#include "OpenMM.h"
#include "TopologyElements.hpp"

// Thin Robosample-owned wrapper around a single OpenMM System/Context (a
// process-wide singleton). One OpenMM system for the whole run.
class OpenMMContext {
    public:
    static auto get() -> OpenMMContext& {
        static OpenMMContext omm;
        return omm;
    }

    auto initialize(const SystemTopology& systemTopology) -> bool;

    void shutdown() {
        integrator.reset();
        context.reset();
        system.reset();
        forceGroupLabels.clear();
        hasVirtualSites = false;
        initialized = false;
    }

    void setVelocitiesToTemperature(double temperature, int seed) {
        ensureInitialized();
        context->setVelocitiesToTemperature(temperature, seed);
    }

    // ---- NCMC alchemy (per-molecule intermolecular decoupling) -------------
    // enableAlchemy stores the decoupled atom range and a flag; the correction
    // force is built in initialize() (which has the SystemTopology). PME/periodic
    // is rejected there. setAlchemicalLambda drives the global "lambda_inter".
    void enableAlchemy(int atomBegin, int atomEnd);
    void setAlchemicalLambda(double lambdaInter);

    [[nodiscard]] auto getPotentialEnergy() const -> double {
        ensureInitialized();
        return potentialEnergy;
    }
    [[nodiscard]] auto getKineticEnergy() const -> double {
        ensureInitialized();
        return kineticEnergy;
    }

    struct ForceGroupEnergy {
        int group = 0;
        std::string name;
        double energy = 0.0; // kJ/mol
    };

    void setSeparateForceGroups(bool enabled) {
        separateForceGroups = enabled;
    }
    [[nodiscard]] auto getSeparateForceGroups() const -> bool {
        return separateForceGroups;
    }

    // Multiple-timestep (r-RESPA) control. When enabled, initialize() builds an
    // MTSIntegrator instead of the single-rate VerletIntegrator: slow forces
    // (Nonbonded, GBSA, NBFIX) go to force group 0 and are evaluated once per
    // outer step; fast bonded forces go to group 1 and are evaluated
    // `innerSubsteps` times. Only affects the Cartesian world's on-device MD
    // (integrateTrajectory); the torsional worlds always get the full force sum.
    // MUST be called before initialize(). innerSubsteps < 2 disables MTS.
    void setMTS(bool enabled, int innerSubsteps) {
        useMTS = enabled && (innerSubsteps >= 2);
        mtsInnerSubsteps = innerSubsteps;
    }
    [[nodiscard]] auto getUseMTS() const -> bool {
        return useMTS;
    }

    void setPositions(const std::vector& positions) {
        ensureInitialized();
        context->setPositions(positions);
        if (hasVirtualSites) {
            context->computeVirtualSites();
        }
    }
    void getPositions(std::vector& out) const {
        ensureInitialized();
        out = context->getState(OpenMM::State::Positions, enforcePeriodicBox).getPositions();
    }

    // Whether OpenMM wraps coordinates into the primary box when we PULL state
    // (positions/forces/energy getState calls). For Robosample this MUST stay
    // false under explicit solvent: the robot engine consumes per-atom positions
    // and rebuilds each molecule's internal frames from contiguous geometry, so a
    // wrapped molecule that straddles a box face would yield a ~box-length "bond"
    // and corrupt the frame build. Energies/forces are unaffected by this flag
    // (OpenMM always applies the minimum image internally); wrapping is purely a
    // representation of the returned positions. Any periodic-image bookkeeping for
    // visualization is done as a WHOLE-MOLECULE rigid translation elsewhere, never
    // here. Default false.
    void setEnforcePeriodicBox(bool v) {
        enforcePeriodicBox = v;
    }
    [[nodiscard]] auto getEnforcePeriodicBox() const -> bool {
        return enforcePeriodicBox;
    }

    // True for the methods that require a periodic box (and thus exclude GBSA).
    [[nodiscard]] static auto isPeriodic(NonbondedMethod m) -> bool {
        return m == NonbondedMethod::CutoffPeriodic || m == NonbondedMethod::Ewald
               || m == NonbondedMethod::PME;
    }

    auto computePotentialEnergy(const std::vector& positions) -> double;
    auto computePotentialEnergyByGroup(const std::vector& positions)
        -> std::pair<double, std::vector>;
    void evaluateForcesFromPositionsCache(const std::vector& positions,
                                          std::vector& outForces) const;
    auto integrateTrajectory(int steps, double timeStepInPicoseconds) -> bool;
    auto computePeriodicBoxVectors_Context(double a_length,
                                           double b_length,
                                           double c_length,
                                           double alpha,
                                           double beta,
                                           double gamma)
        -> std::tuple;

    private:
    OpenMMContext() = default;

    void ensureInitialized() const {
        if (!initialized) {
            throw std::runtime_error("OpenMM subsystem not initialized. Call OpenMMContext::initialize() "
                                     "before using any other functions.");
        }
    }

    [[nodiscard]] auto createNonbondedForce(const SystemTopology& systemTopology) -> OpenMM::NonbondedForce*;
    [[nodiscard]] auto createGBSAOBCForce(const SystemTopology& systemTopology) -> OpenMM::GBSAOBCForce*;
    [[nodiscard]] auto createCustomNonbondedForce(const SystemTopology& systemTopology)
        -> OpenMM::CustomNonbondedForce*;
    // Alchemy correction force: total [begin,end) x rest pair energy becomes
    // lambda_inter * standard (LJ + Coulomb), via a (lambda_inter-1)*standard term
    // over an interaction group. No intermolecular exceptions exist, so no
    // exclusion list is needed (scales to large assemblies).
    [[nodiscard]] auto createAlchemyCorrectionForce(const SystemTopology& systemTopology)
        -> OpenMM::CustomNonbondedForce*;
    [[nodiscard]] auto createHarmonicBondForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicBondForce*;
    [[nodiscard]] auto createHarmonicAngleForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicAngleForce*;
    [[nodiscard]] auto createPeriodicTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::PeriodicTorsionForce*;
    [[nodiscard]] auto createImproperHarmonicTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::CustomTorsionForce*;
    [[nodiscard]] auto createCMAPTorsionForce(const SystemTopology& systemTopology)
        -> OpenMM::CMAPTorsionForce*;
    [[nodiscard]] auto createUreyBradleyForce(const SystemTopology& systemTopology)
        -> OpenMM::HarmonicBondForce*;

    // PME/explicit-solvent NCMC. Reciprocal space cannot be localized to an
    // A x rest pair list, so electrostatics are scaled on the MAIN NonbondedForce
    // via a lambda_inter charge offset (PME-exact), and A's LJ is rebuilt as
    // soft-core A x rest + hard intra-A custom forces. Mutates `main`; returns the
    // two custom forces to add. Driven by the SAME lambda_inter global parameter,
    // so setAlchemicalLambda / ncmcMove need no changes.
    [[nodiscard]] auto createAlchemyDecouplingForces(const SystemTopology& systemTopology,
                                                     OpenMM::NonbondedForce* main)
        -> std::pair;

    std::unique_ptr context;
    std::unique_ptr system;
    std::unique_ptr integrator;

    std::size_t numAtoms = 0;
    double potentialEnergy = 0;
    double kineticEnergy = 0;

    bool separateForceGroups = false;
    std::vector<std::pair> forceGroupLabels;

    // NCMC alchemy state.
    bool alchemyEnabled = false;
    int alchemyBegin = -1;
    int alchemyEnd = -1;
    OpenMM::CustomNonbondedForce* alchemyForce = nullptr; // owned by `system`

    // r-RESPA multiple-timestep state.
    bool useMTS = false;
    int mtsInnerSubsteps = 4;
    static constexpr int kMtsSlowGroup = 0; // Nonbonded, GBSA, NBFIX
    static constexpr int kMtsFastGroup = 1; // bonds, angles, torsions, CMAP, UB

    bool enforcePeriodicBox = false;
    bool hasVirtualSites = false;
    bool initialized = false;
};

#pragma once
// ============================================================================
//  PeriodicBox.hpp -- the OpenMM-free periodic-boundary primitives for explicit
//  solvent: the minimum-image (triclinic wrap) and the reduced box-vector
//  construction.
//
//  SINGLE SOURCE OF TRUTH. The minimum-image wrap was a file-local lambda inside
//  src/Context.cpp's clash scan; the reduced-box-vector construction was the pure
//  body of OpenMMContext::computePeriodicBoxVectors_Context. Both are extracted
//  here verbatim (only wrapped as free functions) so the production code and the
//  unit tests bind the SAME logic -- the hoisting pattern already used for
//  robo_linalg / EngineHelpers. Nothing here touches OpenMM, so it can be unit
//  tested with zero forcefield dependency.
//
//  CONVENTION. Box vectors are REDUCED (lower-triangular):
//      a = (ax, 0,  0 )   b = (bx, by, 0 )   c = (cx, cy, cz)
//  stored as a flat 9-array  bv = [ax,ay,az, bx,by,bz, cx,cy,cz]  (a=[0..2],
//  b=[3..5], c=[6..8]) -- the same layout SystemTopology::boxVectors uses and the
//  order OpenMM reduces them. The diagonal is positive; off-diagonals satisfy the
//  reduction |bx| <= ax/2, |cx| <= ax/2, |cy| <= by/2.
// ============================================================================

#include 
#include 

namespace robo { namespace pbc {

// Reduced lower-triangular box vectors, flat 9-array (a,b,c stacked).
struct BoxVectors {
    std::array v{};

    [[nodiscard]] auto data() const -> const double* {
        return v.data();
    }
    [[nodiscard]] auto data() -> double* {
        return v.data();
    }
};

// Wrap a displacement (dx,dy,dz) to its minimum image in the reduced cell.
// Subtract whole lattice vectors in c -> b -> a order (the same order OpenMM
// reduces them); for a reduced (lower-triangular) cell this single pass yields
// the canonical minimum image. Verbatim port of the src/Context.cpp lambda.
inline void minimumImage(double& dx, double& dy, double& dz, const double* bv) {
    // c then b then a  (bv layout: a=[0..2], b=[3..5], c=[6..8]).
    double n = std::round(dz / bv[8]);
    dx -= n * bv[6];
    dy -= n * bv[7];
    dz -= n * bv[8];
    n = std::round(dy / bv[4]);
    dx -= n * bv[3];
    dy -= n * bv[4];
    n = std::round(dx / bv[0]);
    dx -= n * bv[0];
}

// Minimum-image distance between two points pa, pb (each a 3-array) under bv.
inline double minimumImageDistance(const double* pa, const double* pb, const double* bv) {
    double dx = pa[0] - pb[0];
    double dy = pa[1] - pb[1];
    double dz = pa[2] - pb[2];
    minimumImage(dx, dy, dz, bv);
    return std::sqrt((dx * dx) + (dy * dy) + (dz * dz));
}

// Reduced box vectors from cell lengths and angles (radians). This is the pure
// triclinic construction + lattice reduction OpenMM uses (the body of
// OpenMMContext::computePeriodicBoxVectors_Context, minus the OpenMM types).
//   a along x; b in the xy-plane; c fixed by the three angles; then reduce so the
//   off-diagonals are the smallest images (c -= round(c/.)*., etc.).
inline BoxVectors
reducedBoxVectors(double aLen, double bLen, double cLen, double alpha, double beta, double gamma) {
    constexpr double TOL = 1e-6;
    std::array a{aLen, 0.0, 0.0};
    std::array b{bLen * std::cos(gamma), bLen * std::sin(gamma), 0.0};
    const double cx = cLen * std::cos(beta);
    const double cy = cLen * (std::cos(alpha) - std::cos(beta) * std::cos(gamma)) / std::sin(gamma);
    const double cz = std::sqrt((cLen * cLen) - (cx * cx) - (cy * cy));
    std::array c{cx, cy, cz};

    auto clampSmall = [&](std::array& v) {
        for (int i = 0; i < 3; ++i) {
            if (std::abs(v[static_cast(i)]) < TOL) {
                v[static_cast(i)] = 0.0;
            }
        }
    };
    clampSmall(a);
    clampSmall(b);
    clampSmall(c);

    auto axpy = [](std::array& dst, const std::array& src, double s) {
        dst[0] -= s * src[0];
        dst[1] -= s * src[1];
        dst[2] -= s * src[2];
    };
    if (b[1] != 0.0) {
        axpy(c, b, std::round(c[1] / b[1]));
    }
    if (a[0] != 0.0) {
        axpy(c, a, std::round(c[0] / a[0]));
    }
    if (a[0] != 0.0) {
        axpy(b, a, std::round(b[0] / a[0]));
    }

    BoxVectors out;
    out.v = {a[0], a[1], a[2], b[0], b[1], b[2], c[0], c[1], c[2]};
    return out;
}

// Orthorhombic convenience: a diagonal reduced box of the given side lengths.
inline BoxVectors orthorhombic(double lx, double ly, double lz) {
    BoxVectors out;
    out.v = {lx, 0, 0, 0, ly, 0, 0, 0, lz};
    return out;
}

}} // namespace robo::pbc

#pragma once

// ============================================================================
//  RobotEngine — the SimTK-free dynamics, living in Robosample. Operates on a
//  (const RobotModel&, RobotState&) pair. NO SimTK subsystem/handle types, NO
//  vtables: mobilizer identity is a `switch (model.bodyJoint[b])`, replacing
//  Simbody's RigidBodyNode virtual dispatch.
//
//  EVERY method here is a *faithful port* of a named Simbody routine. The point
//  is behavior preservation: build this beside Simbody, diff each operator to
//  tolerance over random states and every mobilizer type, and only then remove
//  Simbody (MIGRATION_DESIGN.md §6). Bodies are left unimplemented here on
//  purpose — they are transcriptions, not inventions, and must be validated.
//
//  Tree order invariant: model.bodyParent[b] < b. Outward sweep = forward
//  iteration over bodies; inward sweep = reverse iteration. Ground == body 0.
//
//  OpenMP-future: all sweeps are index loops over contiguous SoA; level-parallel
//  variants can later use model.bodyLevel without changing the math. No OpenMP
//  now.
// ============================================================================

#include "ForceBridge.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "robot_math.hpp"

// Forward declaration breaks the Constraints <-> RobotEngine include cycle.
// verletStep takes ConstraintSet only by reference, so an incomplete type is
// enough here; the full definition is pulled in by RobotEngine.cpp.
namespace robo {
class ConstraintSet;
}

class RobotEngine {
    public:
    // ---- KINEMATICS --------------------------------------------------------
    // Port of RigidBodyNodeSpec::realizePosition (RigidBodyNodeSpec.h) +
    // per-joint calcAcrossJointVelocityJacobian (H_FM) + calcBodyTransforms.
    // Outward sweep. Fills X_FM, X_PB, X_GB, Phi, H_FM, H_PB_G, and then the
    // per-atom Ground positions/stations (port of
    // DuMMForceFieldSubsystemRep::realizeSubsystemPositionImpl).
    static void realizePosition(const RobotModel& m, RobotState& s);

    // Port of RigidBodyNodeSpec::realizeVelocity. Fills V_FM, V_GB, Coriolis
    // (AC_GB precursor), gyroscopic terms. Outward sweep.
    static void realizeVelocity(const RobotModel& m, RobotState& s);

    // q-dot from u: per-joint calcQDot / multiplyByN (quaternion coupling for
    // Ball/Free lives here). Port of RigidBodyNodeSpec::calcQDot.
    static void calcQDot(const RobotModel& m, const RobotState& s, robo::Real* qdotOut);
    static void calcQDotDot(const RobotModel& m, RobotState& s);

    // ---- ARTICULATED-BODY DYNAMICS ----------------------------------------
    // Port of realizeArticulatedBodyInertiasInward (RigidBodyNodeSpec.cpp).
    // Inward sweep. Fills P, PPlus, D, DI, G.
    static void realizeArticulatedBodyInertias(const RobotModel& m, RobotState& s);

    // Forward dynamics: forces -> udot. Port of calcUDotPass1Inward (Z, eps,
    // zPlus) + calcUDotPass2Outward (udot, A_GB). Requires bodyForceG +
    // mobilityForce already set (ForceBridge + optional Fixman).
    static void calcUDot(const RobotModel& m, RobotState& s);

    // ---- MASS-MATRIX OPERATORS (no M ever formed) -------------------------
    // Port of multiplyByMInvPass1Inward + multiplyByMInvPass2Outward.
    static void multiplyByMInv(const RobotModel& m, RobotState& s, const robo::Real* in, robo::Real* out);

    // Port of multiplyBySqrtMInvPassOutward (+ inward companion). Used for HMC
    // velocity seeding: u = sqrt(boostRT) * sqrtMInv * gaussian.
    static void multiplyBySqrtMInv(const RobotModel& m, RobotState& s, const robo::Real* in, robo::Real* out);

    // sqrt(M): exact algebraic inverse of multiplyBySqrtMInv (see RobotEngine.cpp).
    // Used by the NMA Route B acceptance to recover the white-noise coordinates
    // w = M^(1/2) u / sqrt(RT) of a trajectory-end velocity. Uses local scratch,
    // so it does NOT disturb s.V_GB() (safe to call alongside calcKineticEnergy).
    static void multiplyBySqrtM(const RobotModel& m, RobotState& s, const robo::Real* in, robo::Real* out);

    // ---- MASS-MATRIX LOG-DETERMINANT (Fixman) -----------------------------
    // ln|M_phi| = sum_b ln det(D_b), the O(n) articulated-body determinant
    // (port of RigidBodyNodeSpec::calcDetMPass2Outward, which accumulates
    //  detM += log(det(D))). Matrix-free: the global nu x nu mass matrix is
    //  NEVER formed; only the per-body dof x dof hinge inertia D_b = ~H P H
    //  (dof <= 6) is built and its determinant taken. REQUIRES
    //  realizeArticulatedBodyInertias to have run first (reads P and H).
    static robo::Real calcLogDetM(const RobotModel& m, const RobotState& s);


    // Port of SimbodyMatterSubsystemRep::calcKineticEnergy ( 1/2 u^T M u ).
    static robo::Real calcKineticEnergy(const RobotModel& m, const RobotState& s);

    // ---- MOBILIZER REACTION FORCES ----------------------------------------
    // Port of SimbodyMatterSubsystemRep::calcMobilizerReactionForces. The
    // reaction on body b is the spatial force its INBOARD mobilizer transmits to
    // it, expressed in Ground. It is obtained by a rigid Newton-Euler inward
    // sweep using the TRUE body accelerations A_GB (so calcUDot must be current):
    //   reac_b@Bo = Mk_b A_GB_b + gyro_b - F_ext_b + sum_children Phi[c] reac_c@Bo
    // where F_ext_b = bodyForceG[b] + (applied mobility force mapped through H).
    // No articulated inertia is used; this is exact rigid force transmission.
    //
    // reactionAtBoInG[b] (length numBodies, [0]=Ground unused) receives the
    // reaction reported AT THE BODY ORIGIN Bo in Ground. Pass nullptr to skip.
    // reactionAtMInG[b] receives the SAME reaction shifted to the outboard
    // mobilizer frame origin Mo in Ground (Simbody's findMobilizerReactionOn-
    // BodyAtMInGround convention): [t;f] at Bo -> [t - p_BoMo_G x f; f] at Mo.
    // Pass nullptr to skip. At least one output must be non-null.
    //
    // PRECONDITION: realizePosition, realizeVelocity, realizeArticulatedBody-
    // Inertias, and calcUDot all current (reads Mk_G, A_GB, gyro, Phi, H,
    // bodyForceG, mobilityForce). Ground (body 0) has no inboard joint; its slot
    // is left zero.
    static void calcMobilizerReactionForces(const RobotModel& m,
                                            const RobotState& s,
                                            robo::SpatialVec* reactionAtBoInG,
                                            robo::SpatialVec* reactionAtMInG);

    // Convenience: the reaction on body b at its M frame origin, in Ground.
    static robo::SpatialVec
    findMobilizerReactionOnBodyAtMInGround(const RobotModel& m, const RobotState& s, int body);

    // ---- INTEGRATOR -------------------------------------------------------
    // Port of VerletIntegrator.cpp::attemptDAEStep, FIXED step. Sequence:
    //   q1 = q0 + h*qdot0 + (h^2/2)*qdotdot0
    //   u1_est = u0 + h*udot0
    //   realizePosition; projectQ (== quaternion renormalization ONLY, no
    //     constraints — see MIGRATION_DESIGN.md §1/§4.3)
    //   realizeVelocity; forces; calcUDot
    //   implicit-trapezoid refine u (<=10 iters): u1 = u0 + (h/2)(udot0+udot1)
    // Advances state by exactly one step h. Returns false if a non-finite force
    // or coordinate appeared during the step (e.g. a hard steric overlap drove an
    // LJ force to Inf); in that case the pre-step q/u are restored so the caller
    // sees a finite, unmodified state to reject from -- never a NaN it must chase.
    template 
    static bool verletStep(const RobotModel& m,
                           RobotState& s,
                           Bridge& bridge,
                           const robo::ConstraintSet& cset,
                           robo::Real h);

    // Drives verletStep until t_end. Port of TimeStepper::stepTo for the fixed-
    // step velocity-Verlet path Robosample uses. Returns success.
    template 
    static bool stepTo(const RobotModel& m,
                       RobotState& s,
                       Bridge& bridge,
                       const robo::ConstraintSet& cset,
                       robo::Real tEnd);

    // Reversibility diagnostic: integrate nSteps forward at step h, flip the
    // momenta, integrate nSteps back, flip again, and return the RELATIVE
    // round-trip residual ||(q,u)_returned - (q,u)_start|| / ||(q,u)_start||.
    // ~machine-eps for a reversible step; O(1) when h is too large. Quaternion
    // DOF use a double-cover-aware distance. NON-DESTRUCTIVE (restores s).
    // NOTE: certifies h only for the configuration it is called from -- the safe
    // h is configuration dependent (M(q), force stiffness), so this is a startup/
    // periodic smoke test, not a whole-run guarantee. The per-step corrector
    // throw in verletStep is the ongoing guard. See THEORY 5.5.
    template 
    static robo::Real checkReversibility(const RobotModel& m,
                                         RobotState& s,
                                         Bridge& bridge,
                                         const robo::ConstraintSet& cset,
                                         int nSteps,
                                         robo::Real h);

    // ---- TRANSFER: internal q/u -> Cartesian (accept path) ----------------
    // Port of the accept-branch loop in HMCSampler::sampleIteration:
    //   atomPosG[a] = X_GB[body].p + X_GB[body].R * station_B[a]
    // Assumes realizePosition has run.
    static void fillAtomPositionsFromBodies(const RobotModel& m, RobotState& s);

    // ---- TRANSFER: Cartesian targets -> internal state --------------------
    // ---- quaternion projection (no-constraint Verlet projection) ----------
    // Renormalizes each quaternion q-block listed in model.quaternionQStart.
    static void normalizeQuaternions(const RobotModel& m, RobotState& s);

    // NOTE: the per-joint kernels (X_FM, H_FM, qdot, qddot) are transcribed
    // inline inside realizePosition / realizeVelocity / calcQDot[Dot] rather
    // than as separate static helpers, so there are no extra symbols to define.
};

