namespace robo {

using Real = double;

inline constexpr Real Pi = Real(3.14159265358979323846);
inline constexpr Real Deg2Rad = Pi / Real(180);

// coordinate axes (unscoped so `XAxis` etc. read like the SimTK names)
enum CoordinateAxis : int {
    XAxis = 0,
    YAxis = 1,
    ZAxis = 2
};

// ---------------------------------------------------------------------------
//  Vec3
// ---------------------------------------------------------------------------
struct alignas(8) Vec3 {
    std::array elems;

    Vec3() = default;
    constexpr explicit Vec3(Real fill)
        : elems{fill, fill, fill} {
    }
    constexpr Vec3(Real valX, Real valY, Real valZ)
        : elems{valX, valY, valZ} {
    }

    constexpr auto operator[](int idx) -> Real& {
        return elems[static_cast(idx)];
    }
    constexpr auto operator[](int idx) const -> Real {
        return elems[static_cast(idx)];
    }

    constexpr auto operator+(const Vec3& rhs) const -> Vec3 {
        return {elems[0] + rhs.elems[0], elems[1] + rhs.elems[1], elems[2] + rhs.elems[2]};
    }
    constexpr auto operator-(const Vec3& rhs) const -> Vec3 {
        return {elems[0] - rhs.elems[0], elems[1] - rhs.elems[1], elems[2] - rhs.elems[2]};
    }
    constexpr auto operator*(Real scalar) const -> Vec3 {
        return {elems[0] * scalar, elems[1] * scalar, elems[2] * scalar};
    }
    constexpr auto operator/(Real scalar) const -> Vec3 {
        return {elems[0] / scalar, elems[1] / scalar, elems[2] / scalar};
    }
    constexpr auto operator+=(const Vec3& rhs) -> Vec3& {
        elems[0] += rhs.elems[0];
        elems[1] += rhs.elems[1];
        elems[2] += rhs.elems[2];
        return *this;
    }
    constexpr auto operator-=(const Vec3& rhs) -> Vec3& {
        elems[0] -= rhs.elems[0];
        elems[1] -= rhs.elems[1];
        elems[2] -= rhs.elems[2];
        return *this;
    }
    constexpr auto operator%(const Vec3& rhs) const -> Vec3 { // cross product
        return {(elems[1] * rhs.elems[2]) - (elems[2] * rhs.elems[1]),
                (elems[2] * rhs.elems[0]) - (elems[0] * rhs.elems[2]),
                (elems[0] * rhs.elems[1]) - (elems[1] * rhs.elems[0])};
    }
    [[nodiscard]] auto norm() const -> Real {
        return std::sqrt(normSqr());
    }
    [[nodiscard]] constexpr auto normSqr() const -> Real {
        return (elems[0] * elems[0]) + (elems[1] * elems[1]) + (elems[2] * elems[2]);
    }
};
constexpr auto dot(const Vec3& lhs, const Vec3& rhs) -> Real {
    return (lhs.elems[0] * rhs.elems[0]) + (lhs.elems[1] * rhs.elems[1]) + (lhs.elems[2] * rhs.elems[2]);
}
constexpr auto operator*(Real scalar, const Vec3& vec) -> Vec3 {
    return vec * scalar;
}

// ---------------------------------------------------------------------------
//  Mat33 (row-major). Non-aggregate: diagonal ctor + 9-element ctor.
// ---------------------------------------------------------------------------
struct Mat33 {
    std::array elems; // row-major: elems[(row*3)+col]

    Mat33() = default;
    explicit constexpr Mat33(Real diag)
        : elems{diag, 0, 0, 0, diag, 0, 0, 0, diag} {
    }
    constexpr Mat33(Real m00, Real m01, Real m02, Real m10, Real m11, Real m12, Real m20, Real m21, Real m22)
        : elems{m00, m01, m02, m10, m11, m12, m20, m21, m22} {
    }

    static constexpr auto identity() -> Mat33 {
        return Mat33(Real(1));
    }
    static constexpr auto zero() -> Mat33 {
        return Mat33(Real(0));
    }

    constexpr auto operator()(int row, int col) -> Real& {
        return elems[static_cast((row * 3) + col)];
    }
    constexpr auto operator()(int row, int col) const -> Real {
        return elems[static_cast((row * 3) + col)];
    }

    constexpr auto operator*(const Vec3& vec) const -> Vec3 {
        return {(elems[0] * vec[0]) + (elems[1] * vec[1]) + (elems[2] * vec[2]),
                (elems[3] * vec[0]) + (elems[4] * vec[1]) + (elems[5] * vec[2]),
                (elems[6] * vec[0]) + (elems[7] * vec[1]) + (elems[8] * vec[2])};
    }
    [[nodiscard]] constexpr auto transposeTimes(const Vec3& vec) const -> Vec3 {
        return {(elems[0] * vec[0]) + (elems[3] * vec[1]) + (elems[6] * vec[2]),
                (elems[1] * vec[0]) + (elems[4] * vec[1]) + (elems[7] * vec[2]),
                (elems[2] * vec[0]) + (elems[5] * vec[1]) + (elems[8] * vec[2])};
    }
    constexpr auto operator+(const Mat33& rhs) const -> Mat33 {
        return Mat33(elems[0] + rhs.elems[0],
                     elems[1] + rhs.elems[1],
                     elems[2] + rhs.elems[2],
                     elems[3] + rhs.elems[3],
                     elems[4] + rhs.elems[4],
                     elems[5] + rhs.elems[5],
                     elems[6] + rhs.elems[6],
                     elems[7] + rhs.elems[7],
                     elems[8] + rhs.elems[8]);
    }
    constexpr auto operator-(const Mat33& rhs) const -> Mat33 {
        return Mat33(elems[0] - rhs.elems[0],
                     elems[1] - rhs.elems[1],
                     elems[2] - rhs.elems[2],
                     elems[3] - rhs.elems[3],
                     elems[4] - rhs.elems[4],
                     elems[5] - rhs.elems[5],
                     elems[6] - rhs.elems[6],
                     elems[7] - rhs.elems[7],
                     elems[8] - rhs.elems[8]);
    }
    constexpr auto operator*(const Mat33& rhs) const -> Mat33 {
        Mat33 out(Real(0));
        for (int row = 0; row < 3; ++row) {
            for (int col = 0; col < 3; ++col) {
                out(row, col) = ((*this)(row, 0) * rhs(0, col)) + ((*this)(row, 1) * rhs(1, col))
                                + ((*this)(row, 2) * rhs(2, col));
            }
        }
        return out;
    }
    constexpr auto operator*(Real scalar) const -> Mat33 {
        return Mat33(elems[0] * scalar,
                     elems[1] * scalar,
                     elems[2] * scalar,
                     elems[3] * scalar,
                     elems[4] * scalar,
                     elems[5] * scalar,
                     elems[6] * scalar,
                     elems[7] * scalar,
                     elems[8] * scalar);
    }
    [[nodiscard]] constexpr auto transpose() const -> Mat33 {
        return Mat33(elems[0],
                     elems[3],
                     elems[6],
                     elems[1],
                     elems[4],
                     elems[7],
                     elems[2],
                     elems[5],
                     elems[8]);
    }
};

constexpr auto crossMat(const Vec3& vec) -> Mat33 { // crossMat(v)*x == v % x
    return Mat33(0, -vec[2], vec[1], vec[2], 0, -vec[0], -vec[1], vec[0], 0);
}

// ---------------------------------------------------------------------------
//  UnitVec3 (normalized on construction)
// ---------------------------------------------------------------------------
struct UnitVec3 {
    Vec3 dir{0, 0, 1};

    UnitVec3() = default;
    explicit UnitVec3(const Vec3& vec) {
        const Real len = vec.norm();
        dir = (len > Real(1e-300)) ? (vec / len) : Vec3(0, 0, 1);
    }
    [[nodiscard]] auto asVec3() const -> const Vec3& {
        return dir;
    }
    operator const Vec3&() const {
        return dir;
    } // NOLINT(google-explicit-constructor): a UnitVec3 IS-A Vec3
    constexpr auto operator[](int idx) const -> Real {
        return dir[idx];
    }
};

// ---------------------------------------------------------------------------
//  Vec4 (raw quaternion storage / qdot result)
// ---------------------------------------------------------------------------
struct alignas(8) Vec4 {
    std::array elems;

    Vec4() = default;
    constexpr Vec4(Real valW, Real valX, Real valY, Real valZ)
        : elems{valW, valX, valY, valZ} {
    }
    constexpr auto operator[](int idx) -> Real& {
        return elems[static_cast(idx)];
    }
    constexpr auto operator[](int idx) const -> Real {
        return elems[static_cast(idx)];
    }
};

// ---------------------------------------------------------------------------
//  Parent-frame quaternion kinematic map  qdot = N(q) * w_FM   (THEORY S3.4).
//
//  INTENDED BEHAVIOR: q represents R_FM (body orientation in the parent frame
//  F), built by Rotation::fromQuaternion as the STANDARD map. The engine's
//  generalized angular speed w_FM is expressed in F. The matching qdot map is
//  therefore the PARENT-frame map (left Hamilton product, qdot = 1/2 (0,w) (x) q):
//
//      qdot_w = 1/2 ( -qx*wx - qy*wy - qz*wz )
//      qdot_x = 1/2 (  qw*wx + qz*wy - qy*wz )
//      qdot_y = 1/2 ( -qz*wx + qw*wy + qx*wz )
//      qdot_z = 1/2 (  qy*wx - qx*wy + qw*wz )
//
//  This is exactly Simbody's calcUnnormalizedNForQuaternion. The body-frame map
//  (right product, q (x) (0,w)) negates the off-diagonal cross terms and assumes
//  w in M; pairing it with the standard R_FM advances the orientation with a
//  wrong-handed angular velocity and pumps kinetic energy (conflict C-4, fixed).
//
//  SINGLE SOURCE OF TRUTH: both Quat::angVelToQdot and
//  Rotation::convertAngVelToQuaternionDot delegate here, so the two cannot
//  silently diverge -- the duplication is what let C-4 hide under
//  self-consistency.
inline auto quaternionDotFromAngVel(Real qw, Real qx, Real qy, Real qz, const Vec3& w) -> Vec4 {
    return Vec4(Real(0.5) * ((-qx * w[0]) - (qy * w[1]) - (qz * w[2])),
                Real(0.5) * ((qw * w[0]) + (qz * w[1]) - (qy * w[2])),
                Real(0.5) * ((-qz * w[0]) + (qw * w[1]) + (qx * w[2])),
                Real(0.5) * ((qy * w[0]) - (qx * w[1]) + (qw * w[2])));
}

// ---------------------------------------------------------------------------
//  Quaternion (w, x, y, z). q represents R_FM; angVel is w_FM in F (== u[0..2]).
//  qdot = N(q) * w (parent-frame, see quaternionDotFromAngVel above).
// ---------------------------------------------------------------------------
struct Quat {
    std::array elems; // w, x, y, z

    Quat() = default;
    constexpr Quat(Real valW, Real valX, Real valY, Real valZ)
        : elems{valW, valX, valY, valZ} {
    }
    explicit Quat(const Vec4& raw)
        : elems{raw[0], raw[1], raw[2], raw[3]} {
        normalize();
    }

    [[nodiscard]] auto norm() const -> Real {
        return std::sqrt((elems[0] * elems[0]) + (elems[1] * elems[1]) + (elems[2] * elems[2])
                         + (elems[3] * elems[3]));
    }
    auto normalize() -> void {
        const Real len = norm();
        if (len > Real(1e-12)) {
            const Real inv = Real(1) / len;
            for (Real& comp : elems) {
                comp *= inv;
            }
        } else {
            elems = {1, 0, 0, 0};
        }
    }
    static auto angVelToQdot(const Quat& quat, const Vec3& angVel) -> Quat {
        const Vec4 d =
            quaternionDotFromAngVel(quat.elems[0], quat.elems[1], quat.elems[2], quat.elems[3], angVel);
        return Quat(d[0], d[1], d[2], d[3]);
    }
};
using Quaternion = Quat; // SimTK-compatible name

// ---------------------------------------------------------------------------
//  SymMat33. Storage order matches the engine's 6-arg ctor: (xx, xy, yy, xz, yz, zz).
//      full = [[xx xy xz],[xy yy yz],[xz yz zz]]
// ---------------------------------------------------------------------------
struct Rotation; // fwd: needed by SymMat33::reexpress

struct SymMat33 {
    std::array elems; // xx, xy, yy, xz, yz, zz

    SymMat33() = default;
    // SimTK-compatible 6-arg order (xx, xy, yy, xz, yz, zz)
    constexpr SymMat33(Real exx, Real exy, Real eyy, Real exz, Real eyz, Real ezz)
        : elems{exx, exy, eyy, exz, eyz, ezz} {
    }
    // diagonal moments (UnitInertia(xx, yy, zz))
    constexpr SymMat33(Real exx, Real eyy, Real ezz)
        : elems{exx, 0, eyy, 0, 0, ezz} {
    }

    static constexpr auto zero() -> SymMat33 {
        return SymMat33(Real(0), Real(0), Real(0), Real(0), Real(0), Real(0));
    }
    static constexpr auto diagonal(Real value) -> SymMat33 {
        return SymMat33(value, value, value);
    }

    constexpr auto operator*(const Vec3& vec) const -> Vec3 {
        return {(elems[0] * vec[0]) + (elems[1] * vec[1]) + (elems[3] * vec[2]),
                (elems[1] * vec[0]) + (elems[2] * vec[1]) + (elems[4] * vec[2]),
                (elems[3] * vec[0]) + (elems[4] * vec[1]) + (elems[5] * vec[2])};
    }
    constexpr auto operator*(Real scalar) const -> SymMat33 {
        return SymMat33(elems[0] * scalar,
                        elems[1] * scalar,
                        elems[2] * scalar,
                        elems[3] * scalar,
                        elems[4] * scalar,
                        elems[5] * scalar);
    }
    constexpr auto operator+(const SymMat33& rhs) const -> SymMat33 {
        return SymMat33(elems[0] + rhs.elems[0],
                        elems[1] + rhs.elems[1],
                        elems[2] + rhs.elems[2],
                        elems[3] + rhs.elems[3],
                        elems[4] + rhs.elems[4],
                        elems[5] + rhs.elems[5]);
    }
    constexpr auto operator-(const SymMat33& rhs) const -> SymMat33 {
        return SymMat33(elems[0] - rhs.elems[0],
                        elems[1] - rhs.elems[1],
                        elems[2] - rhs.elems[2],
                        elems[3] - rhs.elems[3],
                        elems[4] - rhs.elems[4],
                        elems[5] - rhs.elems[5]);
    }
    constexpr auto operator+=(const SymMat33& rhs) -> SymMat33& {
        for (std::size_t idx = 0; idx < 6; ++idx) {
            elems[idx] += rhs.elems[idx];
        }
        return *this;
    }
    [[nodiscard]] constexpr auto full() const -> Mat33 {
        return Mat33(elems[0],
                     elems[1],
                     elems[3],
                     elems[1],
                     elems[2],
                     elems[4],
                     elems[3],
                     elems[4],
                     elems[5]);
    }
    static constexpr auto fromSymmetricPart(const Mat33& mat) -> SymMat33 {
        return SymMat33(mat(0, 0),
                        (mat(1, 0) + mat(0, 1)) / 2,
                        mat(1, 1),
                        (mat(2, 0) + mat(0, 2)) / 2,
                        (mat(2, 1) + mat(1, 2)) / 2,
                        mat(2, 2));
    }
    // re-express in a rotated frame: ~rot * (*this) * rot (SimTK convention). Defined after Rotation.
    [[nodiscard]] auto reexpress(const Rotation& rot) const -> SymMat33;
};
using UnitInertia = SymMat33; // inertia per unit mass about a point

// ---------------------------------------------------------------------------
//  Rotation: orthonormal Mat33 with assorted constructors / setters.
// ---------------------------------------------------------------------------
struct Rotation : Mat33 {
    Rotation()
        : Mat33(Real(1)) {
    }
    Rotation(const Mat33& mat)
        : Mat33(mat) {
    } // NOLINT(google-explicit-constructor): Rotation IS-A Mat33
    Rotation(Real angle, CoordinateAxis axis) {
        setRotationFromAngleAboutAxis(angle, axis);
    }
    Rotation(const UnitVec3& primaryDir,
             CoordinateAxis primaryAxis,
             const Vec3& planeVec,
             CoordinateAxis planeAxis) {
        setRotationFromTwoAxes(primaryDir, primaryAxis, planeVec, planeAxis);
    }

    auto setColumn(int col, const Vec3& vec) -> void {
        elems[static_cast(col)] = vec[0];
        elems[static_cast(3 + col)] = vec[1];
        elems[static_cast(6 + col)] = vec[2];
    }

    auto setRotationFromAngleAboutAxis(Real angle, CoordinateAxis axis) -> void {
        const Real cosA = std::cos(angle);
        const Real sinA = std::sin(angle);
        switch (axis) {
            case XAxis:
                elems = {1, 0, 0, 0, cosA, -sinA, 0, sinA, cosA};
                break;
            case YAxis:
                elems = {cosA, 0, sinA, 0, 1, 0, -sinA, 0, cosA};
                break;
            case ZAxis:
            default:
                elems = {cosA, -sinA, 0, sinA, cosA, 0, 0, 0, 1};
                break;
        }
    }
    auto setRotationFromAngleAboutZ(Real angle) -> void {
        setRotationFromAngleAboutAxis(angle, ZAxis);
    }
    auto setRotationFromQuaternion(const Quat& quat) -> void {
        *this = fromQuaternion(quat);
    }

    // place `dir` on coordinate axis `axis`; complete with an arbitrary orthonormal pair.
    auto setRotationFromOneAxis(const UnitVec3& dir, CoordinateAxis axis) -> void {
        const int idx1 = static_cast(axis);
        const int idx2 = (idx1 + 1) % 3;
        const int idx3 = (idx1 + 2) % 3;
        const Vec3 col1 = dir.asVec3();
        const Vec3 col2 = anyUnitPerpendicular(col1);
        const Vec3 col3 = col1 % col2; // (idx1,idx2,idx3) cyclic -> col1 x col2 = col3
        setColumn(idx1, col1);
        setColumn(idx2, col2);
        setColumn(idx3, col3);
    }

    // primaryAxis aligned to primaryDir; planeAxis as close to planeVec as possible.
    auto setRotationFromTwoAxes(const UnitVec3& primaryDir,
                                CoordinateAxis primaryAxis,
                                const Vec3& planeVec,
                                CoordinateAxis planeAxis) -> void {
        const int idxU = static_cast(primaryAxis);
        const int idxV = static_cast(planeAxis);
        const int idxW = 3 - idxU - idxV;
        const Vec3 colU = primaryDir.asVec3();
        const Vec3 perp = planeVec - (colU * dot(planeVec, colU)); // Gram-Schmidt toward planeVec
        const Real perpNorm = perp.norm();
        const Vec3 colV = (perpNorm > Real(1e-12)) ? (perp / perpNorm) : anyUnitPerpendicular(colU);
        const bool cyclic = (idxV == ((idxU + 1) % 3));
        const Vec3 colW = cyclic ? (colU % colV) : (colV % colU);
        setColumn(idxU, colU);
        setColumn(idxV, colV);
        setColumn(idxW, colW);
    }

    [[nodiscard]] auto operator~() const -> Rotation {
        return Rotation(transpose());
    }

    static auto fromQuaternion(const Quat& source) -> Rotation {
        Quat normalized = source;
        normalized.normalize();
        const Real qw = normalized.elems[0];
        const Real qx = normalized.elems[1];
        const Real qy = normalized.elems[2];
        const Real qz = normalized.elems[3];
        Rotation rot;
        rot.elems = {1 - (2 * ((qy * qy) + (qz * qz))),
                     2 * ((qx * qy) - (qw * qz)),
                     2 * ((qx * qz) + (qw * qy)),
                     2 * ((qx * qy) + (qw * qz)),
                     1 - (2 * ((qx * qx) + (qz * qz))),
                     2 * ((qy * qz) - (qw * qx)),
                     2 * ((qx * qz) - (qw * qy)),
                     2 * ((qy * qz) + (qw * qx)),
                     1 - (2 * ((qx * qx) + (qy * qy)))};
        return rot;
    }

    // qdot = N(quat) * angVel, parent-frame map (SimTK calcUnnormalizedNForQuaternion).
    // Delegates to the shared quaternionDotFromAngVel (single source of truth).
    static auto convertAngVelToQuaternionDot(const Vec4& quat, const Vec3& angVel) -> Vec4 {
        return quaternionDotFromAngVel(quat[0], quat[1], quat[2], quat[3], angVel);
    }
    static auto convertAngVelToQuaternionDot(const Quat& quat, const Vec3& angVel) -> Vec4 {
        return convertAngVelToQuaternionDot(Vec4(quat.elems[0], quat.elems[1], quat.elems[2], quat.elems[3]),
                                            angVel);
    }
    // qddot = N*angVelDot + Ndot*angVel ; Ndot built from qdot = N*angVel (N linear in q).
    static auto
    convertAngVelDotToQuaternionDotDot(const Vec4& quat, const Vec3& angVel, const Vec3& angVelDot) -> Vec4 {
        const Vec4 termA = convertAngVelToQuaternionDot(quat, angVelDot);
        const Vec4 qdot = convertAngVelToQuaternionDot(quat, angVel);
        const Vec4 termB = convertAngVelToQuaternionDot(qdot, angVel);
        return Vec4(termA[0] + termB[0], termA[1] + termB[1], termA[2] + termB[2], termA[3] + termB[3]);
    }

    private:
    static auto anyUnitPerpendicular(const Vec3& vec) -> Vec3 {
        const Real absX = std::abs(vec[0]);
        const Real absY = std::abs(vec[1]);
        const Real absZ = std::abs(vec[2]);
        const Vec3 reference = (absX <= absY && absX <= absZ) ? Vec3(1, 0, 0)
                               : (absY <= absZ)               ? Vec3(0, 1, 0)
                                                              : Vec3(0, 0, 1);
        const Vec3 perp = vec % reference;
        const Real len = perp.norm();
        return (len > Real(1e-12)) ? (perp / len) : Vec3(1, 0, 0);
    }
};

inline auto SymMat33::reexpress(const Rotation& rot) const -> SymMat33 {
    const Mat33 rotated = (rot.transpose() * full()) * rot; // ~R * I * R
    return SymMat33::fromSymmetricPart(rotated);
}

// free dihedral angle (radians), SimTK::calcDihedralAngle(a, b, c, d)
inline auto calcDihedralAngle(const Vec3& atomA, const Vec3& atomB, const Vec3& atomC, const Vec3& atomD)
    -> Real {
    const Vec3 edge1 = atomB - atomA;
    const Vec3 edge2 = atomC - atomB;
    const Vec3 edge3 = atomD - atomC;
    const Vec3 normal1 = edge1 % edge2;
    const Vec3 normal2 = edge2 % edge3;
    const Vec3 frame = normal1 % (edge2 / (edge2.norm() + Real(1e-300)));
    return std::atan2(dot(frame, normal2), dot(normal1, normal2));
}

// ---------------------------------------------------------------------------
//  Transform: rotation + translation, X_AB (frame B expressed in A).
// ---------------------------------------------------------------------------
struct Transform {
    Rotation rot;
    Vec3 trans{0, 0, 0};

    Transform()
        : rot(Mat33::identity()) {
    }
    Transform(const Rotation& rotation, const Vec3& translation)
        : rot(rotation)
        , trans(translation) {
    }
    explicit Transform(const Rotation& rotation)
        : rot(rotation) {
    }
    explicit Transform(const Vec3& translation)
        : rot(Mat33::identity())
        , trans(translation) {
    }

    [[nodiscard]] auto p() const -> const Vec3& {
        return trans;
    }
    [[nodiscard]] auto p() -> Vec3& {
        return trans;
    }
    [[nodiscard]] auto R() const -> const Rotation& {
        return rot;
    }
    [[nodiscard]] auto R() -> Rotation& {
        return rot;
    }

    auto operator*(const Transform& rhs) const -> Transform {
        return Transform{Rotation(rot * rhs.rot), (rot * rhs.trans) + trans};
    }
    auto operator*(const Vec3& point) const -> Vec3 {
        return (rot * point) + trans;
    }
    [[nodiscard]] auto inverse() const -> Transform {
        const Mat33 rotT = rot.transpose();
        return Transform{Rotation(rotT), Vec3(0) - (rotT * trans)};
    }
    [[nodiscard]] auto operator~() const -> Transform {
        return inverse();
    }
};

// ---------------------------------------------------------------------------
//  SpatialVec : 6-vector [angular; linear]. Index [0]=angular, [1]=linear.
// ---------------------------------------------------------------------------
struct SpatialVec {
    Vec3 angular;
    Vec3 linear;

    SpatialVec() = default;
    SpatialVec(const Vec3& angularPart, const Vec3& linearPart)
        : angular(angularPart)
        , linear(linearPart) {
    }

    auto operator[](int idx) -> Vec3& {
        return idx == 0 ? angular : linear;
    }
    auto operator[](int idx) const -> const Vec3& {
        return idx == 0 ? angular : linear;
    }

    auto operator+(const SpatialVec& rhs) const -> SpatialVec {
        return {angular + rhs.angular, linear + rhs.linear};
    }
    auto operator-(const SpatialVec& rhs) const -> SpatialVec {
        return {angular - rhs.angular, linear - rhs.linear};
    }
    auto operator*(Real scalar) const -> SpatialVec {
        return {angular * scalar, linear * scalar};
    }
    auto operator+=(const SpatialVec& rhs) -> SpatialVec& {
        angular += rhs.angular;
        linear += rhs.linear;
        return *this;
    }
};
inline auto dot(const SpatialVec& lhs, const SpatialVec& rhs) -> Real {
    return dot(lhs.angular, rhs.angular) + dot(lhs.linear, rhs.linear);
}
inline auto operator*(Real scalar, const SpatialVec& vec) -> SpatialVec {
    return vec * scalar;
}

// ---------------------------------------------------------------------------
//  Inertia: full 2nd mass moment about a point. SimTK Inertia(p, m) / Inertia(0).
// ---------------------------------------------------------------------------
struct Inertia {
    SymMat33 moments{SymMat33::zero()};

    Inertia() = default;
    explicit Inertia(Real uniformMoment)
        : moments(SymMat33::diagonal(uniformMoment)) {
    }
    Inertia(const Vec3& point, Real pointMass)
        : moments(pointMassInertia(point, pointMass)) {
    }

    auto operator+=(const Inertia& rhs) -> Inertia& {
        moments += rhs.moments;
        return *this;
    }
    auto operator+(const Inertia& rhs) const -> Inertia {
        Inertia out;
        out.moments = moments + rhs.moments;
        return out;
    }
    [[nodiscard]] auto asSymMat33() const -> const SymMat33& {
        return moments;
    }

    private:
    static auto pointMassInertia(const Vec3& point, Real pointMass) -> SymMat33 {
        const Real posX = point[0];
        const Real posY = point[1];
        const Real posZ = point[2];
        // I = m * (|p|^2 I3 - p p^T); arg order (xx, xy, yy, xz, yz, zz)
        return SymMat33(pointMass * ((posY * posY) + (posZ * posZ)),
                        pointMass * (-(posX * posY)),
                        pointMass * ((posX * posX) + (posZ * posZ)),
                        pointMass * (-(posX * posZ)),
                        pointMass * (-(posY * posZ)),
                        pointMass * ((posX * posX) + (posY * posY)));
    }
};

// ---------------------------------------------------------------------------
//  SpatialInertia: rigid-body spatial inertia about the body origin.
//  Mk_G = SpatialInertia(mass, p_BBc_G, G_Bo_G).  Block form (about origin):
//      [[mass*G, mass*crossMat(com)], [~., mass*I]].
// ---------------------------------------------------------------------------
struct SpatialInertia {
    Real mass{0};
    Vec3 com{0, 0, 0};                         // p_BBc (origin -> COM)
    UnitInertia unitInertia{SymMat33::zero()}; // G about origin

    SpatialInertia() = default;
    SpatialInertia(Real bodyMass, const Vec3& massCenter, const UnitInertia& gyration)
        : mass(bodyMass)
        , com(massCenter)
        , unitInertia(gyration) {
    }

    [[nodiscard]] auto getMass() const -> Real {
        return mass;
    }
    [[nodiscard]] auto getMassCenter() const -> const Vec3& {
        return com;
    }
    [[nodiscard]] auto getUnitInertia() const -> const UnitInertia& {
        return unitInertia;
    }

    // spatial momentum = M_spatial * spatial velocity. Defined after ArticulatedInertia.
    [[nodiscard]] auto operator*(const SpatialVec& vel) const -> SpatialVec;
};

// ---------------------------------------------------------------------------
//  ArticulatedInertia: symmetric 6x6 in 3 blocks
//      P = [[angAng, angLin],[~angLin, linLin]]
//      out.angular = angAng*w + angLin*v ;  out.linear = ~angLin*w + linLin*v
//  Engine ctor order: (mass=linLin, massMoment=angLin, inertia=angAng).
// ---------------------------------------------------------------------------
struct ArticulatedInertia {
    SymMat33 angAng{SymMat33::zero()}; // J
    Mat33 angLin{Mat33::zero()};       // F
    SymMat33 linLin{SymMat33::zero()}; // M

    ArticulatedInertia() = default;
    ArticulatedInertia(const SymMat33& massBlock, const Mat33& momentBlock, const SymMat33& inertiaBlock)
        : angAng(inertiaBlock)
        , angLin(momentBlock)
        , linLin(massBlock) {
    }
    explicit ArticulatedInertia(const SpatialInertia& spatial)
        : angAng(spatial.unitInertia * spatial.mass)
        , angLin(crossMat(spatial.com) * spatial.mass)
        , linLin(SymMat33::diagonal(spatial.mass)) {
    }

    auto operator+=(const ArticulatedInertia& rhs) -> ArticulatedInertia& {
        angAng += rhs.angAng;
        angLin = angLin + rhs.angLin;
        linLin += rhs.linLin;
        return *this;
    }
    auto operator-(const ArticulatedInertia& rhs) const -> ArticulatedInertia {
        ArticulatedInertia out;
        out.angAng = angAng - rhs.angAng;
        out.angLin = angLin - rhs.angLin;
        out.linLin = linLin - rhs.linLin;
        return out;
    }
    auto operator*(const SpatialVec& vec) const -> SpatialVec {
        return {(angAng * vec.angular) + (angLin * vec.linear),
                angLin.transposeTimes(vec.angular) + (linLin * vec.linear)};
    }

    // shift to a point `offset` away: Phi(offset) * P * ~Phi(offset).
    [[nodiscard]] auto shift(const Vec3& offset) const -> ArticulatedInertia {
        const Mat33 skew = crossMat(offset);
        const Mat33 massFull = linLin.full();
        const Mat33 momentFull = angLin;
        const Mat33 newMoment = momentFull + (skew * massFull);
        const Mat33 term1 = skew * momentFull.transpose(); // sx * ~F
        const Mat33 term2 = momentFull * skew;             // F * sx
        const Mat33 term3 = (skew * massFull) * skew;      // sx * M * sx
        const Mat33 newInertiaFull = (angAng.full() + term1) - (term2 + term3);
        ArticulatedInertia out;
        out.linLin = linLin;
        out.angLin = newMoment;
        out.angAng = SymMat33::fromSymmetricPart(newInertiaFull);
        return out;
    }
};

inline auto SpatialInertia::operator*(const SpatialVec& vel) const -> SpatialVec {
    return ArticulatedInertia(*this) * vel; // identical block math, single source of truth
}

// ---------------------------------------------------------------------------
//  PhiMatrix: rigid shift with offset l() (parent origin -> child).
//      Phi(l)  * [a; b] = [a + l x b; b]
//      ~Phi(l) * [a; b] = [a; b + a x l]
// ---------------------------------------------------------------------------
struct PhiMatrixTranspose;

struct PhiMatrix {
    Vec3 offset{0, 0, 0}; // l()

    PhiMatrix() = default;
    explicit PhiMatrix(const Vec3& location)
        : offset(location) {
    }

    [[nodiscard]] auto l() const -> const Vec3& {
        return offset;
    }
    auto operator*(const SpatialVec& vec) const -> SpatialVec {
        return {vec.angular + (offset % vec.linear), vec.linear};
    }
    [[nodiscard]] auto operator~() const -> PhiMatrixTranspose;
};

struct PhiMatrixTranspose {
    Vec3 offset{0, 0, 0};
    auto operator*(const SpatialVec& vec) const -> SpatialVec {
        return {vec.angular, vec.linear + (vec.angular % offset)};
    }
};

inline auto PhiMatrix::operator~() const -> PhiMatrixTranspose {
    return PhiMatrixTranspose{offset};
}

// ---------------------------------------------------------------------------
//  MassProperties: mass + COM + unit inertia.
// ---------------------------------------------------------------------------
struct MassProperties {
    Real mass{0};
    Vec3 com{0, 0, 0};
    UnitInertia unitInertia{SymMat33::zero()};

    MassProperties() = default;
    MassProperties(Real bodyMass, const Vec3& massCenter, const UnitInertia& gyration)
        : mass(bodyMass)
        , com(massCenter)
        , unitInertia(gyration) {
    }
    // from a FULL inertia: store unit inertia = inertia / mass.
    MassProperties(Real bodyMass, const Vec3& massCenter, const Inertia& inertia)
        : mass(bodyMass)
        , com(massCenter)
        , unitInertia(bodyMass > Real(0) ? inertia.asSymMat33() * (Real(1) / bodyMass) : SymMat33::zero()) {
    }

    [[nodiscard]] auto getMass() const -> Real {
        return mass;
    }
    [[nodiscard]] auto getMassCenter() const -> const Vec3& {
        return com;
    }
    [[nodiscard]] auto getUnitInertia() const -> const UnitInertia& {
        return unitInertia;
    }

    // SimTK MassProperties::reexpress(R_BC): com' = ~R_BC*com, inertia' = unitInertia.reexpress(R_BC).
    [[nodiscard]] auto reexpress(const Rotation& rotation) const -> MassProperties {
        return MassProperties{mass, rotation.transpose() * com, unitInertia.reexpress(rotation)};
    }
    [[nodiscard]] auto toSpatialInertia() const -> SpatialInertia {
        return SpatialInertia{mass, com, unitInertia};
    }
};

// slab-safety (the MemoryArena frees without running destructors)
static_assert(sizeof(Vec3) == 3 * sizeof(Real), "Vec3 layout");
static_assert(sizeof(SpatialVec) == 6 * sizeof(Real), "SpatialVec layout");
static_assert(std::is_trivially_destructible::value, "Vec3 trivially destructible");
static_assert(std::is_trivially_destructible::value, "SpatialVec trivially destructible");
static_assert(std::is_trivially_destructible::value, "Transform trivially destructible");
static_assert(std::is_trivially_destructible::value,
              "ArticulatedInertia trivially destructible");
static_assert(std::is_trivially_destructible::value, "MassProperties trivially destructible");

} // namespace robo

#pragma once

// ============================================================================
//  RobotModel — the immutable, precomputed, per-World graph. Built ONCE in
//  World::build() from the SoA SystemTopology + this world's per-bond
//  mobilities. Never rebuilt on a coordinate transfer (this is what kills the
//  per-transfer realizeTopology() cost in the current code).
//
//  This is a faithful SoA port of what World currently precomputes across
//  decomposeRigidUnits / buildFrameGraph / modelOneCompound / modelTopologies,
//  with the joint frames and mass properties stored as CONSTANTS rather than
//  Simbody topology-stage defaults.
//
//  SoA, no vtables. Joint identity is an enum per body, branched in the engine
//  (replacing Simbody's RigidBodyNode virtual dispatch).
//
//  Tables here are built once and never resized; std::vector is fine. They can
//  later be frozen into a MemoryArena alongside RobotState if profiling wants
//  the sweep inputs cache-packed — the engine reads them through pointers only.
// ============================================================================

#include 
#include 

#include "robot_math.hpp"

enum class JointType : std::uint8_t {
    Rigid = 0,       // 0 dof
    Torsion,         // 1 dof  rotation about the bond axis (the canonical dihedral)
    Slider,          // 1 dof  translation along the bond axis
    Cylinder,        // 2 dof  rotation + translation about/along the bond axis
    BendStretch,     // 2 dof  rotation perpendicular to the bond + translation along it
    Cartesian,       // 3 dof  3 translations
    Ball,            // 3 dof  rotation, q = 4 (quaternion) by default
    SphericalCoords, // 3 dof  BAT (azimuth, zenith, radius)
    FreeLine,        // 5 dof  2 rotations (no spin about own line) + 3 translations, q = 7
    Free,            // 6 dof  q = 7 (quaternion + translation)
};

// ----------------------------------------------------------------------------
//  INDEX / ORDER CONVENTIONS (must match python/robosample/molecule_prototype.py
//  and z_matrix.py exactly -- see MIGRATION_PLAN_v2_corrections.md Part B 5/6):
//   * Atoms arrive in BFS/compound order from the root (compound 0 == root).
//     The array position IS the atom index; Molmodel cAIx is retired.
//   * Bonds are oriented PARENT->CHILD (root-ward first):  bondsI=parent,
//     bondsJ=child. Ring-closing bonds are flagged (transmitted explicitly)
//     and are NEVER tree edges (skipped in decomposeRigidUnits/buildFrameGraph).
//   * Angles oriented i->k (j center); proper torsions oriented i->l; all
//     root-ward-first, matching Python.
//   * Z-MATRIX uses the standard BAT convention and is the OPPOSITE direction:
//     zI = atom PLACED; zJ/zK/zL = back-references TOWARD root
//     (parent / grandparent / great-grandparent). BAT = dist(zI,zJ),
//     angle(zI,zJ,zK), dihedral(zI,zJ,zK,zL). -1 sentinels in leading rows.
//   * Frame-graph ancestry names: self / parent / grandParent (root-ward).
//     (refChild only exists if the legacy A1 orientation switch is kept.)
// ----------------------------------------------------------------------------
struct RobotModel {
    // ---- system sizes ------------------------------------------------------
    int numBodies = 0; // includes Ground == body 0
    int numAtoms = 0;
    int nq = 0; // total generalized coordinates (quaternion-inflated)
    int nu = 0; // total generalized speeds (== DOFs)

    // ---- body tree, TOPOLOGICAL ORDER (parent index < child index) ---------
    // Sweeps: inward = reverse iteration, outward = forward iteration.
    std::vector bodyParent;      // [numBodies]   parent body (Ground's parent = -1)
    std::vector bodyLevel;       // [numBodies]   depth from Ground (for future level-parallel sweeps)
    std::vector bodyJoint; // [numBodies]
    std::vector bodyRootAtom;    // [numBodies]   the inboard ("root") atom of this body
    std::vector bodyChildrenBeg; // [numBodies]   CSR into bodyChildren
    std::vector bodyChildrenEnd; // [numBodies]
    std::vector bodyChildren;    // flattened children, CSR

    // ---- generalized-coordinate offsets ------------------------------------
    std::vector bodyQIndex;   // [numBodies] first q of this body
    std::vector bodyNQ;       // [numBodies] number of q (4 or 7 if quaternion)
    std::vector bodyUIndex;   // [numBodies] first u of this body
    std::vector bodyNU;       // [numBodies] number of u == dof
    std::vector bodyUSqIndex; // [numBodies] offset into the dof*dof DI pool
    int nuSq = 0;                  // sum of dof^2 over bodies (DI pool size)
    // q-slots that are quaternions and must be renormalized each Verlet step
    // (port of the no-constraint q-projection). Stored as (qStart) of each quat.
    std::vector quaternionQStart; // q index where a 4-wide quaternion begins

    // ---- static joint frames (CONSTANT once built) -------------------------
    // X_PF: inboard frame fixed on the PARENT body. X_BM: outboard frame fixed
    // on THIS body. These define the mobilizer; in the current code they were
    // Simbody topology defaults rewritten every transfer — here they are fixed.
    std::vector X_PF; // [numBodies]
    std::vector X_BM; // [numBodies]

    // ---- mass properties (RECOMPUTED every transfer; about body origin)
    std::vector bodyMass;  // [numBodies]
    std::vector bodyCom_B; // [numBodies] center of mass in body frame
    std::vector
        bodyUnitInertia_B; // [numBodies] unit inertia about body origin, body frame

    // ---- kinetic-metric preconditioning (fictitious mass; SAMPLING only) ----
    // Per-body scale applied to the body spatial inertia Mk_G in the KINETIC
    // metric ONLY: the momentum draw (sqrt(M^-1)), the kinetic energy
    // (1/2 u^T M u), and the Fixman log-det (ln det M). Default 1.0 == physical.
    // MUST be a run-constant (never a function of q). Does NOT enter V.
    //
    // Why this is bias-free: Mk_G is the single source for P/D (hence both the
    // sqrt(M^-1) draw and ln det M) and for calcKineticEnergy, so scaling it by a
    // constant s_b shifts ln det M by the constant sum_b dof_b * ln s_b, which
    // cancels in dH; and the marginalised det(M)^{1/2} is cancelled exactly by
    // the Fixman exp(-beta F) for the SAME (scaled) M. Net effect: the sampled
    // configurational distribution is unchanged; only the proposal dynamics are
    // rescaled, raising the stable dt ~sqrt(s_b) for the scaled body. Used to
    // tame stiff explicit-solvent libration. See World::setMassScaleByJoint /
    // setBodyMassScale. May be left empty (treated as all-1.0).
    std::vector bodyMassScale; // [numBodies]  default 1.0

    // ---- atom <-> body maps ------------------------------------------------
    std::vector atomBody;             // [numAtoms]  body index of each atom
    std::vector atomMass;      // [numAtoms]  per-atom mass (Daltons), constant
    std::vector atomStation_B; // [numAtoms]  atom in body frame (per transfer)
    std::vector atomDummIndex;        // [numAtoms]  DuMM atom index (for OpenMM mapping)
    std::vector atomCompoundIndex;    // [numAtoms]  cAIx (analysis / IO compatibility)
    std::vector bodyAtomsBeg;         // [numBodies] CSR into a body-sorted atom list
    std::vector bodyAtomsEnd;         // [numBodies]
    std::vector bodyAtoms;            // flattened atoms per body, CSR

    // ---- frame graph (your existing Cartesian->frame kernel, kept verbatim) -
    struct FrameGraph {
        int totalAtoms = 0;
        std::vector topoOffset;                              // [numTopologies+1]
        std::vector g_self, g_parent, g_gparent, g_refChild; // full-geometry bucket
        std::vector f_self, f_parent;                        // fallback bucket
        std::vector r_self;                                  // roots
    } frameGraph;

    // ---- OpenMM force->body reduction (NO NonBondedMappings) ----------------
    // DuMM's NonBondedMappings (dummAtomIndex/includedAtomIndex/bodyIndex/
    // bodyStart) is DROPPED. Atom index == OpenMM particle index == SoA
    // position, so positions hand over with no gather. The force->body
    // reduction needs ONLY atomBody[a] (above): scatter into the small
    // bodyForce array (numBodies SpatialVecs, hot in L1). The body-sorted
    // atom CSR (bodyAtoms/bodyAtomsBeg/End, above) is OPTIONAL and only used
    // if a very large single robot wants a strict sequential reduction.

    // ---- z-matrix rows (BAT) ----------------------------------------------
    std::vector zI, zJ, zK, zL; // [numZRows]; -1 sentinels in leading rows
    int numZRows = 0;

    // ---- convenience -------------------------------------------------------
    [[nodiscard]] bool isQuaternionBody(int b) const {
        return jointUsesQuaternion(bodyJoint[b]);
    }

    // ---- joint-type facts: the SINGLE source of truth -----------------------
    // Every place that needs per-joint sizes/flags (the builder's dof counting,
    // the engine's q/u layout, the quaternion renormalizer) reads these, so a
    // new joint is defined in exactly one spot. nq differs from nu only for the
    // quaternion bodies (orientation stored as a 4-wide unit quaternion).
    [[nodiscard]] static constexpr int jointNU(JointType jt) {
        switch (jt) {
            case JointType::Rigid:
                return 0;
            case JointType::Torsion:
            case JointType::Slider:
                return 1;
            case JointType::Cylinder:
            case JointType::BendStretch:
                return 2;
            case JointType::Cartesian:
            case JointType::Ball:
            case JointType::SphericalCoords:
                return 3;
            case JointType::FreeLine:
                return 5;
            case JointType::Free:
                return 6;
        }
        return 0;
    }
    [[nodiscard]] static constexpr int jointNQ(JointType jt) {
        // Quaternion bodies inflate the orientation block from 3 (rotational u)
        // to 4 (unit quaternion q): Ball (4), FreeLine (4 + 3 trans = 7), Free
        // (4 + 3 trans = 7). All others have nq == nu.
        switch (jt) {
            case JointType::Ball:
                return 4;
            case JointType::FreeLine:
            case JointType::Free:
                return 7;
            default:
                return jointNU(jt);
        }
    }
    [[nodiscard]] static constexpr bool jointUsesQuaternion(JointType jt) {
        return jt == JointType::Ball || jt == JointType::FreeLine || jt == JointType::Free;
    }
    [[nodiscard]] static constexpr bool jointIsFlexible(JointType jt) {
        return jt != JointType::Rigid; // Weld/Rigid welds its two atoms into one rigid unit
    }
    // H_FM is CONSTANT in the F (inboard) frame for these, so HDot_FM == 0 and
    // the engine's mobilizer-bias acceleration uses the cheap centripetal path.
    // The other three (BendStretch, SphericalCoords, FreeLine) have q-dependent
    // H_FM and go through the general HDot_FM*u term.
    [[nodiscard]] static constexpr bool jointHasConstantHFM(JointType jt) {
        switch (jt) {
            case JointType::Rigid:
            case JointType::Torsion:
            case JointType::Slider:
            case JointType::Cylinder:
            case JointType::Cartesian:
            case JointType::Ball:
            case JointType::Free:
                return true;
            default: // BendStretch, SphericalCoords, FreeLine
                return false;
        }
    }
    // Only these joints are meaningful as a molecule-root attachment to Ground
    // (the former RootMobility set). Slider/Cylinder/BendStretch/SphericalCoords
    // are defined against a BOND axis that does not exist at the Ground hinge, so
    // they are rejected there (validated in World::buildModel). This is a rule on
    // ONE enum, not a second enum.
    [[nodiscard]] static constexpr bool jointIsLegalRoot(JointType jt) {
        switch (jt) {
            case JointType::Free:
            case JointType::Cartesian: // == Cartesian
            case JointType::Rigid:     // == Rigid
            case JointType::FreeLine:
            case JointType::Ball:
            case JointType::Torsion:
                return true;
            default:
                return false;
        }
    }
};

#pragma once

// ============================================================================
//  RobotState - the single aligned slab holding every per-step quantity, SoA.
//  Replaces SimTK::State + the SBTree*Cache caches (Simbody01/Simbody/src/
//  SimbodyTreeState.h). Field names track those caches so the engine port can
//  be diffed 1:1 against Simbody.
//
//  H_FM / H / G are stored as SpatialVec COLUMNS: column j of a body lives at
//  index (bodyUIndex + j). One SpatialVec == 2 Vec3, so an array of `nu`
//  SpatialVec is exactly the 2*nu Vec3 hinge storage Simbody uses.
//
//  DI (the dof x dof articulated hinge inverse) lives in a flat Real pool of
//  size model.nuSq, addressed by model.bodyUSqIndex[b] (row-major dof x dof).
// ============================================================================

#include 

#include "MemoryArena.hpp"
#include "RobotModel.hpp"
#include "robot_math.hpp"

struct EnergySnapshot {
    robo::Real pe = 0;
    robo::Real ke = 0;
    robo::Real fixman = 0;
    robo::Real logSineSqrGamma2 = 0;
    robo::Real total = 0;
};

class RobotState {
    public:
    RobotState() = default;

    auto allocateFull(const RobotModel& model) -> void {
        // Reset the arena first so this is safe to call more than once (a World
        // rebuild, e.g. after World::setRootMobility, re-runs buildModel which
        // re-allocates). The arena is one-shot -- reserve() throws after commit()
        // -- so without this a second allocate would abort. Move-assigning a
        // fresh arena frees the previous slab. No-op on the first (default) call.
        arena_ = MemoryArena{};

        nq_ = model.nq;
        nu_ = model.nu;
        nAtoms_ = model.numAtoms;
        nBodies_ = model.numBodies;
        nZRows_ = model.numZRows;
        nuSq_ = model.nuSq;

        hQ_ = arena_.reserve(nq_);
        hU_ = arena_.reserve(nu_);
        hQDot_ = arena_.reserve(nq_);
        hUDot_ = arena_.reserve(nu_);
        hQDotDot_ = arena_.reserve(nq_);

        hAtomPosG_ = arena_.reserve(nAtoms_);
        hAtomStationG_ = arena_.reserve(nAtoms_);

        hX_GB_ = arena_.reserve(nBodies_);
        hX_FM_ = arena_.reserve(nBodies_);
        hX_PB_ = arena_.reserve(nBodies_);
        hPhi_ = arena_.reserve(nBodies_);
        hMk_G_ = arena_.reserve(nBodies_);
        hComG_ = arena_.reserve(nBodies_);
        hH_FM_ = arena_.reserve(nu_);
        hH_ = arena_.reserve(nu_);
        hV_FM_ = arena_.reserve(nBodies_);
        hV_PB_G_ = arena_.reserve(nBodies_);
        hV_GB_ = arena_.reserve(nBodies_);
        hA_GB_ = arena_.reserve(nBodies_);
        hGyro_ = arena_.reserve(nBodies_);
        hCoriolisA_ = arena_.reserve(nBodies_);
        hMobCoriolisA_ = arena_.reserve(nBodies_);

        hP_ = arena_.reserve(nBodies_);
        hPPlus_ = arena_.reserve(nBodies_);
        hG_ = arena_.reserve(nu_);
        hDI_ = arena_.reserve(nuSq_);
        hABCentrifugal_ = arena_.reserve(nBodies_);
        hZ_ = arena_.reserve(nBodies_);
        hZPlus_ = arena_.reserve(nBodies_);
        hEps_ = arena_.reserve(nu_);

        hBodyForceG_ = arena_.reserve(nBodies_);
        hMobilityForce_ = arena_.reserve(nu_);
        hBAT_ = arena_.reserve(nZRows_);

        arena_.commit();
        full_ = true;
    }

    auto allocateCompact(const RobotModel& model) -> void {
        arena_ = MemoryArena{}; // re-callable: see allocateFull
        nAtoms_ = model.numAtoms;
        nZRows_ = model.numZRows;
        hAtomPosG_ = arena_.reserve(nAtoms_);
        hBAT_ = arena_.reserve(nZRows_);
        arena_.commit();
        full_ = false;
    }

    [[nodiscard]] auto q() const -> robo::Real* {
        return arena_.ptr(hQ_);
    }
    [[nodiscard]] auto u() const -> robo::Real* {
        return arena_.ptr(hU_);
    }
    [[nodiscard]] auto qdot() const -> robo::Real* {
        return arena_.ptr(hQDot_);
    }
    [[nodiscard]] auto udot() const -> robo::Real* {
        return arena_.ptr(hUDot_);
    }
    [[nodiscard]] auto qdotdot() const -> robo::Real* {
        return arena_.ptr(hQDotDot_);
    }

    [[nodiscard]] auto atomPosG() const -> robo::Vec3* {
        return arena_.ptr(hAtomPosG_);
    }
    [[nodiscard]] auto atomStationG() const -> robo::Vec3* {
        return arena_.ptr(hAtomStationG_);
    }

    [[nodiscard]] auto X_GB() const -> robo::Transform* {
        return arena_.ptr(hX_GB_);
    }
    [[nodiscard]] auto X_FM() const -> robo::Transform* {
        return arena_.ptr(hX_FM_);
    }
    [[nodiscard]] auto X_PB() const -> robo::Transform* {
        return arena_.ptr(hX_PB_);
    }
    [[nodiscard]] auto Phi() const -> robo::PhiMatrix* {
        return arena_.ptr(hPhi_);
    }
    [[nodiscard]] auto Mk_G() const -> robo::SpatialInertia* {
        return arena_.ptr(hMk_G_);
    }
    [[nodiscard]] auto comG() const -> robo::Vec3* {
        return arena_.ptr(hComG_);
    }
    [[nodiscard]] auto H_FM() const -> robo::SpatialVec* {
        return arena_.ptr(hH_FM_);
    }
    [[nodiscard]] auto H() const -> robo::SpatialVec* {
        return arena_.ptr(hH_);
    }
    [[nodiscard]] auto V_FM() const -> robo::SpatialVec* {
        return arena_.ptr(hV_FM_);
    }
    [[nodiscard]] auto V_PB_G() const -> robo::SpatialVec* {
        return arena_.ptr(hV_PB_G_);
    }
    [[nodiscard]] auto V_GB() const -> robo::SpatialVec* {
        return arena_.ptr(hV_GB_);
    }
    [[nodiscard]] auto A_GB() const -> robo::SpatialVec* {
        return arena_.ptr(hA_GB_);
    }
    [[nodiscard]] auto gyro() const -> robo::SpatialVec* {
        return arena_.ptr(hGyro_);
    }
    [[nodiscard]] auto coriolisA() const -> robo::SpatialVec* {
        return arena_.ptr(hCoriolisA_);
    }
    [[nodiscard]] auto mobCoriolisA() const -> robo::SpatialVec* {
        return arena_.ptr(hMobCoriolisA_);
    }

    [[nodiscard]] auto P() const -> robo::ArticulatedInertia* {
        return arena_.ptr(hP_);
    }
    [[nodiscard]] auto PPlus() const -> robo::ArticulatedInertia* {
        return arena_.ptr(hPPlus_);
    }
    [[nodiscard]] auto G() const -> robo::SpatialVec* {
        return arena_.ptr(hG_);
    }
    [[nodiscard]] auto DI() const -> robo::Real* {
        return arena_.ptr(hDI_);
    }
    [[nodiscard]] auto abCentrifugal() const -> robo::SpatialVec* {
        return arena_.ptr(hABCentrifugal_);
    }
    [[nodiscard]] auto Z() const -> robo::SpatialVec* {
        return arena_.ptr(hZ_);
    }
    [[nodiscard]] auto zPlus() const -> robo::SpatialVec* {
        return arena_.ptr(hZPlus_);
    }
    [[nodiscard]] auto eps() const -> robo::Real* {
        return arena_.ptr(hEps_);
    }

    [[nodiscard]] auto bodyForceG() const -> robo::SpatialVec* {
        return arena_.ptr(hBodyForceG_);
    }
    [[nodiscard]] auto mobilityForce() const -> robo::Real* {
        return arena_.ptr(hMobilityForce_);
    }
    [[nodiscard]] auto BAT() const -> robo::Vec3* {
        return arena_.ptr(hBAT_);
    }

    [[nodiscard]] auto nq() const -> int {
        return nq_;
    }
    [[nodiscard]] auto nu() const -> int {
        return nu_;
    }
    [[nodiscard]] auto numAtoms() const -> int {
        return nAtoms_;
    }
    [[nodiscard]] auto numBodies() const -> int {
        return nBodies_;
    }
    [[nodiscard]] auto isFull() const -> bool {
        return full_;
    }

    EnergySnapshot energy;
    robo::Real time = 0;

    auto copyTransferPayloadTo(RobotState& dst) const -> void {
        const robo::Vec3* srcPos = atomPosG();
        robo::Vec3* dstPos = dst.atomPosG();
        for (int i = 0; i < nAtoms_; ++i) {
            dstPos[i] = srcPos[i];
        }
        dst.energy = energy;
    }

    private:
    MemoryArena arena_;
    bool full_ = false;
    int nq_ = 0, nu_ = 0, nAtoms_ = 0, nBodies_ = 0, nZRows_ = 0, nuSq_ = 0;

    using Hnd = MemoryArena::Handle;
    Hnd hQ_{}, hU_{}, hQDot_{}, hUDot_{}, hQDotDot_{};
    Hnd hAtomPosG_{}, hAtomStationG_{};
    Hnd hX_GB_{}, hX_FM_{}, hX_PB_{}, hPhi_{}, hMk_G_{}, hComG_{}, hH_FM_{}, hH_{};
    Hnd hV_FM_{}, hV_PB_G_{}, hV_GB_{}, hA_GB_{}, hGyro_{}, hCoriolisA_{}, hMobCoriolisA_{};
    Hnd hP_{}, hPPlus_{}, hG_{}, hDI_{}, hABCentrifugal_{}, hZ_{}, hZPlus_{}, hEps_{};
    Hnd hBodyForceG_{}, hMobilityForce_{}, hBAT_{};
};

namespace robo {

inline auto operator<<(std::ostream& os, const Vec3& v) -> std::ostream& {
    return os << '[' << v[0] << ' ' << v[1] << ' ' << v[2] << ']';
}

inline auto operator<<(std::ostream& os, const SpatialVec& sv) -> std::ostream& {
    // SpatialVec == 2 Vec3: [0] angular, [1] linear
    return os << "{ang=" << sv[0] << " lin=" << sv[1] << '}';
}

} // namespace robo

#pragma once

#include 
#include 
#include 

#include "RobotModel.hpp"

enum NonbondedMethod : std::uint8_t {
    // No cutoff is applied to nonbonded interactions. The full set of N^2 interactions is computed exactly.
    // This necessarily means that periodic boundary conditions cannot be used. This is the default.
    NoCutoff = 0,

    // Interactions beyond the cutoff distance are ignored. Coulomb interactions closer than the cutoff
    // distance are modified using the reaction field method.
    CutoffNonPeriodic,

    // Periodic boundary conditions are used, so that each particle interacts only with the nearest periodic
    // copy of each other particle. Interactions beyond the cutoff distance are ignored. Coulomb interactions
    // closer than the cutoff distance are modified using the reaction field method.
    CutoffPeriodic,

    // Periodic boundary conditions are used, and Ewald summation is used to compute the interaction of each
    // particle with all periodic copies of every other particle.
    Ewald,

    // Periodic boundary conditions are used, and Particle-Mesh Ewald (PME) summation is used to compute the
    // interaction of each particle with all periodic copies of every other particle.
    PME,
};

struct SystemTopology {
    // -------------------------------------------------------------------------
    // Molecule ranges  -- [begin, end) into each array above; length == numMolecules
    // -------------------------------------------------------------------------

    int numMolecules{0};
    std::vector atomsBegin;
    std::vector atomsEnd;
    std::vector bondsBegin;
    std::vector bondsEnd;
    std::vector anglesBegin;
    std::vector anglesEnd;
    std::vector periodicTorsionsBegin;
    std::vector periodicTorsionsEnd;
    std::vector harmonicTorsionsBegin;
    std::vector harmonicTorsionsEnd;
    std::vector zMatrixBegin;
    std::vector zMatrixEnd;
    std::vector ureyBradleyBegin;
    std::vector ureyBradleyEnd;
    std::vector scaling14Begin;
    std::vector scaling14End;
    std::vector exclusionBegin;
    std::vector exclusionEnd;
    std::vector atomsRootIndex;
    std::vector rootMobilities;

    // -------------------------------------------------------------------------
    // Atom arrays  (BFS order, unit-converted)
    // -------------------------------------------------------------------------

    int numAtoms{0};
    std::vector atomsUniqueName;
    std::vector atomsNonbondedIndex;
    std::vector atomsPrmtopIndex;

    std::vector atomsElementName;
    std::vector atomsElementSymbol;
    std::vector atomsMass;    ///< Mass.                               [daltons]
    std::vector atomsCharge;  ///< Partial charge.                     [e]
    std::vector atomsSigma;   ///< Lennard-Jones sigma (vdW radius).   [nm]
    std::vector atomsEpsilon; ///< Lennard-Jones epsilon (well depth). [kJ/mol]
    std::vector atomsRadius;  ///< GBSA solvent radius.                [nm]
    std::vector atomsScreen;  ///< OBC screening factor.               [dimensionless]
    std::vector atomsX;       ///< x coordinate (reference structure). [nm]
    std::vector atomsY;       ///< y coordinate (reference structure). [nm]
    std::vector atomsZ;       ///< z coordinate (reference structure). [nm]
    std::vector atomsAtomicNumber;
    std::vector atomsNumBondsInvolved;

    // -------------------------------------------------------------------------
    // Bond arrays  (BFS order)
    // -------------------------------------------------------------------------

    int numBonds{0};                      ///< Total bonds (tree + ring-closing).
    std::vector bondsI;              ///< BFS index of bond endpoint atom 1.
    std::vector bondsJ;              ///< BFS index of bond endpoint atom 2.
    std::vector bondsMoleculeIndex;  ///< Molecule index this bond belongs to.
    std::vector bondsRingClosing;   ///< Whether this bond is a ring-closing bond.
    std::vector bondsStiffness;   ///< Harmonic force constant.         [kJ/mol/nm^2]
    std::vector bondsEquilibrium; ///< Equilibrium bond length.         [nm]

    // -------------------------------------------------------------------------
    // Angle arrays
    // -------------------------------------------------------------------------

    int numAngles{0};
    std::vector anglesI;
    std::vector anglesJ;
    std::vector anglesK;
    std::vector anglesEquilibrium; ///< Equilibrium angle.               [rad]
    std::vector anglesStiffness;   ///< Harmonic force constant.         [kJ/mol/rad^2]

    // -------------------------------------------------------------------------
    // Periodic torsion arrays
    // -------------------------------------------------------------------------

    int numPeriodicTorsions{0};
    std::vector periodicTorsionsImproper;
    std::vector periodicTorsionsI;
    std::vector periodicTorsionsJ;
    std::vector periodicTorsionsK;
    std::vector periodicTorsionsL;
    std::vector periodicTorsionsN;            ///< Periodicity.
    std::vector periodicTorsionsPhase;     ///< Phase offset.             [rad]
    std::vector periodicTorsionsStiffness; ///< Force constant.           [kJ/mol]

    // -------------------------------------------------------------------------
    // Harmonic torsion arrays
    // -------------------------------------------------------------------------

    int numHarmonicTorsions{0};
    std::vector harmonicTorsionsI;
    std::vector harmonicTorsionsJ;
    std::vector harmonicTorsionsK;
    std::vector harmonicTorsionsL;
    std::vector harmonicTorsionsStiffness; ///< Force constant.           [kJ/mol]
    std::vector harmonicTorsionsPhase;     ///< Equilibrium angle.        [rad]

    // -------------------------------------------------------------------------
    // Z-matrix arrays  (tree-traversal order, rooted at atomsRootIndex)
    // Length n; sentinel value -1 fills inapplicable leading rows (see below).
    // -------------------------------------------------------------------------

    int numZMatrixRows{0};
    std::vector zMatrixI; ///< Global atom index of the atom placed at row r.
    std::vector zMatrixJ; ///< Bond-length reference atom.  Row 0   : -1 (root).
    std::vector zMatrixK; ///< Bond-angle reference atom.   Rows 0-1: -1.
    std::vector zMatrixL; ///< Dihedral reference atom.     Rows 0-2: -1.

    // -------------------------------------------------------------------------
    // Urey-Bradley 1-3 interactions
    // -------------------------------------------------------------------------

    int numUreyBradley{0};
    std::vector ureyBradleyI;              ///< Global index of atom 1 (outer atom of angle i-j-k).
    std::vector ureyBradleyK;              ///< Global index of atom 3 (outer atom of angle i-j-k).
    std::vector ureyBradleyStiffness;   ///< Harmonic force constant. [kJ/mol/nm^2]
    std::vector ureyBradleyEquilibrium; ///< Nominal 1-3 distance.                           [nm]

    // -------------------------------------------------------------------------
    // 1-4 pair scaling
    // -------------------------------------------------------------------------

    int numScaling14{0};
    std::vector scaling14I;                ///< Global index of atom 1 (first atom of dihedral i-j-k-l).
    std::vector scaling14L;                ///< Global index of atom 4 (last  atom of dihedral i-j-k-l).
    std::vector scaling14ChargeProduct; ///< q1*q4 pre-scaled by the 1-4 electrostatic factor.  [e^2]
    std::vector scaling14Epsilon;       ///< Combined LJ well depth.                          [kJ/mol]
    std::vector scaling14Sigma;         ///< Combined LJ radius.                              [nm]

    // -------------------------------------------------------------------------
    // Exclusions
    // -------------------------------------------------------------------------

    int numExclusions{0};
    std::vector exclusionI; ///< Global index of atom 1.
    std::vector exclusionJ; ///< Global index of atom 2.

    // -------------------------------------------------------------------------
    // CMAP torsion arrays
    // -------------------------------------------------------------------------

    int cmapGridSize{0};
    std::vector cmapGridEnergy;

    std::vector cmapTorsionMapIndex;
    std::vector cmapTorsionA1;
    std::vector cmapTorsionA2;
    std::vector cmapTorsionA3;
    std::vector cmapTorsionA4;
    std::vector cmapTorsionB1;
    std::vector cmapTorsionB2;
    std::vector cmapTorsionB3;
    std::vector cmapTorsionB4;

    bool hasNBfix = false;
    int numNBTypes = 0;
    std::vector aCoef;
    std::vector bCoef;

    bool useGBSAOBC2 = false;
    double gbsaSolventDielectric = 78.5;
    double gbsaSoluteDielectric = 1.0;

    NonbondedMethod nonbondedMethod = NonbondedMethod::NoCutoff;
    double nonbondedCutoff = 1.2;

    // -------------------------------------------------------------------------
    // Periodic box (explicit solvent)
    // -------------------------------------------------------------------------
    // Three REDUCED lattice vectors in OpenMM's lower-triangular convention
    //   a = (ax, 0,  0 ),  b = (bx, by, 0 ),  c = (cx, cy, cz),
    // stored row-major as 9 doubles [a.x a.y a.z  b.x b.y b.z  c.x c.y c.z], in
    // nm. Filled directly from ParmEd's parm.box_vectors (already reduced), so no
    // a/b/c/alpha/beta/gamma reduction happens on the C++ side. EMPTY for any
    // non-periodic method; REQUIRED (length 9) for CutoffPeriodic / Ewald / PME.
    // The box is set on the OpenMM System (setDefaultPeriodicBoxVectors) BEFORE
    // the Context is created, which is mandatory for PME.
    std::vector boxVectors;

    // Reciprocal-space accuracy for Ewald/PME (OpenMM setEwaldErrorTolerance).
    // Ignored by the non-Ewald methods. 5e-4 is OpenMM's usual default.
    double ewaldErrorTolerance = 5.0e-4;

    // -------------------------------------------------------------------------
    // Virtual sites (extra points: massless particles placed by real atoms)
    // -------------------------------------------------------------------------
    // 4-point water (OPC, TIP4P family) carries a massless EP that holds the
    // negative charge; its position is the affine combination
    //   r_site = w1*r_a1 + w2*r_a2 + w3*r_a3,   w1 + w2 + w3 = 1
    // (a 3-particle AVERAGE site). These MUST be declared to OpenMM via
    // setVirtualSite(ThreeParticleAverageSite) so the integrator skips them and
    // redistributes their force onto the parents; otherwise OpenMM freezes the
    // massless particle in place and the EP detaches as the molecule moves.
    // Indices are global/BFS atom indices (the OpenMM particle order). Only the
    // 3-particle average type is represented here (covers OPC/TIP4P/-Ew/-2005);
    // out-of-plane sites (e.g. TIP5P) would need an additional type.
    int numVirtualSites{0};
    std::vector vsSite;       ///< global index of the massless EP particle.
    std::vector vsAtom1;      ///< parent atom 1 (global index).
    std::vector vsAtom2;      ///< parent atom 2 (global index).
    std::vector vsAtom3;      ///< parent atom 3 (global index).
    std::vector vsWeight1; ///< weight on parent 1.
    std::vector vsWeight2; ///< weight on parent 2.
    std::vector vsWeight3; ///< weight on parent 3.

    double thermostatTemperature = 300.0;
    double collisionFrequency = 1.0;
    int seed = 0;
};

#pragma once
// ============================================================================
//  units_md.hpp -- boundary unit safety for robosample, built on the
//  nholthaus compile-time units library (third_party/units/units.h, MIT).
//
//  POLICY: typed quantities live ONLY at I/O boundaries (prmtop parsing, the
//  OpenMM transfer, DCD writing, timestep configuration) where unit-system
//  mistakes actually happen -- Angstrom vs nm, kcal vs kJ. The dynamics core
//  stays raw `double` in the consistent MD system (nm, dalton, ps, kJ/mol);
//  there is nothing to mix up once past the boundary, so paying for dimensional
//  analysis inside the ABA recursion would be cost with no benefit. nholthaus
//  unit_t is zero runtime overhead, but the ergonomic + compile-time cost is
//  only worth it at the edges. The conversions below are the exact spots that
//  have bitten us (e.g. the DCD nm->Angstrom x10).
//
//  Add the submodule and point the include path at it:
//      git submodule add https://github.com/nholthaus/units third_party/units
//      target_include_directories(robosample PRIVATE third_party/units/include)
// ============================================================================

#include "units.h" // nholthaus

namespace robo::mdunits {

// boundary unit aliases (use these on function signatures that cross an edge)
using Nanometer = units::length::nanometer_t;
using Angstrom = units::length::angstrom_t;
using Picosecond = units::time::picosecond_t;
using Femtosecond = units::time::femtosecond_t;
using Kilojoule = units::energy::kilojoule_t;     // per-mole is implicit in MD
using Kilocalorie = units::energy::kilocalorie_t; // ratio kcal:kJ is system-independent

// ---- boundary conversions: typed in, raw double out (for the core) ----------
inline auto angstromToNm(double valAngstrom) -> double {
    return Nanometer(Angstrom(valAngstrom)).value();
}
inline auto nmToAngstrom(double valNanometer) -> double {
    return Angstrom(Nanometer(valNanometer)).value(); // the DCD writer's x10
}
inline auto kcalToKj(double valKilocalorie) -> double {
    return Kilojoule(Kilocalorie(valKilocalorie)).value();
}
inline auto kjToKcal(double valKilojoule) -> double {
    return Kilocalorie(Kilojoule(valKilojoule)).value();
}
inline auto fsToPs(double valFemtosecond) -> double {
    return Picosecond(Femtosecond(valFemtosecond)).value();
}

// Mass (dalton == g/mol numerically) and energy-per-mole stay raw double: the
// prmtop already supplies them in the MD system, and they never cross into a
// different unit system, so a strong type would add friction with no payoff.

} // namespace robo::mdunits

#pragma once

// ============================================================================
//  World - reimplemented, SimTK-free. Each World owns ONE robot (immutable
//  RobotModel + live RobotState), a RobotEngine (stateless ops), and a
//  ForceBridge to OpenMM.
//
//  Regimes (selected by moveType / cartesian_):
//    Cartesian world  : plain OpenMM MD on the device (integrateTrajectoryOnDevice).
//    Torsional/robotic: internal-coordinate Generalized-Coordinate HMC. Sampling
//                       = seed u via sqrt(M^-1), Verlet stepTo, Metropolis on the
//                       FULL Hamiltonian H = PE + KE + Fixman - 1/2 RT logSineSqr.
//    Docking world    : a torsional world whose ligand molecule roots are Free
//                       and everything else is Welded/Rigid. Its move is a rigid
//                       KICK of the ligand (a symmetric Cartesian proposal,
//                       Metropolised on dU), optionally followed by the standard
//                       MD-HMC relaxation sub-move. Root mobility here is a
//                       *World* property, supplied by Context::addDockingWorld.
// ============================================================================

#include 
#include 
#include 
#include 

#include "Constraints.hpp"
#include "ForceBridge.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TopologyElements.hpp"
#include "robot_math.hpp"

enum class AcceptRejectMode : std::uint8_t {
    AlwaysAccept = 0,
    MetropolisHastings
};

// How a world proposes a sample.
//   MdHmc     : draw momenta, run constrained Verlet, Metropolis on full H.
//   RigidKick : rigid-body kick of the ligand (docking). A symmetric Cartesian
//               proposal Metropolised on dU; if mdSteps > 0 it is followed by an
//               MdHmc relaxation sub-move on the same world.
enum class MoveType : std::uint8_t {
    MdHmc = 0,
    RigidKick,
    NcmcSwitch // NEW: lambda:1->0->1 alchemical decouple-move-recouple (per-molecule)
};

// Velocity-distortion option for the HMC momentum draw, ported from the simtk
// Robosample "NMA scaling" (HMCSampler::setVelocitiesToNMA). Before the
// sqrt(M^-1) map, each generalized-speed component of the white-noise draw is
// scaled by its per-DOF NMA factor and the overall vector length is restored by
// sqrt(nu)/||uScale|| so the kinetic temperature is preserved. The source read
// the per-body factors from World::getMobodUScaleFactor but never populated them,
// so the effective factors are unity and the distortion reduces to the plain
// Gaussian draw unless non-unit factors are supplied. A nullopt option (Python
// None, the default) means the distortion is not applied at all.
enum class DistortOption : std::uint8_t {
    NMA = 0
};

// Per-bond mobility selection produced by Context::build_flexibilities. The
// per-bond joint type is now a JointType (the former BondMobility enum is gone;
// Rigid/Torsion remain usable as JointType aliases). Default Weld (== Rigid)
// welds the two bonded atoms into the same rigid unit.
struct Selection {
    std::vector bondMobility; // [numBonds]; default Weld (== Rigid)
};

struct SamplerConfig {
    double timeStep = 0.001;
    int mdSteps = 0;
    AcceptRejectMode acceptRejectMode = AcceptRejectMode::AlwaysAccept;
    bool useFixman = false; // include the Fixman potential + logSineSqr in H
    MoveType moveType = MoveType::MdHmc;
    bool useNuts = false;

    // Velocity-distortion applied at momentum-draw time (World::reinitialize).
    // nullopt (Python None, the default) => plain Gaussian draw, no distortion.
    // DistortOption::NMA => apply the per-DOF NMA velocity scaling (see the
    // DistortOption enum). Ported from the simtk HMCSampler DistortOpt path.
    std::optional distortOption = std::nullopt;
    // NMA Route B bias magnitude alpha (DistortOption::NMA only). The momentum
    // mixture is Us = z +/- alpha * uhat, uhat a UNIT direction, so alpha is the
    // directed push in thermal-sigma units along that direction (||bias||^2 =
    // alpha^2, NOT nu). Larger alpha => bolder proposals, lower acceptance. See
    // add_sampler docstring for guidance; 1.0 is one thermal sigma.
    double nmaBiasScale = 1.0;
    // Docking: the binding sphere is sized automatically, per ligand, as
    //   R_i = R_receptor + sphereFactor * R_ligand_i
    // (R_receptor / R_ligand_i = max extent of each set from its centroid, from
    // current geometry). sphereFactor scales only the ligand allowance: the guest
    // may roam roughly sphereFactor ligand-radii beyond the receptor surface.
    double sphereFactor = 1.0;

    // alwaysKick == false (default): CONTAINMENT -- the kick fires for a ligand
    // only when its COM has left the sphere; otherwise the move is pure dynamics.
    // alwaysKick == true: perturb every ligand every round regardless. Either way
    // the perturbation relocates the guest (uniform position in the sphere +
    // uniform reorientation = a full perturbation of its external q) and the
    // dynamics step then reseeds qdot/qdotdot.
    bool alwaysKick = false;

    // A proposed conformation is VALID only if its potential energy is finite and
    // |peNew| <= clashThreshold * max(1, |pePre|). In other words, reject if the
    // proposed PE is more than clashThreshold times larger (in absolute value) than
    // the pre-kick PE -- an order-of-magnitude relative check. This handles both
    // free-space (~0 kJ/mol) and bound (~-2000 kJ/mol) regimes without a hard-coded
    // absolute ceiling. Default 10 = one order of magnitude. Enforced in EVERY mode
    // (AlwaysAccept means skip the Metropolis probability, not allow broken geometry).
    double clashThreshold = 10.0; // dimensionless factor

    // ABSOLUTE physical ceiling on a pose's potential energy [kJ/mol], shared by
    // the acceptance gate and the forced-kick rescue. The relative clashThreshold
    // alone is dangerous in the bound regime: at pePre ~ -2400 it admits poses up
    // to ~24000, so a clash at e.g. +9800 passes validity AND sits below the old
    // hard-coded 1e4 rescue ceiling -- a strained, non-integrable pose that becomes
    // an absorbing state (PE frozen, q restored every round). Tying both gates to
    // ONE absolute ceiling removes that dead band: nothing the acceptance gate lets
    // in can exceed what the rescue treats as bad. A pose this far above the bound
    // minimum is physically a clash, never a resting state.
    double maxStartPE = 5.0e3; // kJ/mol; entry ceiling == rescue ceiling

    // INITIAL KICK: before round 0, keep re-drawing the ligand position until
    // the proposal passes the clash gate (dPE <= maxStartPE). This guarantees
    // the simulation starts from a clash-free pose without burning real rounds.
    // maxInitialKickTries caps the retry loop; if no clean pose is found within
    // that budget the run throws rather than starting from a clashing geometry.
    // Set to 0 (default) to disable -- the first round handles placement as usual.
    int maxInitialKickTries = 0; // 0 = disabled; >0 = retry budget

    // ESCAPE HATCH (docking): max consecutive rejected docking moves tolerated from
    // the SAME carried-forward pose before a kick is FORCED regardless of energy
    // magnitude. A pose that is finite and below maxStartPE can still be locally
    // non-integrable (every reseeded trajectory diverges), so neither the energy
    // gate nor the rescue ceiling would fire -- and the move loops forever. This
    // counter guarantees no pose is a permanent trap: after this many stuck rounds
    // the ligand is relocated unconditionally, then the counter resets.
    int maxStuckRounds = 25;

    // Reversibility diagnostic cadence. 0 = OFF (default; preserves zero overhead).
    // N > 0 = run RobotEngine::checkReversibility every N generateSample() calls
    // (the first call is round 0, so N>0 also performs the startup check). The probe
    // integrates mdSteps forward + back at the world's timeStep from the freshly
    // seeded state, logs the relative round-trip residual, and warns if it is large
    // or non-finite. It is a NON-DESTRUCTIVE smoke test that certifies dt only for
    // the current configuration (the safe dt is configuration dependent); the
    // always-on guard remains the per-step corrector throw in verletStep. See
    // THEORY 5.7. Set from Python via the reversibility_check_every=N argument to
    // context.add_*_world() (which forwards to World::setReversibilityCheck).
    int reversibilityCheckInterval = 0;

    // ---- NCMC (MoveType::NcmcSwitch) -----------------------------------
    // Total protocol substeps; lambda ramps 1->0 then 0->1, one Verlet step per
    // substep (the torsional stride happens near the lambda~0 midpoint where the
    // mobile molecule is uncaged from all others). 0 => not an NCMC world.
    int ncmcSteps = 0;
    // Fraction of ncmcSteps held at lambda=0 between the down- and up-ramps.
    double ncmcHoldFraction = 0.0;
    // Atom-index range [begin,end) of the molecule decoupled from every other
    // molecule. Set by World::configureNcmc.
    int ncmcAtomBegin = -1;
    int ncmcAtomEnd = -1;
};

class World {
    public:
    World(int index, bool cartesian, std::uint32_t seed);

    // Build the immutable RobotModel once from the shared topology + this
    // world's per-bond mobilities + this world's root mobilities. NOTE: the
    // root-mobility vector is now a PER-WORLD argument (Context passes a global
    // default for ordinary worlds and a docking-specific one for docking
    // worlds), which is what makes "root mobility is a world property" true.
    void
    buildModel(const SystemTopology& sys, const Selection& sel, const std::vector& rootMobilities);

    // Override this world's root attachment to Ground. Root mobility is a
    // PER-WORLD property: these mutate only THIS world's copy of the
    // root-mobility vector and rebuild this world's RobotModel in place; they
    // never touch the shared SystemTopology, so different worlds can give the
    // same molecule different roots (e.g. a solvation shell where near waters
    // are Free and the bulk is Welded). buildModel(...) MUST have been called
    // once (by Context::add*World) first. Call these BEFORE add_sampler / mass
    // scaling, since rebuilding resets the per-body sampler state.
    //
    //   setRootMobility   : change ONE molecule (rebuilds once).
    //   setRootMobilities : replace the WHOLE vector and rebuild ONCE -- the
    //                       O(N)-not-O(N^2) path for setting many molecules
    //                       (e.g. thousands of solvent molecules at once).
    void setRootMobility(int moleculeIndex, JointType mobility);
    void setRootMobilities(const std::vector& rootMobilities);

    // Python: world.add_sampler(timeStep, mdSteps, acceptRejectMode, use_nuts,
    //                           sphere_factor=1.0, use_fixman=None)
    // sphere_factor scales the AUTO radius R_i = R_receptor + sphere_factor*
    // R_ligand_i per ligand; larger => guest may roam further past the receptor
    // surface. use_fixman == nullopt -> AUTO: ON for non-Cartesian worlds
    // (torsional + docking), forced OFF for Cartesian. boostMDSteps and the
    // kick_stride / local_kick_* knobs were removed (radius is now automatic and
    // the kick is conditional on leaving the sphere).
    World& add_sampler(double timeStep,
                       int mdSteps,
                       AcceptRejectMode mode,
                       bool useNuts,
                       double sphereFactor,
                       std::optional useFixman,
                       bool alwaysKick,
                       double clashThreshold,
                       int maxInitialKickTries,
                       std::optional distortOption = std::nullopt,
                       double nmaBiasScale = 1.0);

    // Mark this world as a docking world. ligandGroups[i] is the global atom
    // index list of ligand molecule i (each gets its own auto-sized sphere and is
    // repositioned independently); siteAtoms is the receptor atom list whose
    // centroid is the sphere centre. Called by Context::addDockingWorld.
    void configureDocking(std::vector<std::vector> ligandGroups, std::vector siteAtoms);

    // Mark this world as a per-molecule NCMC world: during the lambda:1->0->1
    // switch the intermolecular nonbonded between [atomBegin,atomEnd) and every
    // other molecule is alchemically softened (intramolecular physics untouched).
    // Call AFTER add_sampler (it sets moveType last). Vacuum/implicit only.
    void configureNcmc(int atomBegin, int atomEnd, int ncmcSteps, double holdFraction);

    void setAtomsLocationsInGround(const std::vector& atomPosG);
    [[nodiscard]] const robo::Vec3* getAtomsLocationsInGround() const {
        return state_.atomPosG();
    }

    // One Gibbs sample on this world. Returns true if accepted.
    bool generateSample();

    // Docking initialisation: keep drawing random ligand placements until the
    // post-kick PE change is below the clash ceiling, or the retry budget
    // (sampler_.maxInitialKickTries) is exhausted.  Returns the number of
    // attempts needed.  Throws if no clean pose was found within the budget.
    // Called by Context::runREX before round 0 when maxInitialKickTries > 0.
    int findGoodStartingPose();

    [[nodiscard]] const RobotModel& model() const {
        return model_;
    }
    [[nodiscard]] RobotState& state() {
        return state_;
    }
    [[nodiscard]] int index() const {
        return index_;
    }
    [[nodiscard]] bool isCartesian() const {
        return cartesian_;
    }
    [[nodiscard]] bool isDocking() const {
        return docking_;
    }

    // --- last-move telemetry (for the [rex] log) ---
    [[nodiscard]] bool lastAccepted() const {
        return lastAccepted_;
    }
    // Set by Context::runREX each round. During equilibration every world
    // behaves as AlwaysAccept regardless of its sampler_.acceptRejectMode,
    // so the burn-in warms up from the starting geometry without the
    // Metropolis gate blocking large-dH moves from an unrelaxed structure.
    void setEquilPhase(bool equil) {
        equilPhase_ = equil;
    }

    [[nodiscard]] bool lastKickApplied() const {
        return lastKickApplied_;
    }
    [[nodiscard]] double lastPE() const {
        return state_.energy.pe;
    }
    [[nodiscard]] double lastKE() const {
        return state_.energy.ke;
    }
    [[nodiscard]] double lastFixman() const {
        return state_.energy.fixman;
    }
    [[nodiscard]] double lastTotalEnergy() const {
        return state_.energy.total;
    }
    [[nodiscard]] const char* typeName() const {
        return cartesian_ ? "cartesian" : (docking_ ? "docking" : "torsional");
    }

    void setTemperature(double T);

    // Kinetic-metric preconditioning (fictitious mass; sampling only). Inflates
    // the spatial inertia used ONLY in the proposal (momentum draw, KE, Fixman
    // ln det M) for selected bodies, raising their stable dt ~sqrt(scale) with
    // zero configurational bias (see RobotModel::bodyMassScale). Call after
    // buildModel(). Typical use: setMassScaleByJoint(JointType::Free, 16.0) on a
    // solvent world to tame water libration.
    void setBodyMassScale(int body, double scale);
    void setMassScaleByJoint(JointType jt, double scale);

    // Enable/disable the periodic reversibility probe (THEORY 5.7). interval<=0
    // disables it; interval>0 runs it every `interval` generateSample() calls,
    // starting at round 0. Bound to Python as world.set_reversibility_check(...).
    void setReversibilityCheck(int interval);

    // Compute the Route B mass-weighted internal-coordinate Hessian at the given
    // (minimized) Ground-frame coordinates and store the softest non-trivial mode
    // as the per-DOF NMA direction consumed by reinitialize(). atomPosGFlat is
    // [x0,y0,z0, x1,...] in nm, global/OpenMM atom order. Returns omega^2 of the
    // chosen mode (sanity: should be > 0 at a real minimum). No-op on Cartesian worlds.
    double setNMASoftModeFromHessian(const std::vector& atomPosGFlat,
                                     double h = 1e-5,
                                     double zeroTol = 1e-6);

    private:
    // --- internal (torsional) HMC pieces ---
    void reinitialize(); // seed velocities, record initial H (incl. Fixman)
    bool metropolis(double Hold, double Hnew);
    double currentTotalEnergy(); // PE (OpenMM) + KE (engine) [+ Fixman - 1/2 RT logSineSqr]
    // NMA Route B kinetic correction RT*ln cosh(w.mu), w = M^(1/2) u / sqrt(RT).
    // Subtracted from the kinetic term in both Hold_ and Hnew so the acceptance
    // uses ke_mix = -RT*ln g(u|q) for the biased-mixture momentum draw. Returns 0
    // (strict no-op) unless DistortOption::NMA is active and nmaBias_ is set.
    double nmaKineticCorrection();
    bool ncmcMove();                    // the lambda-protocol HMC move (NcmcSwitch)
    double protocolLambda(int s) const; // lambda schedule, s in [0, ncmcSteps)
    void recomputeGeometry(const robo::Vec3* targets);

    // --- Fixman / coordinate-Jacobian corrections (torsional worlds only) ---
    // calcFixman   = 1/2 RT ( ln|M_phi| - ln|M_3N| ); ln|M_phi| via the O(n) ABA
    //                D-determinant (matrix-free, ALL bodies). |M_3N| is constant
    //                and cancels in dH, kept for an absolute value.
    // calcLogSineSqrGamma2 = sum over EVERY root body (not just molecule 0) of
    //                log(sin^2(pitch)) from the root-atom quaternion.
    double calcFixman();
    double calcLogSineSqrGamma2() const;

    // --- docking ---
    // Reposition ligands (pure proposal; relocate + reorient, no acceptance here).
    // forceAll=false: containment -- move a ligand only if its COM has left its
    // sphere. true (always_kick): perturb every ligand every round. The move is
    // judged in generateSample (Hold at pre-kick + energy validity check).
    // Returns true if any ligand was perturbed.
    bool repositionLigands(bool forceAll);
    double groupSphereRadius(int g) const;                             // R_receptor + sphereFactor*R_ligand_g
    robo::Vec3 sampleUniformInSphere(double radius);                   // uniform in a ball
    robo::Rotation sampleUniformRotation();                            // uniform on SO(3)
    robo::Vec3 atomSetCentroid(const std::vector& atoms) const;   // unweighted centre
    robo::Vec3 atomSetMassCenter(const std::vector& atoms) const; // mass-weighted COM
    double atomSetRadius(const std::vector& atoms, const robo::Vec3& center) const;

    int index_;
    bool cartesian_;
    bool docking_ = false;
    RobotModel model_;
    RobotState state_;
    ForceBridge bridge_;
    SamplerConfig sampler_;
    robo::ConstraintSet constraints_;

    // Docking bookkeeping (global atom indices, OpenMM order). One atom group per
    // ligand molecule; the receptor atoms define the sphere centre.
    std::vector<std::vector> ligandGroups_;
    std::vector siteAtoms_;
    bool lastAccepted_ = false;
    bool lastKickApplied_ = false;
    long generateSampleCalls_ = 0; // for the reversibility-check cadence (SamplerConfig)
    bool equilPhase_ = false;      // true during burn-in: AlwaysAccept overrides MH

    // Consecutive rejected docking moves from the current carried-forward pose.
    // Reset on any acceptance; when it reaches sampler_.maxStuckRounds a kick is
    // forced unconditionally so a locally non-integrable pose cannot trap the run.
    int dockingStuckCount_ = 0;

    double temperature_ = 300.0;
    double RT_ = 0;
    double beta_ = 0;

    // Constant Cartesian mass-matrix log-determinant ln|M_3N| = 3 * sum ln m_a.
    double lnDetMCartesian_ = 0.0;

    std::mt19937_64 rng_;
    std::normal_distribution gaussian_{0.0, 1.0};
    std::uniform_real_distribution uniform_{0.0, 1.0};

    // Per-DOF NMA velocity-scale factors for DistortOption::NMA. Sized to nu and
    // lazily initialised to 1.0 in reinitialize(); the simtk source read these
    // per mobilized body (getMobodUScaleFactor) but never populated them, so the
    // effective default is unity (NMA distortion == plain Gaussian draw).
    std::vector uScaleFactors_;

    // NMA Route B bias mu = uScaleFactors_ * sqrt(nu)/||uScaleFactors_|| (length-
    // restored; unit factors => mu = ones). Set per block in reinitialize(); the
    // momentum draw is the mixture Us = z +/- mu, and the acceptance correction
    // RT*ln cosh(w.mu) uses this same mu.
    std::vector nmaBias_;

    std::vector savedPosG_;
    std::vector savedQ_;
    double Hold_ = 0;

    std::vector frameFlat_;
    std::vector xpcFlat_;

    // Build inputs retained so setRootMobility(ies) can rebuild this world's
    // model in isolation. sys_ points at the Context-owned SystemTopology
    // (outlives every World); sel_ and rootMobilities_ are this world's own
    // copies. Captured on the first buildModel() call.
    const SystemTopology* sys_ = nullptr;
    Selection sel_;
    std::vector rootMobilities_;
};

