// ============================================================================
//  RobotBuilders.hpp -- hand-assemble RobotModel "robots" for engine tests,
//  WITHOUT the World/Context/OpenMM/molecule pipeline. A robot here is exactly
//  what Simbody/Robosample mean structurally: a tree of rigid bodies rooted on
//  the shared Ground (body 0). A molecular *system* is just a forest of such
//  trees sharing Ground -- so these builders let one test exercise several
//  robots at once, which is the whole point of "each molecule is a robot".
//
//  We populate only the fields the RobotEngine sweeps read: the body tree +
//  children CSR, the q/u layout (from RobotModel::jointNQ/jointNU, the single
//  source of truth), the static joint frames X_PF/X_BM, and per-body mass
//  properties. No atoms, no frame graph, no z-matrix -- those belong to the
//  geometry/transfer layer, not to the multibody mechanics under test here.
// ============================================================================
#pragma once

#include 

#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"
#include "robot_math.hpp"

namespace rtest {

using robo::Rotation;
using robo::Transform;
using robo::UnitInertia;
using robo::Vec3;

// One body to add to a robot: its parent (already-added) body index and joint.
struct BodySpec {
    int parent; // parent body index (0 == Ground)
    JointType joint;
    Transform X_PF; // inboard frame on the parent
    Transform X_BM; // outboard frame on this body
    robo::Real mass = robo::Real(1);
    Vec3 com_B = Vec3(0); // COM in body frame
    UnitInertia inertia_B = UnitInertia(robo::Real(0.4), robo::Real(0.5), robo::Real(0.6));
};

// Assemble a RobotModel from a list of body specs (index i -> body i+1; body 0
// is Ground). Parents must be < child (topological order), which is natural
// since a spec can only name an already-listed parent.
inline RobotModel buildForest(const std::vector& specs) {
    RobotModel m;
    const int B = static_cast(specs.size()) + 1; // + Ground
    m.numBodies = B;
    m.numAtoms = 0;

    m.bodyParent.assign(B, -1);
    m.bodyLevel.assign(B, 0);
    m.bodyJoint.assign(B, JointType::Rigid);
    m.bodyRootAtom.assign(B, -1);
    m.X_PF.assign(B, Transform());
    m.X_BM.assign(B, Transform());
    m.bodyMass.assign(B, robo::Real(0));
    m.bodyCom_B.assign(B, Vec3(0));
    m.bodyUnitInertia_B.assign(B, UnitInertia(robo::Real(0), robo::Real(0), robo::Real(0)));

    m.bodyQIndex.assign(B, 0);
    m.bodyNQ.assign(B, 0);
    m.bodyUIndex.assign(B, 0);
    m.bodyNU.assign(B, 0);
    m.bodyUSqIndex.assign(B, 0);

    int qc = 0, uc = 0, usq = 0;
    for (int i = 0; i < (int)specs.size(); ++i) {
        const int b = i + 1;
        const BodySpec& s = specs[i];
        m.bodyParent[b] = s.parent;
        m.bodyLevel[b] = m.bodyLevel[s.parent] + 1;
        m.bodyJoint[b] = s.joint;
        m.X_PF[b] = s.X_PF;
        m.X_BM[b] = s.X_BM;
        m.bodyMass[b] = s.mass;
        m.bodyCom_B[b] = s.com_B;
        m.bodyUnitInertia_B[b] = s.inertia_B;

        const int nq = RobotModel::jointNQ(s.joint);
        const int nu = RobotModel::jointNU(s.joint);
        m.bodyQIndex[b] = qc;
        m.bodyNQ[b] = nq;
        m.bodyUIndex[b] = uc;
        m.bodyNU[b] = nu;
        m.bodyUSqIndex[b] = usq;
        if (RobotModel::jointUsesQuaternion(s.joint)) {
            m.quaternionQStart.push_back(qc);
        }
        qc += nq;
        uc += nu;
        usq += nu * nu;
    }
    m.nq = qc;
    m.nu = uc;
    m.nuSq = usq;

    // children CSR (needed by the inward ABI / udot sweeps)
    std::vector<std::vector> kids(B);
    for (int b = 1; b < B; ++b) {
        kids[m.bodyParent[b]].push_back(b);
    }
    m.bodyChildrenBeg.assign(B, 0);
    m.bodyChildrenEnd.assign(B, 0);
    for (int b = 0; b < B; ++b) {
        m.bodyChildrenBeg[b] = (int)m.bodyChildren.size();
        for (int c : kids[b]) {
            m.bodyChildren.push_back(c);
        }
        m.bodyChildrenEnd[b] = (int)m.bodyChildren.size();
    }
    return m;
}

// Convenience: a single body of joint type `jt` attached straight to Ground,
// with random-but-fixed joint frames (so the test exercises non-trivial X_PF/
// X_BM, not just identity).
inline RobotModel buildSingle(JointType jt, Rng& rng) {
    BodySpec s;
    s.parent = 0;
    s.joint = jt;
    s.X_PF = Transform(rng.rotation(), rng.vec3());
    s.X_BM = Transform(rng.rotation(), rng.vec3());
    return buildForest({s});
}

// A single chain Ground -> joints[0] -> joints[1] -> ... (joints[0] must be a
// legal root). Every body gets random-but-fixed frames and mass. This is the
// Robosample analogue of Simbody TestAngleConversions' "one of every mobilizer
// in a chain" stress configuration.
inline RobotModel buildChain(const std::vector& joints, Rng& rng) {
    std::vector specs;
    for (int i = 0; i < (int)joints.size(); ++i) {
        BodySpec s;
        s.parent = i; // body i+1's parent is body i (Ground for the first)
        s.joint = joints[i];
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.5);
        s.com_B = rng.vec3(-0.25, 0.25);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        specs.push_back(s);
    }
    return buildForest(specs);
}

// ----------------------------------------------------------------------------
//  attachAtoms -- give a hand-built robot atoms (buildForest leaves numAtoms=0).
//  `stations_B` are in the BODY frame (the convention realizePosition consumes:
//  posG = X_GB.p + R_GB*station_B); `masses` are daltons (0 == virtual site).
//  ORDERING CONTRACT: call BEFORE RobotState::allocateFull(model) -- the state
//  sizes its per-atom arrays from model.numAtoms at allocation time.
//
//  (TestAtomTransfer.cpp has a sibling random/mass-deriving variant; this is the
//  explicit-placement form TestBuilders.cpp needs to check the station formula.)
// ----------------------------------------------------------------------------
inline void attachAtoms(RobotModel& m,
                        int body,
                        const std::vector& stations_B,
                        const std::vector& masses) {
    if (body < 0 || body >= m.numBodies) {
        return;
    }
    if (stations_B.size() != masses.size()) {
        return;
    }
    const int firstNew = m.numAtoms;
    for (std::size_t k = 0; k < stations_B.size(); ++k) {
        m.atomBody.push_back(body);
        m.atomMass.push_back(masses[k]);
        m.atomStation_B.push_back(stations_B[k]);
        m.atomDummIndex.push_back(-1);
        m.atomCompoundIndex.push_back(m.numAtoms);
        ++m.numAtoms;
    }
    if (m.bodyRootAtom[body] < 0 && !stations_B.empty()) {
        m.bodyRootAtom[body] = firstNew;
    }
    m.bodyAtoms.clear();
    m.bodyAtomsBeg.assign(static_cast(m.numBodies), 0);
    m.bodyAtomsEnd.assign(static_cast(m.numBodies), 0);
    for (int b = 0; b < m.numBodies; ++b) {
        m.bodyAtomsBeg[b] = static_cast(m.bodyAtoms.size());
        for (int a = 0; a < m.numAtoms; ++a) {
            if (m.atomBody[a] == b) {
                m.bodyAtoms.push_back(a);
            }
        }
        m.bodyAtomsEnd[b] = static_cast(m.bodyAtoms.size());
    }
}

// Fill q with a valid random configuration: scalars uniform, quaternion blocks a
// random unit quaternion (Shoemake). u is plain Gaussian.
inline void randomizeState(const RobotModel& m, RobotState& s, Rng& rng) {
    robo::Real* q = s.q();
    for (int i = 0; i < m.nq; ++i) {
        q[i] = rng.uniform(robo::Real(-1.5), robo::Real(1.5));
    }
    for (int qs : m.quaternionQStart) {
        const auto quat = rng.unitQuat();
        q[qs + 0] = quat.elems[0];
        q[qs + 1] = quat.elems[1];
        q[qs + 2] = quat.elems[2];
        q[qs + 3] = quat.elems[3];
    }
    robo::Real* u = s.u();
    for (int i = 0; i < m.nu; ++i) {
        u[i] = rng.gaussian(0, robo::Real(0.7));
    }
}

} // namespace rtest

#pragma once
// ============================================================================
//  robo_linalg.hpp -- small dense linear-algebra kernels for the articulated-
//  body dynamics (the dof x dof hinge block D = ~H P H, dof <= 6).
//
//  SINGLE SOURCE OF TRUTH. These were file-local statics in the anonymous
//  namespace of src/RobotEngine.cpp; they are hoisted here verbatim (only the
//  linkage qualifier changed to `inline` for header use) so that BOTH the engine
//  TU and the unit-test TU bind the *same* symbol. Previously tests exercised a
//  hand-synced copy (tests/RobotLinearAlgebra.hpp) that could silently drift
//  from the shipped code; that copy is now deleted and both sides #include this.
//
//  Consumers in the engine: invertDense -> D^-1 (=> M^-1 seed, udot);
//  symSqrt / symSqrtInv -> sqrt(D^-1)/sqrt(D) (the momentum draw); logDetSymPD
//  -> ln det(D) (the Fixman tree term). jacobiSymEig underlies all of them.
// ============================================================================

#include 
#include 

#include "robot_math.hpp"

namespace robo_linalg {

using robo::Real;

inline robo::Real logDetSymPD(const robo::Real* A, int n) {
    if (n <= 0) {
        return robo::Real(0);
    }
    robo::Real L[36]; // n <= 6
    for (int i = 0; i < n * n; ++i) {
        L[i] = robo::Real(0);
    }
    robo::Real logDet = robo::Real(0);
    for (int j = 0; j < n; ++j) {
        robo::Real sum = A[j * n + j];
        for (int k = 0; k < j; ++k) {
            sum -= L[j * n + k] * L[j * n + k];
        }
        // Guard against a non-finite / non-PD block (near-singular hinge): clamp
        // the pivot so the caller gets a large-but-finite Fixman rather than NaN,
        // which the Metropolis step can then reject cleanly.
        if (!(sum > robo::Real(1e-300))) {
            sum = robo::Real(1e-300);
        }
        const robo::Real Ljj = std::sqrt(sum);
        L[j * n + j] = Ljj;
        logDet += robo::Real(2) * std::log(Ljj);
        for (int i = j + 1; i < n; ++i) {
            robo::Real s = A[i * n + j];
            for (int k = 0; k < j; ++k) {
                s -= L[i * n + k] * L[j * n + k];
            }
            L[i * n + j] = s / Ljj;
        }
    }
    return logDet;
}

// Symmetric eigensolver (cyclic Jacobi) for a small dense symmetric matrix
// (n <= 6 here). Row-major input A[n*n]; outputs eigenvalues d[n] and
// eigenvectors as COLUMNS of V (V[i*n+k] = component i of eigenvector k).
// Self-contained: no SimTK::Eigen / LAPACK dependency (that symbol is not in
// the link line and produced an undefined-symbol ImportError).
inline void jacobiSymEig(const Real* Ain, int n, Real* d, Real* V) {
    Real a[36];
    for (int i = 0; i < n * n; ++i) {
        a[i] = Ain[i];
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            V[i * n + j] = (i == j) ? Real(1) : Real(0);
        }
    }
    for (int sweep = 0; sweep < 100; ++sweep) {
        Real off = 0;
        for (int p = 0; p < n; ++p) {
            for (int q = p + 1; q < n; ++q) {
                off += a[p * n + q] * a[p * n + q];
            }
        }
        if (off <= Real(1e-30)) {
            break;
        }
        for (int p = 0; p < n; ++p) {
            for (int q = p + 1; q < n; ++q) {
                const Real apq = a[p * n + q];
                if (apq == Real(0)) {
                    continue;
                }
                const Real app = a[p * n + p];
                const Real aqq = a[q * n + q];
                const Real theta = (aqq - app) / (2 * apq);
                const Real t =
                    (theta >= 0 ? Real(1) : Real(-1)) / (std::abs(theta) + std::sqrt(theta * theta + 1));
                const Real cs = Real(1) / std::sqrt(t * t + 1);
                const Real sn = t * cs;
                // A <- J^T A J  (rotate columns then rows of the (p,q) plane).
                for (int i = 0; i < n; ++i) {
                    const Real aip = a[i * n + p];
                    const Real aiq = a[i * n + q];
                    a[i * n + p] = cs * aip - sn * aiq;
                    a[i * n + q] = sn * aip + cs * aiq;
                }
                for (int i = 0; i < n; ++i) {
                    const Real api = a[p * n + i];
                    const Real aqi = a[q * n + i];
                    a[p * n + i] = cs * api - sn * aqi;
                    a[q * n + i] = sn * api + cs * aqi;
                }
                // V <- V J  (accumulate eigenvectors as columns).
                for (int i = 0; i < n; ++i) {
                    const Real vip = V[i * n + p];
                    const Real viq = V[i * n + q];
                    V[i * n + p] = cs * vip - sn * viq;
                    V[i * n + q] = sn * vip + cs * viq;
                }
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        d[i] = a[i * n + i];
    }
}

// Symmetric (Moore-Penrose) pseudo-inverse of the dof x dof articulated hinge
// matrix D = ~H P H, row-major in/out. D is symmetric and, for a well-posed
// hinge, SPD; this routine returns its inverse.
//
// CRITICAL ROBUSTNESS PROPERTY: a *degenerate* hinge -- a DOF with ~zero
// articulated inertia -- must be LOCKED, not regularized into a huge finite
// inverse. The canonical case is a single atom sitting exactly on its own
// torsion axis (D ~ 1e-33). It arises naturally once a ring-closing bond is
// removed and a ring atom (e.g. a proline/ring nitrogen) is left as a lone
// body whose root atom lies on the bond it rotates about; rotating a point
// mass on its own axis is unobservable, so the DOF has no dynamics.
//
// The previous code clamped such a D to +-1e-14 and returned 1/eps ~ 1e14.
// That inverse is enormous but FINITE, so it slips past the non-finite guard,
// multiplies the (tiny, noisy) force residual into a ~1e14 acceleration, and
// blows up on the next step -- exactly the observed failure. The correct
// action is a pseudo-inverse: invert the well-conditioned directions and set
// the inverse of any ~null direction to 0. DI=0 => G=0 => PPlus=P (full
// inertia passes through, i.e. the joint behaves as a weld) => udot=0 and the
// HMC seed velocity is 0 too. The DOF is frozen at its initial value, which is
// the physically exact treatment of a null coordinate.
inline void invertDense(const Real* A, int n, Real* Ainv) {
    const Real lockTol = Real(1e-12); // |eigenvalue| <= this is treated as null

    // Dominant case: 1-DOF Torsion. Closed form, with a lock instead of a clamp.
    if (n == 1) {
        const Real d = A[0];
        Ainv[0] = (std::abs(d) > lockTol) ? (Real(1) / d) : Real(0);
        return;
    }

    // n in {3,6}: symmetric pseudo-inverse via the in-house Jacobi eigensolver
    // (self-contained; no LAPACK/Eigen link dependency). For a non-degenerate
    // hinge every eigenvalue is well above tol, so this equals the true inverse;
    // any null eigendirection contributes 0 (that direction is locked).
    Real d[6];
    Real V[36];
    jacobiSymEig(A, n, d, V);
    Real scale = 0;
    for (int k = 0; k < n; ++k) {
        scale = std::max(scale, std::abs(d[k]));
    }
    const Real tol = std::max(lockTol, scale * Real(1e-12));
    for (int i = 0; i < n * n; ++i) {
        Ainv[i] = Real(0);
    }
    for (int k = 0; k < n; ++k) {
        if (std::abs(d[k]) <= tol) {
            continue; // null direction -> pseudo-inverse contributes 0 (locked)
        }
        const Real inv = Real(1) / d[k];
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                Ainv[i * n + j] += inv * V[i * n + k] * V[j * n + k];
            }
        }
    }
}

// dof==1 is a scalar sqrt; otherwise S = V diag(sqrt(lambda)) ~V, exactly as
// Simbody's multiplyBySqrtMInvPassOutward does (sqrtDI = U diag(sqrt) ~U).
inline void symSqrt(const Real* A, int n, Real* S) {
    if (n == 1) {
        S[0] = std::sqrt(std::max(Real(0), A[0]));
        return;
    }
    Real d[6];
    Real V[36];
    jacobiSymEig(A, n, d, V);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real acc = 0;
            for (int k = 0; k < n; ++k) {
                acc += V[i * n + k] * std::sqrt(std::max(Real(0), d[k])) * V[j * n + k];
            }
            S[i * n + j] = acc;
        }
    }
}

// Inverse symmetric square root of a dof x dof SPD block: S = V diag(1/sqrt(lambda)) ~V.
// This is the EXACT inverse of symSqrt (same eigenvectors, reciprocal sqrt eigenvalues),
// so symSqrtInv(A) * symSqrt(A) == I. Used by multiplyBySqrtM (the forward sqrt sweep).
// Verified numerically to ~2e-13 over random SPD blocks (dof 1..6).
inline void symSqrtInv(const Real* A, int n, Real* S) {
    if (n == 1) {
        S[0] = Real(1) / std::sqrt(std::max(Real(1e-300), A[0]));
        return;
    }
    Real d[6];
    Real V[36];
    jacobiSymEig(A, n, d, V);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real acc = 0;
            for (int k = 0; k < n; ++k) {
                acc += V[i * n + k] * (Real(1) / std::sqrt(std::max(Real(1e-300), d[k]))) * V[j * n + k];
            }
            S[i * n + j] = acc;
        }
    }
}

} // namespace robo_linalg

// ============================================================================
//  TestAlchemy.cpp -- the OpenMM-linked half of the alchemical/NCMC suite.
//
//  Exercises OpenMMContext's two alchemy code paths, driven by the single global
//  parameter lambda_inter, against INDEPENDENT hand-computed oracles:
//
//   A. THE VACUUM / IMPLICIT CORRECTION PATH (createAlchemyCorrectionForce, used
//      for NoCutoff / CutoffNonPeriodic). Adds (lambda-1)*standard over the A x
//      rest interaction group, so total A x rest == lambda * standard. We assert
//      EXACT linearity and lambda=1 fidelity to machine precision against a direct
//      Lorentz-Berthelot LJ + Coulomb A x rest sum.
//
//   B. THE EXPLICIT-SOLVENT DECOUPLING PATH (createAlchemyDecouplingForces, used
//      for CutoffPeriodic / Ewald / PME). Electrostatics via a charge offset
//      (effective q_A = lambda*q_A; openmmtools' "exact PME"); sterics via a
//      Beutler soft-core A x rest CustomNonbondedForce; plus a lambda-independent
//      intra-A LJ restorer. We assert:
//        - lambda=1 fidelity vs the unmodified field within MAX_DELTA (this is the
//          test that fails if the LJ long-range dispersion correction is dropped
//          from the soft-core force -- the bug fixed in createAlchemyDecoupling-
//          Forces; the unfixed offset is ~0.027 kJ/mol, far above MAX_DELTA);
//        - force-group isolation: the soft-core A x rest group is EXACTLY 0 at
//          lambda=0 and equals an independent minimum-image LJ A x rest sum at
//          lambda=1; the intra-A group is lambda-independent;
//        - soft-core finiteness: at lambda<1 the decoupled-atom energy stays
//          finite even at full overlap (r->0), where the hard LJ diverges;
//        - the charge offset reproduces a directly charge-scaled system under PME.
//
//   C. THE SHUTDOWN RESET regression: a stale alchemy range must not leak into a
//      subsequent plain initialize() on the process-wide singleton.
//
//  System builder mirrors the working probes: a small box of LJ+charge sites with
//  a 1-2 atom alchemical region (kept small so the residual CustomNonbondedForce
//  long-range-correction approximation stays well under MAX_DELTA).
//
//  Build (see run_alchemy_tests.sh): link the compiled production OpenMMContext.o
//  against libOpenMM; run with OPENMM_PLUGIN_DIR pointing at the wheel's plugins.
// ============================================================================
#include 
#include 
#include 
