#include "OpenMMContext.hpp"
#include "PeriodicBox.hpp"
#include "TestHelpers.hpp"


namespace {

constexpr double K_COULOMB = 138.935456; // kJ*nm/(mol*e^2), OpenMM's ONE_4PI_EPS0

// ---- system builder --------------------------------------------------------
struct Atom {
    double q, sigma, eps, x, y, z, mass;
};

SystemTopology
buildSystem(const std::vector& atoms, NonbondedMethod method, double box, double cutoff) {
    SystemTopology s;
    s.numAtoms = static_cast(atoms.size());
    s.numMolecules = static_cast(atoms.size()); // each atom its own molecule (no intramolecular bonds)
    s.nonbondedMethod = method;
    s.nonbondedCutoff = cutoff;
    if (box > 0) {
        s.boxVectors = {box, 0, 0, 0, box, 0, 0, 0, box};
    }
    for (const auto& a : atoms) {
        s.atomsCharge.push_back(a.q);
        s.atomsSigma.push_back(a.sigma);
        s.atomsEpsilon.push_back(a.eps);
        s.atomsMass.push_back(a.mass);
        s.atomsX.push_back(a.x);
        s.atomsY.push_back(a.y);
        s.atomsZ.push_back(a.z);
        s.atomsRadius.push_back(0);
        s.atomsScreen.push_back(0);
    }
    return s;
}

std::vector positions(const SystemTopology& s) {
    std::vector p;
    for (int a = 0; a < s.numAtoms; ++a) {
        p.emplace_back(s.atomsX[a], s.atomsY[a], s.atomsZ[a]);
    }
    return p;
}

// Independent A x rest standard nonbonded oracle (Lorentz-Berthelot, NO cutoff,
// NO periodicity): the exact thing the vacuum correction path scales by lambda.
double oracleAxRestVacuum(const SystemTopology& s, int aBegin, int aEnd) {
    double S = 0;
    for (int i = aBegin; i < aEnd; ++i) {
        for (int j = 0; j < s.numAtoms; ++j) {
            if (j >= aBegin && j < aEnd) {
                continue; // intra-A is excluded from the A x rest group
            }
            const double dx = s.atomsX[i] - s.atomsX[j];
            const double dy = s.atomsY[i] - s.atomsY[j];
            const double dz = s.atomsZ[i] - s.atomsZ[j];
            const double r = std::sqrt(dx * dx + dy * dy + dz * dz);
            const double eps = std::sqrt(s.atomsEpsilon[i] * s.atomsEpsilon[j]);
            const double sig = 0.5 * (s.atomsSigma[i] + s.atomsSigma[j]);
            const double sr6 = std::pow(sig / r, 6);
            S += 4 * eps * (sr6 * sr6 - sr6) + K_COULOMB * s.atomsCharge[i] * s.atomsCharge[j] / r;
        }
    }
    return S;
}

// Independent A x rest LJ-only oracle using the MINIMUM IMAGE under the box (no
// cutoff applied -- valid when every A-rest min-image distance is < cutoff, which
// we arrange). Matches the soft-core force at lambda=1 (where the soft core
// reduces to standard LJ). Uses the SAME robo::pbc::minimumImage the production
// PBC path uses, tying this oracle to shipped infrastructure.
double oracleAxRestLJMinImage(const SystemTopology& s, int aBegin, int aEnd) {
    double S = 0;
    for (int i = aBegin; i < aEnd; ++i) {
        for (int j = 0; j < s.numAtoms; ++j) {
            if (j >= aBegin && j < aEnd) {
                continue;
            }
            const double pa[3] = {s.atomsX[i], s.atomsY[i], s.atomsZ[i]};
            const double pb[3] = {s.atomsX[j], s.atomsY[j], s.atomsZ[j]};
            const double r = robo::pbc::minimumImageDistance(pa, pb, s.boxVectors.data());
            const double eps = std::sqrt(s.atomsEpsilon[i] * s.atomsEpsilon[j]);
            const double sig = 0.5 * (s.atomsSigma[i] + s.atomsSigma[j]);
            const double sr6 = std::pow(sig / r, 6);
            S += 4 * eps * (sr6 * sr6 - sr6);
        }
    }
    return S;
}

// Platform-portable energy closeness. Accelerated platforms (CUDA/OpenCL) use
// mixed-precision accumulation and per-run-nondeterministic reduction order, so
// energies agree to a RELATIVE precision tied to their magnitude, NOT to the
// double ULP. (An absolute 1e-13 tolerance on a ~10^3 kJ/mol energy is below the
// ULP there and silently degrades EXPECT_NEAR into bitwise equality.) Compare
// with a relative tolerance plus a small absolute floor.
::testing::AssertionResult energyClose(double a, double b, double rtol = 1e-6, double atol = 1e-4) {
    const double tol = rtol * std::max(std::abs(a), std::abs(b)) + atol;
    if (std::abs(a - b) <= tol) {
        return ::testing::AssertionSuccess();
    }
    return ::testing::AssertionFailure() << a << " vs " << b << " differ by " << std::abs(a - b) << " > tol "
                                         << tol << " (rtol=" << rtol << ", atol=" << atol << ")";
}

double groupEnergy(const std::vector& groups, const std::string& name) {
    for (const auto& g : groups) {
        if (g.name == name) {
            return g.energy;
        }
    }
    return std::nan("");
}

// A 1-atom alchemical solute (A) inside a small cubic box of LJ+charge sites,
// arranged so all A-rest separations are inside the cutoff (the min-image oracle
// then matches the cutoff'd soft-core sum at lambda=1).
std::vector solvatedSystem() {
    return {
        {+0.5, 0.31, 0.6, 1.00, 1.00, 1.00, 16.0}, // A (atom 0)
        {-0.25, 0.30, 0.5, 0.62, 1.00, 1.00, 16.0},
        {+0.25, 0.30, 0.5, 1.40, 1.00, 1.00, 16.0},
        {-0.25, 0.30, 0.5, 1.00, 0.62, 1.00, 16.0},
        {+0.25, 0.30, 0.5, 1.00, 1.38, 1.00, 16.0},
        {-0.25, 0.30, 0.5, 1.00, 1.00, 0.64, 16.0},
        {+0.25, 0.30, 0.5, 1.00, 1.00, 1.40, 16.0},
    };
}

// openmmtools' alchemical-energy comparison tolerance is ~1 kcal/mol; we hold the
// decoupling path to a much tighter 0.01 kJ/mol. The dispersion-correction fix
// brings lambda=1 to ~0.0045 kJ/mol (residual = the interaction-group-unaware
// Tight tolerance for the pairwise soft-core sterics vs. the LJ oracle. This is
// the part of lambda=1 fidelity that IS platform-independent and physically
// meaningful: at lambda=1 the soft core must reduce to the standard A x rest LJ.
constexpr double MAX_DELTA = 1.0e-2; // kJ/mol

// Total-energy lambda=1 fidelity is limited by ONE thing the alchemical decompo-
// sition cannot reproduce bit-for-bit: the LJ long-range (dispersion) tail of the
// decoupled atoms. Zeroing A's epsilon in the main NonbondedForce drops A from
// MAIN's analytic tail correction, and the only place to put it back is the
// soft-core CustomNonbondedForce -- but OpenMM's CustomNonbondedForce tail
// correction is documented NOT to support interaction groups (it assumes all
// pairs). So the compensation is platform-dependent: the Reference platform
// computes an approximate all-pairs correction (residual ~0.004 kJ/mol here), the
// CUDA/OpenCL platforms do not apply it at all (residual ~0.027 kJ/mol). Both are
// small (~0.01 kT) constants that, being configuration-independent, cancel in an
// NCMC acceptance taken within a single alchemical context. openmmtools carries
// the identical limitation. We therefore hold lambda=1 fidelity to:
//   - the tight MAX_DELTA on the Reference platform, where the correction applies
//     (this also regression-guards the setUseLongRangeCorrection fix);
//   - a tail-scale tolerance elsewhere, large enough to absorb the unrecovered
//     dispersion tail yet far below any REAL lambda=1 breakage (a wrong charge
//     offset or a soft core not reducing to LJ would deviate by order the full
//     A x rest interaction, ~1+ kJ/mol).
#if defined(USE_REFERENCE) && (USE_REFERENCE)
constexpr double LAMBDA1_TOTAL_TOL = 1.0e-2; // kJ/mol; Reference applies the LRC
#else
constexpr double LAMBDA1_TOTAL_TOL = 1.0e-1; // kJ/mol; accelerated platforms: tolerate the dispersion tail
#endif

} // namespace

// ===========================================================================
//  A. Vacuum / implicit correction path (NoCutoff)
// ===========================================================================

// Linearity + lambda=1 fidelity: E(lambda) == E_plain + (lambda-1)*S, with S the
// independent A x rest standard sum. This is the cleanest statement of "alchemy
// only rescales the A<->rest coupling, linearly, and reproduces the true field at
// lambda=1". We compare with a RELATIVE tolerance: on the Reference platform the
// agreement is bitwise, but on CUDA/OpenCL the energy is accumulated in mixed
// precision, so the meaningful check is relative, not at the double ULP. The
// system is deliberately well-conditioned (all pairs near the LJ minimum, no
// near-overlap) so the energy magnitude does not swamp the A x rest signal.
TEST(AlchemyVacuum, Lambda1FidelityAndExactLinearity) {
    auto& omm = OpenMMContext::get();
    const std::vector atoms = {
        {+0.4, 0.30, 0.50, 0.00, 0.00, 0.00, 12.0}, // A (atom 0)
        {-0.4, 0.32, 0.40, 0.42, 0.00, 0.00, 12.0}, // rest...
        {+0.3, 0.31, 0.45, 0.00, 0.44, 0.00, 14.0},
        {-0.3, 0.29, 0.55, 0.00, 0.00, 0.46, 14.0},
    };
    SystemTopology s = buildSystem(atoms, NonbondedMethod::NoCutoff, /*box*/ 0, /*cutoff*/ 0.9);
    const auto pos = positions(s);

    omm.shutdown();
    omm.initialize(s);
    const double Eplain = omm.computePotentialEnergy(pos);

    omm.shutdown();
    omm.enableAlchemy(0, 1); // A = atom 0
    omm.initialize(s);

    const double S = oracleAxRestVacuum(s, 0, 1);
    for (double lam : {1.0, 0.75, 0.5, 0.25, 0.0}) {
        omm.setAlchemicalLambda(lam);
        const double E = omm.computePotentialEnergy(pos);
        const double pred = Eplain + (lam - 1.0) * S;
        EXPECT_TRUE(energyClose(E, pred)) << "lambda=" << lam << " not on the exact A x rest line";
    }

    // lambda=1 reproduces the unmodified field.
    omm.setAlchemicalLambda(1.0);
    EXPECT_TRUE(energyClose(omm.computePotentialEnergy(pos), Eplain)) << "lambda=1 fidelity";

    // At lambda=0 the A<->rest coupling is fully removed: E == Eplain - S.
    omm.setAlchemicalLambda(0.0);
    EXPECT_TRUE(energyClose(omm.computePotentialEnergy(pos), Eplain - S)) << "lambda=0 decoupling";
}

// ===========================================================================
//  B. Explicit-solvent decoupling path (CutoffPeriodic / Ewald / PME)
// ===========================================================================

// lambda=1 fidelity for every periodic method, up to the decoupled atoms' LJ
// dispersion tail (see LAMBDA1_TOTAL_TOL). On Reference the tolerance is tight and
// also guards the setUseLongRangeCorrection fix; on accelerated platforms it
// tolerates the unrecovered tail (a small, configuration-independent constant)
// while still catching any real lambda=1 breakage, which would be far larger.
TEST(AlchemyDecoupling, Lambda1FidelityAcrossPeriodicMethods) {
    auto& omm = OpenMMContext::get();
    for (NonbondedMethod method :
         {NonbondedMethod::CutoffPeriodic, NonbondedMethod::Ewald, NonbondedMethod::PME}) {
        SystemTopology s = buildSystem(solvatedSystem(), method, /*box*/ 2.0, /*cutoff*/ 0.6);
        const auto pos = positions(s);

        omm.shutdown();
        omm.initialize(s);
        const double Eplain = omm.computePotentialEnergy(pos);

        omm.shutdown();
        omm.enableAlchemy(0, 1);
        omm.initialize(s);
        omm.setAlchemicalLambda(1.0);
        const double E1 = omm.computePotentialEnergy(pos);

        EXPECT_NEAR(E1, Eplain, LAMBDA1_TOTAL_TOL)
            << "lambda=1 fidelity broken beyond the dispersion-tail scale (method "
            << static_cast(method) << "); a residual this large is not the LJ tail but a real "
            << "decoupling error (charge offset or soft-core not reducing to LJ at lambda=1)";
    }
}

// Force-group isolation: with separate force groups, the soft-core A x rest group
// is EXACTLY 0 at lambda=0 (LJ fully decoupled) and equals the independent
// min-image LJ A x rest sum at lambda=1; the intra-A restorer is lambda-independent.
TEST(AlchemyDecoupling, SoftcoreForceGroupIsolation) {
    auto& omm = OpenMMContext::get();
    SystemTopology s = buildSystem(solvatedSystem(), NonbondedMethod::PME, 2.0, 0.6);
    const auto pos = positions(s);

    omm.shutdown();
    omm.setSeparateForceGroups(true);
    omm.enableAlchemy(0, 1);
    omm.initialize(s);

    omm.setAlchemicalLambda(0.0);
    auto [E0, groups0] = omm.computePotentialEnergyByGroup(pos);
    const double soft0 = groupEnergy(groups0, "AlchemySoftcoreAxR");
    const double intra0 = groupEnergy(groups0, "AlchemyIntraAxA");

    omm.setAlchemicalLambda(1.0);
    auto [E1, groups1] = omm.computePotentialEnergyByGroup(pos);
    const double soft1 = groupEnergy(groups1, "AlchemySoftcoreAxR");
    const double intra1 = groupEnergy(groups1, "AlchemyIntraAxA");

    ASSERT_FALSE(std::isnan(soft0)) << "AlchemySoftcoreAxR force group not found";

    // lambda=0: A x rest sterics fully off, bitwise zero (the soft-core prefactor
    // lambda_inter multiplies the whole expression, so even its tail correction
    // vanishes).
    EXPECT_DOUBLE_EQ(soft0, 0.0);
    // lambda=1: the soft core reduces to standard LJ over A x rest. The group
    // energy is the within-cutoff pairwise sum (== our min-image oracle, since
    // every A-rest pair is inside the 0.6 nm cutoff and the nearest periodic image
    // is >1.5 nm away) PLUS the analytic LJ long-range dispersion tail the soft
    // force now carries. That tail is the ~0.02 kJ/mol offset below; the TOTAL
    // lambda=1 fidelity against the true field is validated to MAX_DELTA in
    // Lambda1FidelityAcrossPeriodicMethods, so here we only check the pairwise
    // part matches with an LRC-inclusive tolerance.
    const double ljOracle = oracleAxRestLJMinImage(s, 0, 1);
    EXPECT_NEAR(soft1, ljOracle, 0.05) << "soft-core A x rest != standard LJ (+tail) at lambda=1";
    EXPECT_LT(soft1, 0.0) << "A x rest LJ should be attractive here";
    // intra-A restorer carries no A-with-A pairs here (single-atom A) and is
    // lambda-independent regardless -- bitwise identical across lambda.
    EXPECT_DOUBLE_EQ(intra0, intra1);
}

// Soft-core finiteness: a decoupled atom may overlap a solvent atom (r->0) during
// the uncaged stride. The Beutler soft core keeps the A x rest energy FINITE at
// lambda<1, whereas the hard 1/r^12 LJ (lambda=1) diverges. This is exactly the
// property that lets NCMC push lambda->0 without catastrophic forces.
TEST(AlchemyDecoupling, SoftcoreFiniteAtOverlap) {
    auto& omm = OpenMMContext::get();
    // A (atom 0) sits essentially ON TOP of a solvent atom (atom 1).
    std::vector atoms = {
        {+0.3, 0.31, 0.6, 1.000, 1.0, 1.0, 16.0},  // A
        {-0.3, 0.30, 0.5, 1.0003, 1.0, 1.0, 16.0}, // overlapping solvent atom
        {+0.2, 0.30, 0.5, 1.40, 1.0, 1.0, 16.0},
        {-0.2, 0.30, 0.5, 1.00, 1.4, 1.0, 16.0},
    };
    SystemTopology s = buildSystem(atoms, NonbondedMethod::PME, 2.0, 0.6);
    const auto pos = positions(s);

    omm.shutdown();
    omm.setSeparateForceGroups(true);
    omm.enableAlchemy(0, 1);
    omm.initialize(s);

    // lambda=0.5: soft core active -> A x rest sterics finite despite the overlap.
    omm.setAlchemicalLambda(0.5);
    auto [Ehalf, gHalf] = omm.computePotentialEnergyByGroup(pos);
    const double softHalf = groupEnergy(gHalf, "AlchemySoftcoreAxR");
    EXPECT_TRUE(std::isfinite(softHalf)) << "soft-core energy non-finite at overlap";
    EXPECT_LT(std::abs(softHalf), 1.0e4) << "soft core did not tame the overlap (got " << softHalf << ")";

    // lambda=1: hard LJ -> the A x rest sterics blow up (the thing the soft core avoids).
    omm.setAlchemicalLambda(1.0);
    auto [Eone, gOne] = omm.computePotentialEnergyByGroup(pos);
    const double softOne = groupEnergy(gOne, "AlchemySoftcoreAxR");
    EXPECT_GT(softOne, 1.0e6) << "hard LJ should diverge at near-overlap but soft core was " << softOne;
}

// Charge offset == direct charge scaling under PME ("exact PME"). With LJ turned
// off everywhere, the only alchemical effect is the electrostatic charge offset
// q_A -> lambda*q_A. We compare the alchemical system at lambda to a SEPARATELY
// built plain system whose atom-0 charge is literally lambda*q_A. PME of identical
// charge distributions must agree -- this is the property the openmmtools-style
// exact treatment guarantees (and it is NOT mere linearity: the reciprocal-space
// self/cross terms make E quadratic in lambda for the A self-interaction).
TEST(AlchemyDecoupling, ChargeOffsetMatchesScaledChargeSystemPME) {
    auto& omm = OpenMMContext::get();
    std::vector base = {
        {+0.6, 0.30, 0.0, 1.00, 1.0, 1.0, 16.0}, // A, LJ eps = 0
        {-0.3, 0.30, 0.0, 0.70, 1.0, 1.0, 16.0},
        {-0.3, 0.30, 0.0, 1.30, 1.0, 1.0, 16.0},
        {+0.0, 0.30, 0.0, 1.00, 1.3, 1.0, 16.0},
    };
    SystemTopology sAlch = buildSystem(base, NonbondedMethod::PME, 2.0, 0.6);
    const auto pos = positions(sAlch);

    omm.shutdown();
    omm.enableAlchemy(0, 1);
    omm.initialize(sAlch);

    for (double lam : {1.0, 0.6, 0.25, 0.0}) {
        omm.setAlchemicalLambda(lam);
        const double Ealch = omm.computePotentialEnergy(pos);

        // Reference: plain system with atom-0 charge scaled to lam*q.
        std::vector scaled = base;
        scaled[0].q = lam * base[0].q;
        SystemTopology sRef = buildSystem(scaled, NonbondedMethod::PME, 2.0, 0.6);
        omm.shutdown();
        omm.initialize(sRef);
        const double Eref = omm.computePotentialEnergy(pos);

        EXPECT_NEAR(Ealch, Eref, 5.0e-3)
            << "charge-offset alchemy != directly charge-scaled system at lambda=" << lam;

        // restore the alchemical system for the next iteration
        omm.shutdown();
        omm.enableAlchemy(0, 1);
        omm.initialize(sAlch);
    }
}

// ===========================================================================
//  C. shutdown() reset regression
// ===========================================================================

// A prior alchemy run must not leak its atom range into a later plain
// initialize() on the process-wide singleton. Before the shutdown() fix, the
// stale alchemyEnabled/Begin/End would make the next initialize() wrongly build a
// decoupling force over the old range -- which would shift the plain energy by a
// sizable fraction of that range's nonbonded interaction (order ~1 kJ/mol here).
//
// We can't assert bitwise equality across re-inits on accelerated platforms: CUDA
// destroys/recreates its context (PME FFT plans, buffers) per initialize(), which
// is not bit-reproducible run-to-run. So we first MEASURE that baseline reinit
// jitter (plain -> shutdown -> plain, no alchemy), then require that inserting a
// full alchemy session in between perturbs the subsequent plain energy by no more
// than that baseline plus a small margin -- and, separately, by far less than a
// real leaked decoupling force ever could.
TEST(AlchemyShutdown, StaleAlchemyStateDoesNotLeak) {
    auto& omm = OpenMMContext::get();
    SystemTopology s = buildSystem(solvatedSystem(), NonbondedMethod::PME, 2.0, 0.6);
    const auto pos = positions(s);

    // Fresh plain reference.
    omm.shutdown();
    omm.initialize(s);
    const double Eref = omm.computePotentialEnergy(pos);

    // Baseline: plain -> shutdown -> plain again, NO alchemy. Captures the
    // platform's context-reinit nondeterminism (bitwise 0 on Reference).
    omm.shutdown();
    omm.initialize(s);
    const double Eplain0 = omm.computePotentialEnergy(pos);
    const double jitter = std::abs(Eplain0 - Eref);

    // Run a full alchemy session with separate force groups + a non-trivial range...
    omm.shutdown();
    omm.setSeparateForceGroups(true);
    omm.enableAlchemy(0, 2);
    omm.initialize(s);
    omm.setAlchemicalLambda(0.3);
    (void)omm.computePotentialEnergy(pos);

    // ...then shutdown and bring up a PLAIN system again.
    omm.shutdown();
    omm.initialize(s);
    const double Eplain = omm.computePotentialEnergy(pos);

    // The alchemy session must add NO more deviation than a plain re-init does
    // (plus a small absolute margin for path-dependent reinit jitter). If any
    // alchemy/force-group state leaked, a decoupling force would reappear over the
    // stale [0,2) range and blow far past this.
    const double margin = std::max(5.0 * jitter, 0.1); // kJ/mol
    EXPECT_LT(std::abs(Eplain - Eref), margin)
        << "alchemy session perturbed a later plain init beyond reinit jitter "
        << "(Eref=" << Eref << ", Eplain=" << Eplain << ", baseline jitter=" << jitter << ")";

    // And it is nowhere near a real force leak (which would be order >= 1 kJ/mol).
    EXPECT_LT(std::abs(Eplain - Eref), 1.0) << "stale decoupling force appears to have leaked";
}

// ============================================================================
//  TestAnalyticForce.cpp -- Phase 1: self-tests for the AnalyticForceBridge
//  harness (the keystone that makes integrator/energy/ensemble tests OpenMM-free).
//
//  The harness is only trustworthy as an oracle if (a) its force really is the
//  negative gradient of its stated potential, and (b) its per-atom -> per-body
//  reduction is byte-identical to the production ForceBridge reduction. These
//  tests pin both, each with an explicit must-FAIL control.
// ============================================================================
#include 
#include 
#include 

#include "AnalyticForceBridge.hpp"
#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::attachAtoms;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

RobotModel twoBodyWithAtoms(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.0);
        s.com_B = rng.vec3(-0.2, 0.2);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        return s;
    };
    RobotModel m = buildForest({mk(0, JointType::Free), mk(1, JointType::Torsion)});
    attachAtoms(m, 1, {Vec3(0.0, 0.0, 0.0), Vec3(0.10, -0.03, 0.05)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.0, 0.12, 0.0), Vec3(-0.04, 0.0, 0.07)}, {16.0, 1.0});
    return m;
}

} // namespace

// ---------------------------------------------------------------------------
//  ForceMatchesNegGradU: per-atom force == -dU/dr_a by central FD on the
//  Cartesian atom position. U is a pure function of the flat atom-position
//  array (calcPotentialEnergyAt), so each component is perturbed independently.
//  This certifies the harness IS conservative -- the property energy tests need.
// ---------------------------------------------------------------------------
TEST(AnalyticForce, ForceMatchesNegGradU) {
    Rng rng(0xA1F0);
    RobotModel m = twoBodyWithAtoms(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    AnalyticForceBridge bridge(m, s, /*k=*/250.0); // anchors = these start positions

    // move OFF the anchors so forces are nonzero
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    std::vector base(s.atomPosG(), s.atomPosG() + m.numAtoms);
    const Real h = 1e-6;
    for (int a = 0; a < m.numAtoms; ++a) {
        if (m.atomMass[a] == Real(0)) {
            continue;
        }
        const Vec3 F = bridge.atomForceAt(base.data(), a);
        for (int i = 0; i < 3; ++i) {
            std::vector p = base;
            p[static_cast(a)][i] += h;
            const Real up = bridge.calcPotentialEnergyAt(p.data(), m.numAtoms);
            p[static_cast(a)][i] -= 2 * h;
            const Real um = bridge.calcPotentialEnergyAt(p.data(), m.numAtoms);
            const Real dUdr = (up - um) / (2 * h);
            EXPECT_NEAR(-dUdr, F[i], rtest::kFD) << "atom " << a << " comp " << i;
        }
    }
}

// ---------------------------------------------------------------------------
//  ReductionMatchesRealBridge: bodyForceG from evaluate() equals the hand
//  reduction (sum f ; sum (r_a - X_GB[b].p()) % f) to kTight.
//  MUST-FAIL guard: the moment about X_BM.p() (a constant body-frame point)
//  instead of the body origin must NOT reproduce the bridge's angular row.
// ---------------------------------------------------------------------------
TEST(AnalyticForce, ReductionMatchesRealBridge) {
    Rng rng(0xA1F1);
    RobotModel m = twoBodyWithAtoms(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    AnalyticForceBridge bridge(m, s, 180.0);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);
    bridge.evaluate(s);

    const SpatialVec* BF = s.bodyForceG();
    const Vec3* posG = s.atomPosG();
    const Transform* X_GB = s.X_GB();

    std::vector lin(static_cast(m.numBodies), Vec3(0));
    std::vector ang(static_cast(m.numBodies), Vec3(0));
    std::vector angWrong(static_cast(m.numBodies), Vec3(0));
    for (int a = 0; a < m.numAtoms; ++a) {
        if (m.atomMass[a] == Real(0)) {
            continue;
        }
        const int b = m.atomBody[a];
        const Vec3 f = bridge.atomForce(s, a);
        lin[static_cast(b)] += f;
        ang[static_cast(b)] += (posG[a] - X_GB[b].p()) % f;        // correct: body origin
        angWrong[static_cast(b)] += (posG[a] - m.X_BM[b].p()) % f; // wrong lever
    }

    bool anyAngDiffersFromWrong = false;
    for (int b = 1; b < m.numBodies; ++b) {
        EXPECT_TRUE(rtest::NearVec3(BF[b][1], lin[static_cast(b)], rtest::kTight))
            << "linear body " << b;
        EXPECT_TRUE(rtest::NearVec3(BF[b][0], ang[static_cast(b)], rtest::kTight))
            << "angular body " << b;
        if (!rtest::NearVec3(BF[b][0], angWrong[static_cast(b)], 1e-9)) {
            anyAngDiffersFromWrong = true;
        }
    }
    // must-fail control: the wrong-origin moment must differ on at least one body
    // (a robot whose every atom sits at X_BM would be degenerate; ours does not).
    EXPECT_TRUE(anyAngDiffersFromWrong)
        << "angular row matched the WRONG lever origin (X_BM.p) -- convention not pinned";
}

// ---------------------------------------------------------------------------
//  VirtualSiteSkipped: an atomMass==0 site contributes ZERO to bodyForceG.
//  MUST-FAIL guard: the force the site WOULD carry if (wrongly) counted is
//  nonzero, so including it would change the body's linear row.
// ---------------------------------------------------------------------------
TEST(AnalyticForce, VirtualSiteSkipped) {
    Rng rng(0xA1F2);
    BodySpec root;
    root.parent = 0;
    root.joint = JointType::Free;
    root.X_PF = Transform(rng.rotation(), rng.vec3());
    root.X_BM = Transform(rng.rotation(), rng.vec3());
    root.mass = 1.0;
    RobotModel m = buildForest({root});
    // one real atom (mass 12) and one VIRTUAL site (mass 0)
    attachAtoms(m, 1, {Vec3(0.05, 0.0, 0.0), Vec3(0.0, 0.07, 0.0)}, {12.0, 0.0});

    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);
    AnalyticForceBridge bridge(m, s, 200.0);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);
    bridge.evaluate(s);

    const SpatialVec* BF = s.bodyForceG();
    const Vec3* posG = s.atomPosG();
    const Transform* X_GB = s.X_GB();

    // expected: only the REAL atom (index 0) contributes
    const Vec3 fReal = bridge.atomForce(s, 0);
    EXPECT_TRUE(rtest::NearVec3(BF[1][1], fReal, rtest::kTight));
    EXPECT_TRUE(rtest::NearVec3(BF[1][0], (posG[0] - X_GB[1].p()) % fReal, rtest::kTight));

    // the site genuinely carries no force
    EXPECT_TRUE(rtest::NearVec3(bridge.atomForce(s, 1), Vec3(0), rtest::kTight));

    // must-fail control: the site IS displaced from its anchor, so the harmonic
    // force it WOULD carry is nonzero -- including it would change BF[1].linear.
    const Vec3 fSiteIfCounted = (bridge.anchor(1) - posG[1]) * bridge.stiffness();
    EXPECT_GT(fSiteIfCounted.norm(), 1e-6) << "site not displaced -> test is vacuous; reseed";
    EXPECT_FALSE(rtest::NearVec3(BF[1][1], fReal + fSiteIfCounted, rtest::kTight))
        << "body force includes the virtual-site contribution -- skip was lost";
}

// ============================================================================
//  TestAtomTransfer.cpp -- the ATOM/TRANSFER layer the engine suite never
//  exercised. RobotBuilders.hpp deliberately builds models with numAtoms == 0
//  ("no atoms ... those belong to the geometry/transfer layer"), so every test
//  that ships today validates the multibody MECHANICS on a bare body tree and
//  leaves the boundary that the original molmodel/DuMM "problematic calls" were
//  all about completely untested:
//
//    original molmodel/DuMM call                  ported responsibility (current)
//    ------------------------------------------   --------------------------------
//    DuMM::bsetAtomStationOnBody / station_B      RobotModel::atomStation_B
//    CompoundAtom::setFrameInMobilizedBodyFrame   atomStation_B (+ body frame)
//    getAtomStationOnBody / getLocationInMBF      (~X_GB[b]) * atomPosG  (invariant)
//    calcAtomLocationInGroundFrameThroughSimbody  RobotEngine::realizePosition tail
//      / DuMM::realizeSubsystemPositionImpl         + fillAtomPositionsFromBodies
//    updIncludedAtomStation/getIncludedAtomStn    RobotState::atomStationG (R_GB*station)
//    calcAtomVelocityInGroundFrame                V_GB rigid transport to the atom
//    calcAtomAccelerationInGroundFrame            A_GB + V_GB rigid point accel
//    DuMM::calcMassProperties ("we do it ourselves")  bodyMass/Com_B/UnitInertia_B
//                                                     -> Mk_G in realizePosition
//    HMCSampler::sampleIteration accept-path       transfer round trip
//      target locations <-> internal state
//
//  These are all engine/model-level facts (no World, no OpenMM, no frame graph),
//  so they are tested here the same way the rest of the suite tests mechanics:
//  hand-built RobotModels, deterministic RNG, finite-difference cross-checks.
//  The CONSTRAINTS chosen below are the ones the original code silently relied
//  on; see each test's banner for the precise invariant and its tolerance.
// ============================================================================
#include 
#include 
#include 

#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// ---------------------------------------------------------------------------
//  Attach `perBody` random atoms to every non-Ground body of an already-built
//  model, then DERIVE the body mass properties from those atom point masses --
//  exactly as World::recomputeGeometry does (bodyMass = sum m, com = mass-
//  weighted station mean, unit inertia = sum Inertia(station,m) / mass). This
//  makes the model's mass properties and its atoms self-consistent, which is the
//  precondition the engine's Mk_G build assumes.
// ---------------------------------------------------------------------------
void attachAtoms(RobotModel& m, Rng& rng, int perBody = 3) {
    const int B = m.numBodies;
    m.atomBody.clear();
    m.atomStation_B.clear();
    m.atomMass.clear();

    std::vector<std::vector> bodyAtoms(B);
    for (int b = 1; b < B; ++b) {
        for (int k = 0; k < perBody; ++k) {
            const int a = static_cast(m.atomBody.size());
            m.atomBody.push_back(b);
            m.atomStation_B.push_back(rng.vec3(Real(-0.3), Real(0.3)));
            m.atomMass.push_back(rng.uniform(Real(1.0), Real(16.0))); // ~H..O daltons
            bodyAtoms[b].push_back(a);
        }
    }
    m.numAtoms = static_cast(m.atomBody.size());

    // body-sorted atom CSR (optional for the engine, used by our own sums)
    m.bodyAtomsBeg.assign(B, 0);
    m.bodyAtomsEnd.assign(B, 0);
    m.bodyAtoms.clear();
    for (int b = 0; b < B; ++b) {
        m.bodyAtomsBeg[b] = static_cast(m.bodyAtoms.size());
        for (int a : bodyAtoms[b]) {
            m.bodyAtoms.push_back(a);
        }
        m.bodyAtomsEnd[b] = static_cast(m.bodyAtoms.size());
    }

    // mass properties from the atom point masses (the calcMassProperties port).
    m.bodyMass.assign(B, Real(0));
    m.bodyCom_B.assign(B, Vec3(0));
    m.bodyUnitInertia_B.assign(B, UnitInertia(Real(0), Real(0), Real(0)));
    for (int b = 1; b < B; ++b) {
        Real mass = 0;
        Vec3 com(0);
        Inertia inertia(0);
        for (int ci = m.bodyAtomsBeg[b]; ci < m.bodyAtomsEnd[b]; ++ci) {
            const int a = m.bodyAtoms[ci];
            const Vec3& st = m.atomStation_B[a];
            const Real ma = m.atomMass[a];
            mass += ma;
            com = com + (st * ma);
            inertia += Inertia(st, ma);
        }
        const MassProperties mp(mass, mass > 0 ? Vec3(com * (Real(1) / mass)) : Vec3(0), inertia);
        m.bodyMass[b] = mass;
        m.bodyCom_B[b] = mp.getMassCenter();
        m.bodyUnitInertia_B[b] = mp.getUnitInertia();
    }
}

// A forest of several robots on the shared Ground, one of every joint type, so
// the atom transfer is exercised across the full mobilizer spread at once.
RobotModel makeAtomicForest(Rng& rng, int perBody = 3) {
    auto F = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        return s;
    };
    std::vector specs;
    specs.push_back(F(0, JointType::Free));        // body 1
    specs.push_back(F(1, JointType::Torsion));     // body 2
    specs.push_back(F(2, JointType::BendStretch)); // body 3 (q-dependent H_FM)
    specs.push_back(F(0, JointType::Ball));        // body 4
    specs.push_back(F(0, JointType::Cartesian));   // body 5
    specs.push_back(F(5, JointType::Slider));      // body 6
    specs.push_back(F(0, JointType::FreeLine));    // body 7
    specs.push_back(F(0, JointType::Rigid));       // body 8 (frozen)
    RobotModel m = buildForest(specs);
    attachAtoms(m, rng, perBody);
    return m;
}

// atom velocity in Ground = rigid transport of the body spatial velocity to the
// atom: v_a = v_o + w x (r_a - o). (calcAtomVelocityInGroundFrame.)
Vec3 atomVelG(const RobotState& s, const RobotModel& m, int a) {
    const int b = m.atomBody[a];
    const Vec3 r = s.atomPosG()[a] - s.X_GB()[b].p();
    return s.V_GB()[b][1] + (s.V_GB()[b][0] % r);
}

} // namespace

// ---------------------------------------------------------------------------
//  T1. station_B is BODY-FIXED: for ANY configuration, an atom's Ground position
//      re-expressed in its body frame returns exactly its station. This is the
//      property getAtomStationOnBody / getLocationInMobilizedBodyFrame silently
//      depended on (the station is a topological constant; only X_GB moves).
//      Tolerance kTight (machine algebra): the map is one rigid inverse.
// ---------------------------------------------------------------------------
TEST(AtomTransfer, StationIsBodyFixedUnderAnyConfiguration) {
    Rng rng(0xA70505);
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 30; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        for (int a = 0; a < m.numAtoms; ++a) {
            const int b = m.atomBody[a];
            const Vec3 stationBack = (~s.X_GB()[b]) * s.atomPosG()[a];
            EXPECT_TRUE(rtest::NearVec3(stationBack, m.atomStation_B[a], rtest::kTight))
                << "atom " << a << " body " << b << " rep " << rep;
        }
    }
}

// ---------------------------------------------------------------------------
//  T2. Ground-position currency is internally consistent: the per-atom positions
//      written by realizePosition equal both (a) the explicit station map
//      X_GB.p + R_GB*station (= fillAtomPositionsFromBodies, the accept-path) and
//      (b) origin + atomStationG, where atomStationG = R_GB*station is the
//      getIncludedAtomStation referent fed to the force bridge. All three must
//      agree to the last bit -- they are the SAME quantity computed two ways, so
//      any drift is a real bug, not FD noise. Tolerance kTight.
// ---------------------------------------------------------------------------
TEST(AtomTransfer, RealizePositionFillAndStationGAllAgree) {
    Rng rng(0xB22222);
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);

    RobotEngine::realizePosition(m, s);
    std::vector posFromRealize(s.atomPosG(), s.atomPosG() + m.numAtoms);
    std::vector stationG(s.atomStationG(), s.atomStationG() + m.numAtoms);

    // scribble over atomPosG, then recompute via the accept-path entry point.
    for (int a = 0; a < m.numAtoms; ++a) {
        s.atomPosG()[a] = Vec3(0);
    }
    RobotEngine::fillAtomPositionsFromBodies(m, s);

    for (int a = 0; a < m.numAtoms; ++a) {
        const int b = m.atomBody[a];
        const Vec3 viaStationMap = s.X_GB()[b].p() + s.X_GB()[b].R() * m.atomStation_B[a];
        EXPECT_TRUE(rtest::NearVec3(s.atomPosG()[a], posFromRealize[a], rtest::kTight))
            << "fill vs realize " << a;
        EXPECT_TRUE(rtest::NearVec3(s.atomPosG()[a], viaStationMap, rtest::kTight)) << "fill vs map " << a;
        // atomStationG == R_GB * station, and origin + stationG == position.
        EXPECT_TRUE(rtest::NearVec3(stationG[a], s.X_GB()[b].R() * m.atomStation_B[a], rtest::kTight))
            << "stationG " << a;
        EXPECT_TRUE(rtest::NearVec3(s.X_GB()[b].p() + stationG[a], posFromRealize[a], rtest::kTight))
            << "origin+stationG " << a;
    }
}

// ---------------------------------------------------------------------------
//  T3. Atom velocity in Ground (calcAtomVelocityInGroundFrame) is the rigid
//      transport of the body spatial velocity, and must equal d/dt of the atom's
//      Ground position along the true trajectory q(t)=q0+t*qdot. Central FD,
//      tolerance 1e-4 (~ the kinematic FD tolerance used elsewhere in the suite).
// ---------------------------------------------------------------------------
TEST(AtomTransfer, AtomVelocityIsDerivativeOfAtomPosition) {
    Rng rng(0xC33033);
    const Real h = 1e-6;
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);

        std::vector q0(s.q(), s.q() + m.nq), qdot(m.nq);
        RobotEngine::calcQDot(m, s, qdot.data());
        std::vector vAnalytic(m.numAtoms);
        for (int a = 0; a < m.numAtoms; ++a) {
            vAnalytic[a] = atomVelG(s, m, a);
        }

        auto posAt = [&](Real t, std::vector& P) {
            for (int i = 0; i < m.nq; ++i) {
                s.q()[i] = q0[i] + t * qdot[i];
            }
            RobotEngine::normalizeQuaternions(m, s);
            RobotEngine::realizePosition(m, s);
            P.assign(s.atomPosG(), s.atomPosG() + m.numAtoms);
        };
        std::vector Pp, Pm;
        posAt(+h, Pp);
        posAt(-h, Pm);
        for (int a = 0; a < m.numAtoms; ++a) {
            const Vec3 vFD = (Pp[a] - Pm[a]) * (Real(1) / (Real(2) * h));
            EXPECT_TRUE(rtest::NearVec3(vAnalytic[a], vFD, 1e-4)) << "atom " << a << " rep " << rep;
        }
        std::copy(q0.begin(), q0.end(), s.q());
    }
}

// ---------------------------------------------------------------------------
//  T4. Atom acceleration in Ground (calcAtomAccelerationInGroundFrame) is the
//      rigid point acceleration a_a = a_o + alpha x r + w x (w x r), and must
//      equal d/dt of the atom velocity along the true (q,u) trajectory. Drives a
//      random generalized force through full forward dynamics first. Central FD
//      of the atom velocity, tolerance 1e-3 (second-kinematic-derivative FD, as
//      in TestMobilizer's A_GB leg).
// ---------------------------------------------------------------------------
TEST(AtomTransfer, AtomAccelerationIsDerivativeOfAtomVelocity) {
    Rng rng(0xD44044);
    const Real h = 1e-6;
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 12; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        std::fill(s.bodyForceG(), s.bodyForceG() + m.numBodies, SpatialVec(Vec3(0), Vec3(0)));
        for (int i = 0; i < m.nu; ++i) {
            s.mobilityForce()[i] = rng.gaussian(0, Real(0.5));
        }
        RobotEngine::calcUDot(m, s);

        std::vector q0(s.q(), s.q() + m.nq), u0(s.u(), s.u() + m.nu);
        std::vector qdot0(m.nq), udot0(s.udot(), s.udot() + m.nu);
        RobotEngine::calcQDot(m, s, qdot0.data());

        // analytic atom acceleration from body spatial accel + velocity.
        std::vector aAnalytic(m.numAtoms);
        for (int a = 0; a < m.numAtoms; ++a) {
            const int b = m.atomBody[a];
            const Vec3 r = s.atomPosG()[a] - s.X_GB()[b].p();
            const Vec3 w = s.V_GB()[b][0];
            const Vec3 alpha = s.A_GB()[b][0];
            const Vec3 a_o = s.A_GB()[b][1];
            aAnalytic[a] = a_o + (alpha % r) + (w % (w % r));
        }

        auto atomVelAt = [&](Real t, std::vector& V) {
            for (int i = 0; i < m.nq; ++i) {
                s.q()[i] = q0[i] + t * qdot0[i];
            }
            for (int i = 0; i < m.nu; ++i) {
                s.u()[i] = u0[i] + t * udot0[i];
            }
            RobotEngine::normalizeQuaternions(m, s);
            RobotEngine::realizePosition(m, s);
            RobotEngine::realizeVelocity(m, s);
            V.resize(m.numAtoms);
            for (int a = 0; a < m.numAtoms; ++a) {
                V[a] = atomVelG(s, m, a);
            }
        };
        std::vector Vp, Vm;
        atomVelAt(+h, Vp);
        atomVelAt(-h, Vm);
        for (int a = 0; a < m.numAtoms; ++a) {
            const Vec3 aFD = (Vp[a] - Vm[a]) * (Real(1) / (Real(2) * h));
            EXPECT_TRUE(rtest::NearVec3(aAnalytic[a], aFD, 1e-3)) << "atom " << a << " rep " << rep;
        }
        std::copy(q0.begin(), q0.end(), s.q());
        std::copy(u0.begin(), u0.end(), s.u());
    }
}

// ---------------------------------------------------------------------------
//  T5. The calcMassProperties REPLACEMENT. The body spatial inertia the engine
//      builds (Mk_G, about the body origin, in Ground) must equal the spatial
//      inertia assembled INDEPENDENTLY from the atom point masses at their Ground
//      positions. Concretely:
//        * bodyMass[b]            == sum_a m_a                       (kTight)
//        * comG[b]                == (sum_a m_a posG[a]) / M          (kAlg)
//        * Mk_G unit inertia * M  == sum_a Inertia(posG[a]-origin,m_a)(kAlg)
//      This is the whole point of "we handle mass properties ourselves": the
//      reduction from atoms to a rigid body must be exact, in Ground, every
//      transfer. (Validates recomputeGeometry's sums AND realizePosition's
//      reexpression bodyUnitInertia_B -> G_Bo_G in one shot.)
// ---------------------------------------------------------------------------
TEST(AtomTransfer, BodySpatialInertiaEqualsAtomPointMassSum) {
    Rng rng(0xE55055);
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    for (int b = 1; b < m.numBodies; ++b) {
        if (m.bodyAtomsBeg[b] == m.bodyAtomsEnd[b]) {
            continue;
        }
        Real mass = 0;
        Vec3 comG(0);
        Inertia inertiaAboutOriginG(0);
        const Vec3 origin = s.X_GB()[b].p();
        for (int ci = m.bodyAtomsBeg[b]; ci < m.bodyAtomsEnd[b]; ++ci) {
            const int a = m.bodyAtoms[ci];
            const Real ma = m.atomMass[a];
            const Vec3 r = s.atomPosG()[a] - origin; // atom offset from origin, in Ground
            mass += ma;
            comG = comG + (s.atomPosG()[a] * ma);
            inertiaAboutOriginG += Inertia(r, ma);
        }
        comG = comG * (Real(1) / mass);

        // (a) total mass
        EXPECT_NEAR(m.bodyMass[b], mass, rtest::kTight) << "mass body " << b;
        // (b) COM in Ground: engine comG[b] is origin + R_GB*com_B.
        EXPECT_TRUE(rtest::NearVec3(s.comG()[b], comG, rtest::kAlg)) << "comG body " << b;
        // (c) inertia about the body origin, expressed in Ground.
        const Mat33 fromEngine = s.Mk_G()[b].getUnitInertia().full() * m.bodyMass[b];
        const Mat33 fromAtoms = inertiaAboutOriginG.asSymMat33().full();
        EXPECT_TRUE(rtest::NearMat33(fromEngine, fromAtoms, rtest::kAlg)) << "inertia body " << b;
    }
}

// ---------------------------------------------------------------------------
//  T6. TRANSFER ROUND TRIP (HMCSampler::sampleIteration accept-path <-> the
//      getAtomLocationInMobilizedBodyFrameThroughDumm inverse). Given ANY set of
//      per-atom Cartesian "targets", the rigid decomposition recovers them
//      EXACTLY: station' = (~X_GB[b]) * target, then refill posG = X_GB * station'
//      reproduces target to machine precision -- for every body configuration.
//
//      This is the analogue of the original TestAtomTargetLocations residual
//      check, but where molmodel's iterative matchDefault*/getTransformAndResidual
//      only reached residual < 0.02 nm, the SoA decomposition is exact (the
//      station absorbs the within-body offset), so the bar here is kTight (~1e-13)
//      rather than 2e-2. Tightening the constraint is the correctness gain.
// ---------------------------------------------------------------------------
TEST(AtomTransfer, CartesianTargetsRoundTripExactly) {
    Rng rng(0xF66066);
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);

        // arbitrary targets (need not be a rigid placement; the station absorbs
        // whatever offset, which is exactly why a transfer is lossless).
        std::vector targets(m.numAtoms);
        for (int a = 0; a < m.numAtoms; ++a) {
            targets[a] = rng.vec3(Real(-5), Real(5));
        }

        // inverse: derive a station per atom from the target and current frames.
        std::vector savedStation = m.atomStation_B;
        for (int a = 0; a < m.numAtoms; ++a) {
            const int b = m.atomBody[a];
            m.atomStation_B[a] = (~s.X_GB()[b]) * targets[a];
        }
        // forward again: recover the targets.
        RobotEngine::fillAtomPositionsFromBodies(m, s);
        for (int a = 0; a < m.numAtoms; ++a) {
            EXPECT_TRUE(rtest::NearVec3(s.atomPosG()[a], targets[a], rtest::kTight))
                << "atom " << a << " rep " << rep;
        }
        m.atomStation_B = savedStation;
    }
}

// ---------------------------------------------------------------------------
//  T7. Atoms follow forest indexing: an atom is moved ONLY by its own robot's
//      coordinates. Perturbing robot R1's q must not move any atom whose body
//      belongs to robot R3 -- the atom<->body map and the children CSR carry the
//      molecule="robot" independence all the way down to the per-atom positions.
//      Tolerance kTight.
// ---------------------------------------------------------------------------
TEST(AtomTransfer, AtomsMoveOnlyWithTheirOwnRobot) {
    Rng rng(0x121212);
    RobotModel m = makeAtomicForest(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    // robot rooted at the Cartesian body 5 occupies bodies {5,6}; snapshot its atoms.
    const std::array otherBodies = {5, 6};
    std::vector<std::pair> before;
    for (int a = 0; a < m.numAtoms; ++a) {
        for (int b : otherBodies) {
            if (m.atomBody[a] == b) {
                before.emplace_back(a, s.atomPosG()[a]);
            }
        }
    }
    ASSERT_TRUE(!before.empty());

    // perturb robot 1 (bodies {1,2,3}).
    for (int b : {1, 2, 3}) {
        for (int j = 0; j < m.bodyNQ[b]; ++j) {
            s.q()[m.bodyQIndex[b] + j] += Real(0.4);
        }
    }
    RobotEngine::normalizeQuaternions(m, s);
    RobotEngine::realizePosition(m, s);

    for (auto& [a, p] : before) {
        EXPECT_TRUE(rtest::NearVec3(s.atomPosG()[a], p, rtest::kTight)) << "atom " << a << " moved";
    }
}

// ============================================================================
//  TestBiasForces.cpp -- Phase 2: pin the VELOCITY-DEPENDENT bias terms of the
//  articulated-body dynamics in isolation -- gyroscopic, centrifugal /
//  centripetal, and Coriolis. These are computed in realizeVelocity
//  (s.gyro(), s.mobCoriolisA(), s.coriolisA()) and consumed by calcUDot.
//
//  WHY THIS FILE EXISTS. Until now these terms were touched only INDIRECTLY: the
//  one quantitative dynamics check (Dynamics.UDotEqualsMInvForceAtZeroVelocity,
//  TestMassMatrix.cpp) deliberately ZEROES velocity, so every bias term is 0 in
//  it and a regression there would be invisible. The realizeVelocity comments
//  document two historical energy-pumping bugs that live exactly here -- the
//  dropped Hdot_G u term ("EARLIER BUG") and the missing centripetal HDot_MB_F
//  term -- both of which conserve nothing yet pass a position-only OpenMM energy
//  check. This file exercises each term at NONZERO u, against an independent
//  re-derivation, plus a residual force balance and a system-level angular-
//  momentum invariant. Each test carries a must-FAIL-if-dropped guard so a
//  silent regression to the documented bugs turns the suite red.
//
//  No World / forcefield: generalized forces are set directly (calcUDot), and
//  the integrator tests use the OpenMM-free ZeroBridge below.
//
//  NOT PORTED (no operator in Robosample): reaction forces
//  (calcMobilizerReactionForces); gravity (none in Robosample).
// ============================================================================
#include 
#include 
#include 
#include 

#include "Constraints.hpp"
#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotIntegrator.hpp" // templated verletStep (FreeBodyConservesAngularMomentum)
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::NearVec3;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// ---- local tolerances (the spec's kFDbias / kEdrift; kTight/kLoose are shared) -
inline constexpr Real kFDbias = 1e-6; // central-FD bias residual (observed ~1e-9)
inline constexpr Real kEdrift = 1e-6; // free-body L drift over 2000 steps at small h

inline Real spatialNorm(const SpatialVec& v) {
    return std::sqrt(v[0].normSqr() + v[1].normSqr());
}

// makeDynForest-style mixed-joint builder (modeled on TestMassMatrix.cpp). Every
// body gets random-but-fixed joint frames; X_BM has a NONZERO translation, so
// r_MB = X_MB.p() != 0 and the centripetal HDot_MB_F term is active on every
// body (in particular the Torsion bodies -- the spec's "Torsion-with-nonzero-
// X_BM.p()" requirement). All ten joint types appear so CoriolisAccelMatches-
// ClassicForm exercises both the constant-H closed form (seven joints) and the
// q-dependent FD branch (BendStretch / SphericalCoords / FreeLine).
RobotModel makeBiasForest(Rng& rng) {
    auto F = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3(-0.6, 0.6)); // nonzero r_MB
        s.mass = rng.uniform(0.5, 2.5);
        s.com_B = rng.vec3(-0.25, 0.25);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        return s;
    };
    std::vector specs;
    specs.push_back(F(0, JointType::Free));            // 1  (robot 1 root)
    specs.push_back(F(1, JointType::Torsion));         // 2  Torsion, offset M frame, parent moving
    specs.push_back(F(2, JointType::Torsion));         // 3  Torsion (chain)
    specs.push_back(F(0, JointType::Ball));            // 4  (robot 2 root)
    specs.push_back(F(4, JointType::Cylinder));        // 5
    specs.push_back(F(0, JointType::Cartesian));       // 6  (robot 3 root)
    specs.push_back(F(6, JointType::BendStretch));     // 7  q-dependent H
    specs.push_back(F(6, JointType::SphericalCoords)); // 8  q-dependent H
    specs.push_back(F(0, JointType::FreeLine));        // 9  q-dependent H (robot 4 root)
    specs.push_back(F(1, JointType::Slider));          // 10
    return buildForest(specs);
}

void realizeForBias(const RobotModel& m, RobotState& s) {
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeVelocity(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
}

// Independent re-derivation of the mobilizer bias a_mob[b] by finite difference,
// valid for EVERY joint type (constant-H and q-dependent alike):
//   a_tot[b] = d/dt V_GB[b] holding u fixed (udot==0), and
//   a_mob[b] = a_tot[b] - ~Phi[b] * a_tot[parent].
// We FD V_GB along q(t)=q0+t*qdot (quaternions renormalized, u restored each
// sample) and subtract the parent's shifted FD using the CENTER-point Phi.
// Returns a_mob_fd indexed by body. Restores s to its center configuration.
std::vector mobBiasByFD(const RobotModel& m, RobotState& s, Real h = 1e-6) {
    const int nb = m.numBodies;
    std::vector q0(s.q(), s.q() + m.nq);
    std::vector u(s.u(), s.u() + m.nu);
    std::vector qdot(m.nq);
    RobotEngine::calcQDot(m, s, qdot.data());
    std::vector Phi(s.Phi(), s.Phi() + nb); // center-point Phi

    auto velAt = [&](Real t) {
        for (int i = 0; i < m.nq; ++i) {
            s.q()[i] = q0[i] + t * qdot[i];
        }
        RobotEngine::normalizeQuaternions(m, s);
        RobotEngine::realizePosition(m, s);
        std::copy(u.begin(), u.end(), s.u());
        RobotEngine::realizeVelocity(m, s);
        return std::vector(s.V_GB(), s.V_GB() + nb);
    };
    const std::vector Vp = velAt(+h);
    const std::vector Vm = velAt(-h);

    // restore center
    std::copy(q0.begin(), q0.end(), s.q());
    std::copy(u.begin(), u.end(), s.u());
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeVelocity(m, s);

    const Real inv2h = Real(1) / (Real(2) * h);
    std::vector dV(nb), aMob(nb, SpatialVec(Vec3(0), Vec3(0)));
    for (int b = 0; b < nb; ++b) {
        dV[b] = SpatialVec((Vp[b][0] - Vm[b][0]) * inv2h, (Vp[b][1] - Vm[b][1]) * inv2h);
    }
    for (int b = 1; b < nb; ++b) {
        const SpatialVec shifted = (~Phi[b]) * dV[m.bodyParent[b]];
        aMob[b] = SpatialVec(dV[b][0] - shifted[0], dV[b][1] - shifted[1]);
    }
    return aMob;
}

// OpenMM-free zero-force bridge matching the verletStep contract: clears every
// per-body spatial force and every mobility force, exactly like ForceBridge does
// before accumulating (here it accumulates nothing). With zero applied force the
// ONLY thing driving udot is the velocity-dependent bias -- which is the point.
struct ZeroBridge {
    const RobotModel& m;
    explicit ZeroBridge(const RobotModel& model)
        : m(model) {
    }
    void evaluate(RobotState& s) {
        for (int b = 0; b < m.numBodies; ++b) {
            s.bodyForceG()[b] = SpatialVec(Vec3(0), Vec3(0));
        }
        for (int i = 0; i < m.nu; ++i) {
            s.mobilityForce()[i] = Real(0);
        }
    }
};

// Spatial angular momentum of a single rigid body about its OWN COM, in Ground.
// Spatial momentum about the body origin Bo is h = Mk_G * V_GB = [L_Bo ; p];
// shifting the reference point Bo -> COM (offset c = Bo->COM in Ground):
//   L_com = L_Bo - c x p .
// For a torque-free free body this is the conserved quantity (it equals
// I_com * w in the inertial frame and is constant; w itself precesses).
Vec3 angularMomentumAboutCom(const RobotModel& m, RobotState& s, int b) {
    const SpatialVec hmom = s.Mk_G()[b] * s.V_GB()[b];
    const Vec3 p = hmom[1];                     // linear momentum m * v_com
    const Vec3 c = s.Mk_G()[b].getMassCenter(); // Bo -> COM in Ground
    return hmom[0] - (c % p);
}

} // namespace

// ---------------------------------------------------------------------------
//  B1: GyroscopicMatchesClosedForm. For every body of a random forest at random
//  u, s.gyro()[b] must equal the independent closed form
//      g = mass * [ w x (G w) ; w x (w x c) ]
//  built from Mk_G()[b].getUnitInertia()/getMassCenter()/getMass() and V_GB()[b].
//  FAIL guard: the body-frame variant mass * w x (I_body w) -- forgetting the
//  reexpress(~R_GB) into Ground -- must differ by > 1e-6 for at least one body
//  (otherwise the test could not catch that exact regression).
// ---------------------------------------------------------------------------
TEST(BiasForces, GyroscopicMatchesClosedForm) {
    Rng rng(0xB1A5);
    RobotModel m = makeBiasForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng);
        realizeForBias(m, s);

        const SpatialInertia* Mk = s.Mk_G();
        const SpatialVec* V = s.V_GB();
        const SpatialVec* gyro = s.gyro();

        Real maxWrong = 0; // body-frame (un-reexpressed) deviation, for the guard
        for (int b = 1; b < m.numBodies; ++b) {
            const Vec3 w = V[b][0];
            const Vec3 Gw = Mk[b].getUnitInertia() * w; // G w (Ground), per unit mass
            const Vec3 c = Mk[b].getMassCenter();       // COM offset in Ground
            const SpatialVec g = Mk[b].getMass() * SpatialVec(w % Gw, w % (w % c));

            EXPECT_TRUE(NearVec3(gyro[b][0], g[0], rtest::kTight)) << "ang body " << b << " rep " << rep;
            EXPECT_TRUE(NearVec3(gyro[b][1], g[1], rtest::kTight)) << "lin body " << b << " rep " << rep;

            // WRONG variant: unit inertia taken in the BODY frame (no reexpress).
            const Vec3 GwBody = m.bodyUnitInertia_B[b] * w;
            const Vec3 gWrongAng = Mk[b].getMass() * (w % GwBody);
            maxWrong = std::max(maxWrong, (gWrongAng - gyro[b][0]).norm());
        }
        EXPECT_GT(maxWrong, 1e-6) << "body-frame gyroscopic indistinguishable from Ground form, rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  B2: BiasVanishesAtZeroVelocity. With u = 0, every bias term is a product of
//  zero velocities, so gyro[b], mobCoriolisA[b], coriolisA[b] must all be
//  exactly Vec3(0) (to kTight) for every body. This is the boundary that the
//  pre-existing UDotEqualsMInvForceAtZeroVelocity relies on implicitly; pinning
//  it makes the assumption explicit.
// ---------------------------------------------------------------------------
TEST(BiasForces, BiasVanishesAtZeroVelocity) {
    Rng rng(0xB2A5);
    RobotModel m = makeBiasForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 10; ++rep) {
        randomizeState(m, s, rng);
        std::fill(s.u(), s.u() + m.nu, Real(0)); // zero velocity
        realizeForBias(m, s);

        for (int b = 1; b < m.numBodies; ++b) {
            EXPECT_TRUE(NearVec3(s.gyro()[b][0], Vec3(0), rtest::kTight)) << "gyro ang b" << b;
            EXPECT_TRUE(NearVec3(s.gyro()[b][1], Vec3(0), rtest::kTight)) << "gyro lin b" << b;
            EXPECT_TRUE(NearVec3(s.mobCoriolisA()[b][0], Vec3(0), rtest::kTight)) << "aMob ang b" << b;
            EXPECT_TRUE(NearVec3(s.mobCoriolisA()[b][1], Vec3(0), rtest::kTight)) << "aMob lin b" << b;
            EXPECT_TRUE(NearVec3(s.coriolisA()[b][0], Vec3(0), rtest::kTight)) << "aTot ang b" << b;
            EXPECT_TRUE(NearVec3(s.coriolisA()[b][1], Vec3(0), rtest::kTight)) << "aTot lin b" << b;
        }
    }
}

// ---------------------------------------------------------------------------
//  B3: BiasIsNonzeroWhenItMustBe -- the must-FAIL-if-dropped control. For bodies
//  whose mobilizer bias is genuinely nonzero (a Torsion child with an offset M
//  frame and a moving parent; an offset Ball/Free root) at random nonzero u,
//  ||mobCoriolisA[b]|| must exceed 1e-6. Dropping the centripetal_G / Hdot_G u
//  term (the documented "EARLIER BUG") collapses these to zero and turns this
//  red.
// ---------------------------------------------------------------------------
TEST(BiasForces, BiasIsNonzeroWhenItMustBe) {
    Rng rng(0xB3A5);
    // A focused forest: Free root (offset), Torsion child (offset, moving parent),
    // Ball root (offset). All three have a structurally nonzero a_mob.
    auto F = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3(-0.6, 0.6));
        s.mass = rng.uniform(0.8, 2.0);
        s.com_B = rng.vec3(-0.2, 0.2);
        s.inertia_B = UnitInertia(0.4, 0.5, 0.6);
        return s;
    };
    RobotModel m = buildForest({F(0, JointType::Free), F(1, JointType::Torsion), F(0, JointType::Ball)});
    RobotState s;
    s.allocateFull(m);
    const int freeRoot = 1, torsionChild = 2, ballRoot = 3;

    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng); // u ~ gaussian, nonzero
        realizeForBias(m, s);
        EXPECT_GT(spatialNorm(s.mobCoriolisA()[freeRoot]), 1e-6) << "Free root, rep " << rep;
        EXPECT_GT(spatialNorm(s.mobCoriolisA()[torsionChild]), 1e-6) << "Torsion child, rep " << rep;
        EXPECT_GT(spatialNorm(s.mobCoriolisA()[ballRoot]), 1e-6) << "Ball root, rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  B4: CoriolisAccelMatchesClassicForm. Re-derive the mobilizer bias from the
//  classic centripetal + 2*Coriolis form using only parent body velocities and
//  static frames -- independent of the engine's extraAng/extraLin path:
//    a_mob.ang = w_GP x w_PB_G
//    a_mob.lin = w_GP x (v_GB - v_GP) + w_GP x v_PB_G + R_GF*(w_FM x (w_FM x r_MB_F))
//  This closed form is COMPLETE only when H_FM is constant in F (seven joints),
//  so it is asserted for those. For the three q-dependent joints (BendStretch /
//  SphericalCoords / FreeLine) the closed form misses the intrinsic dH_FM/dt u
//  term, so a_mob is instead checked against a finite difference of the body
//  velocity (== d/dt(H_PB_G u) after removing the parent's shifted acceleration).
// ---------------------------------------------------------------------------
TEST(BiasForces, CoriolisAccelMatchesClassicForm) {
    Rng rng(0xB4A5);
    RobotModel m = makeBiasForest(rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        realizeForBias(m, s);

        const SpatialVec* V = s.V_GB();
        const SpatialVec* V_FM = s.V_FM();
        const SpatialVec* V_PB_G = s.V_PB_G();
        const Transform* X_GB = s.X_GB();
        const Transform* X_FM = s.X_FM();
        const SpatialVec* aMob = s.mobCoriolisA();

        // FD reference for the q-dependent joints (also valid for the rest).
        const std::vector aMobFD = mobBiasByFD(m, s);

        for (int b = 1; b < m.numBodies; ++b) {
            const int p = m.bodyParent[b];
            if (RobotModel::jointHasConstantHFM(m.bodyJoint[b])) {
                const Vec3& w_GP = V[p][0];
                const Vec3& v_GP = V[p][1];
                const Vec3& v_GB = V[b][1];
                const Vec3& w_PB_G = V_PB_G[b][0];
                const Vec3& v_PB_G = V_PB_G[b][1];
                const Vec3& w_FM = V_FM[b][0];
                const Vec3 r_MB_F = X_FM[b].R() * (~m.X_BM[b]).p(); // Mo->Bo in F
                const Rotation R_GF = X_GB[p].R() * m.X_PF[b].R();
                const Vec3 centripetal_G = R_GF * (w_FM % (w_FM % r_MB_F));

                const Vec3 ang = w_GP % w_PB_G;
                const Vec3 lin = (w_GP % (v_GB - v_GP)) + (w_GP % v_PB_G) + centripetal_G;
                EXPECT_TRUE(NearVec3(aMob[b][0], ang, rtest::kTight))
                    << "classic ang body " << b << " rep " << rep;
                EXPECT_TRUE(NearVec3(aMob[b][1], lin, rtest::kTight))
                    << "classic lin body " << b << " rep " << rep;
            } else {
                // q-dependent: only the FD oracle captures the dH_FM/dt u term.
                EXPECT_TRUE(NearVec3(aMob[b][0], aMobFD[b][0], kFDbias))
                    << "FD ang body " << b << " joint " << static_cast(m.bodyJoint[b]) << " rep " << rep;
                EXPECT_TRUE(NearVec3(aMob[b][1], aMobFD[b][1], kFDbias))
                    << "FD lin body " << b << " joint " << static_cast(m.bodyJoint[b]) << " rep " << rep;
            }
        }
    }
}

// ---------------------------------------------------------------------------
//  B5: ResidualForceBalanceAtNonzeroVelocity. The missing companion to
//  UDotEqualsMInvForceAtZeroVelocity: drive calcUDot at NONZERO u with random
//  mobilityForce (tau) and zero bodyForceG, then verify the equation of motion
//      M udot = tau - c        (c = velocity-dependent gyroscopic+Coriolis bias)
//  in the cleaner equivalent form actually asserted here:
//      udot == multiplyByMInv(tau - c).
//  We obtain M^-1 (tau - c) without ever forming c explicitly: run calcUDot with
//  tau=0 to get udot_bias = M^-1 (-c), and use linearity of M^-1:
//      udot(tau) == multiplyByMInv(tau) + udot_bias.
//  FAIL guard: forcing bias to 0 (i.e. comparing udot(tau) to multiplyByMInv(tau)
//  alone) must NOT pass at nonzero u -- proving the bias actually enters udot.
// ---------------------------------------------------------------------------
TEST(Dynamics, ResidualForceBalanceAtNonzeroVelocity) {
    Rng rng(0xB5A5);
    RobotModel m = makeBiasForest(rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng); // nonzero u
        realizeForBias(m, s);
        std::fill(s.bodyForceG(), s.bodyForceG() + m.numBodies, SpatialVec(Vec3(0), Vec3(0)));

        std::vector tau(m.nu);
        for (int i = 0; i < m.nu; ++i) {
            tau[i] = rng.gaussian();
        }

        // udot at applied force tau (includes the bias).
        std::copy(tau.begin(), tau.end(), s.mobilityForce());
        RobotEngine::calcUDot(m, s);
        std::vector udotTau(s.udot(), s.udot() + m.nu);

        // udot at zero applied force = M^-1 (-c), the pure bias acceleration.
        std::fill(s.mobilityForce(), s.mobilityForce() + m.nu, Real(0));
        RobotEngine::calcUDot(m, s);
        std::vector udotBias(s.udot(), s.udot() + m.nu);

        // M^-1 tau via the explicit operator (no velocity terms).
        std::vector minvTau(m.nu);
        RobotEngine::multiplyByMInv(m, s, tau.data(), minvTau.data());

        // Equation of motion: udot(tau) == M^-1(tau) + M^-1(-c).
        Real maxBiasContribution = 0;
        for (int i = 0; i < m.nu; ++i) {
            EXPECT_NEAR(udotTau[i], minvTau[i] + udotBias[i], rtest::kLoose) << "i=" << i << " rep " << rep;
            maxBiasContribution = std::max(maxBiasContribution, std::abs(udotTau[i] - minvTau[i]));
        }
        // FAIL guard: bias-forced-to-0 (udotTau ?= minvTau) must NOT hold -- the
        // velocity-dependent term genuinely moves udot at nonzero u.
        EXPECT_GT(maxBiasContribution, 1e-6) << "bias did not enter udot, rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  B6: FreeBodyConservesAngularMomentum (system-level invariant). A single Free
//  body, NO applied force (so udot is driven entirely by the gyroscopic bias),
//  random initial spin, integrated 2000 steps with the production verletStep.
//  The spatial angular momentum about the COM in Ground is a constant of motion
//  for a torque-free body, so its relative drift must stay < kEdrift.
//  Sensitivity (FAIL) guard: a 10x-too-large h must drift past kEdrift.
// ---------------------------------------------------------------------------
TEST(BiasForces, FreeBodyConservesAngularMomentum) {
    auto relDrift = [](Real h, int nSteps) -> Real {
        // Deterministic single Free body with an ASYMMETRIC inertia (so w
        // precesses -- the gyroscopic term is genuinely exercised, not trivial).
        BodySpec spec;
        spec.parent = 0;
        spec.joint = JointType::Free;
        spec.X_PF = Transform();
        spec.X_BM = Transform();
        spec.mass = Real(2.0);
        spec.com_B = Vec3(0.07, -0.03, 0.05);
        spec.inertia_B = UnitInertia(Real(0.30), Real(0.55), Real(0.80));
        RobotModel m = buildForest({spec});

        RobotState s;
        s.allocateFull(m);
        Real* q = s.q();
        q[0] = 1; // identity quaternion
        q[1] = q[2] = q[3] = 0;
        q[4] = q[5] = q[6] = 0; // origin
        Real* u = s.u();
        u[0] = Real(1.3); // pure spin (w_FM), zero translational speed
        u[1] = Real(-0.8);
        u[2] = Real(0.5);
        u[3] = u[4] = u[5] = 0;

        ZeroBridge bridge(m);
        const ConstraintSet cset; // empty -> unconstrained

        // seed the derivative chain (mirrors TestIntegrator's seedDerivatives).
        RobotEngine::realizePosition(m, s);
        RobotEngine::fillAtomPositionsFromBodies(m, s);
        bridge.evaluate(s);
        RobotEngine::realizeVelocity(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        RobotEngine::calcUDot(m, s);
        RobotEngine::calcQDot(m, s, s.qdot());
        RobotEngine::calcQDotDot(m, s);

        const Vec3 L0 = angularMomentumAboutCom(m, s, 1);
        for (int n = 0; n < nSteps; ++n) {
            const bool ok = RobotEngine::verletStep(m, s, bridge, cset, h);
            if (!ok) {
                return Real(1e9); // a rejected step is itself a failure of conservation
            }
        }
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);
        const Vec3 L1 = angularMomentumAboutCom(m, s, 1);
        return (L1 - L0).norm() / (L0.norm() + Real(1e-30));
    };

    const Real h = 5e-4;
    EXPECT_LT(relDrift(h, 2000), kEdrift) << "angular momentum drifted at the nominal step";
    // sensitivity: 10x the step must visibly break conservation.
    EXPECT_GT(relDrift(10 * h, 2000), kEdrift) << "10x step did not break conservation (insensitive)";
}

// ============================================================================
//  TestBuilders.cpp -- Phase 0.2: the atom-attachment builder extension.
//
//  buildForest hands back atom-free robots (numAtoms == 0). Constraints
//  (SHAKE/RATTLE), the force bridge, and the internal->Cartesian transfer all
//  read model.atomBody / atomStation_B / atomPosG, so attachAtoms (RobotBuilders
//  .hpp) is the precondition every one of those downstream test files relies on.
//
//  This file pins attachAtoms two ways:
//   * PURE (no engine): the arrays and the body->atoms CSR it builds are
//     internally consistent (every atom appears exactly once, under its own
//     body; the root atom is set; virtual sites are stored verbatim).
//   * ENGINE: after RobotState::allocateFull + realizePosition, the per-atom
//     Ground positions obey the station formula
//         atomPosG[a] == X_GB[b].p() + X_GB[b].R() * atomStation_B[a]
//     and atomStationG[a] == R_GB * atomStation_B[a], to machine precision.
//     This is the kTight golden the Phase 3/6 constraint+transfer tests assume.
//
//  NOT PORTED / DEFERRED: the z-matrix-driven atom placement (model.zI/zJ/zK/zL)
//  is the production path; these hand-built robots set stations directly, which
//  is what the multibody/constraint tests need. The z-matrix transfer is a
//  separate (OpenMM-pipeline) concern and is not exercised here.
// ============================================================================
#include 
#include 
#include 

#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::attachAtoms;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// Ground -> Free(body 1) -> Torsion(body 2). Random static frames.
RobotModel twoBody(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.0);
        s.com_B = rng.vec3(-0.2, 0.2);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        return s;
    };
    return buildForest({mk(0, JointType::Free), mk(1, JointType::Torsion)});
}

} // namespace

// ---------------------------------------------------------------------------
//  P1 (pure): attachAtoms populates the per-atom arrays and sets the root atom.
// ---------------------------------------------------------------------------
TEST(Builders, AttachAtomsPopulatesArrays) {
    Rng rng(0xA70);
    RobotModel m = twoBody(rng);
    EXPECT_EQ(m.numAtoms, 0); // buildForest is atom-free

    const std::vector st1 = {Vec3(0, 0, 0), Vec3(0.1, 0, 0)};
    const std::vector ms1 = {12.0, 1.0};
    const std::vector st2 = {Vec3(0, 0.15, 0)};
    const std::vector ms2 = {16.0};

    attachAtoms(m, 1, st1, ms1);
    attachAtoms(m, 2, st2, ms2);

    ASSERT_EQ(m.numAtoms, 3);
    // atom 0,1 -> body 1 ; atom 2 -> body 2 (append order)
    EXPECT_EQ(m.atomBody[0], 1);
    EXPECT_EQ(m.atomBody[1], 1);
    EXPECT_EQ(m.atomBody[2], 2);
    EXPECT_TRUE(rtest::NearVec3(m.atomStation_B[0], st1[0], rtest::kTight));
    EXPECT_TRUE(rtest::NearVec3(m.atomStation_B[1], st1[1], rtest::kTight));
    EXPECT_TRUE(rtest::NearVec3(m.atomStation_B[2], st2[0], rtest::kTight));
    EXPECT_EQ(m.atomMass[0], 12.0);
    EXPECT_EQ(m.atomMass[2], 16.0);
    // first atom on each body becomes that body's root atom
    EXPECT_EQ(m.bodyRootAtom[1], 0);
    EXPECT_EQ(m.bodyRootAtom[2], 2);
    // compound index == array position (the atom index identity)
    EXPECT_EQ(m.atomCompoundIndex[2], 2);
}

// ---------------------------------------------------------------------------
//  P2 (pure): the body->atoms CSR partitions every atom exactly once, each
//  under its own body. (Constraint/transfer tests walk a body's atoms via CSR.)
// ---------------------------------------------------------------------------
TEST(Builders, AtomCsrPartitionsAllAtoms) {
    Rng rng(0xA71);
    RobotModel m = twoBody(rng);
    attachAtoms(m, 2, {Vec3(0, 0, 0), Vec3(0.1, 0.1, 0)}, {14.0, 1.0});
    attachAtoms(m, 1, {Vec3(0, 0, 0)}, {12.0}); // attach to a DIFFERENT body second

    // CSR ranges are non-overlapping, cover [0,numAtoms), and every listed atom
    // sits under the body whose range contains it.
    std::vector seen(static_cast(m.numAtoms), 0);
    int total = 0;
    for (int b = 0; b < m.numBodies; ++b) {
        ASSERT_LE(m.bodyAtomsBeg[b], m.bodyAtomsEnd[b]);
        for (int i = m.bodyAtomsBeg[b]; i < m.bodyAtomsEnd[b]; ++i) {
            const int a = m.bodyAtoms[static_cast(i)];
            EXPECT_EQ(m.atomBody[a], b) << "atom " << a << " listed under wrong body";
            seen[static_cast(a)]++;
            total++;
        }
    }
    EXPECT_EQ(total, m.numAtoms);
    for (int a = 0; a < m.numAtoms; ++a) {
        EXPECT_EQ(seen[static_cast(a)], 1) << "atom " << a << " not covered exactly once";
    }
}

// ---------------------------------------------------------------------------
//  P3 (pure): a virtual site (mass == 0) is stored verbatim, not dropped. The
//  force reduction skips it, but the model must still carry it (it has a station
//  and a body), so a regression that filters mass==0 at attach time is caught.
// ---------------------------------------------------------------------------
TEST(Builders, VirtualSiteMassZeroPreserved) {
    Rng rng(0xA72);
    RobotModel m = twoBody(rng);
    attachAtoms(m, 1, {Vec3(0, 0, 0), Vec3(0.05, 0, 0)}, {16.0, 0.0}); // 2nd is an M-site
    ASSERT_EQ(m.numAtoms, 2);
    EXPECT_EQ(m.atomMass[1], 0.0);
    EXPECT_TRUE(rtest::NearVec3(m.atomStation_B[1], Vec3(0.05, 0, 0), rtest::kTight));
    EXPECT_EQ(m.atomBody[1], 1);
}

// ---------------------------------------------------------------------------
//  P4 (engine): the station formula golden -- the kTight invariant every
//  downstream constraint/transfer test depends on.
//      atomPosG[a]     == X_GB[b].p() + X_GB[b].R() * atomStation_B[a]
//      atomStationG[a] == X_GB[b].R() * atomStation_B[a]
//  attachAtoms MUST precede allocateFull (the state sizes atom arrays from
//  model.numAtoms); this test pins that ordering contract by construction.
// ---------------------------------------------------------------------------
TEST(Builders, StationFormulaExactAfterRealize) {
    Rng rng(0xA73);
    RobotModel m = twoBody(rng);
    attachAtoms(m, 1, {Vec3(0.0, 0.0, 0.0), Vec3(0.12, -0.03, 0.05)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.0, 0.10, 0.0), Vec3(-0.04, 0.0, 0.07)}, {16.0, 1.0});

    RobotState s;
    s.allocateFull(m); // AFTER attachAtoms -> atom arrays sized for numAtoms
    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        const Transform* X_GB = s.X_GB();
        const Vec3* posG = s.atomPosG();
        const Vec3* stG = s.atomStationG();
        for (int a = 0; a < m.numAtoms; ++a) {
            const int b = m.atomBody[a];
            const Vec3 st = X_GB[b].R() * m.atomStation_B[a];
            EXPECT_TRUE(rtest::NearVec3(stG[a], st, rtest::kTight)) << "stationG atom " << a;
            EXPECT_TRUE(rtest::NearVec3(posG[a], X_GB[b].p() + st, rtest::kTight))
                << "posG atom " << a << " rep " << rep;
        }
    }
}

// ============================================================================
//  TestConstraints.cpp -- Phase 3: the PUBLIC loop-closure paths of
//  robo::ConstraintSet on a real hand-built robot forest -- SHAKE
//  (enforcePositionConstraints), RATTLE (enforceVelocityConstraints), the
//  Jacobian-transpose force map (mapAtomForcesToGeneralizedForces), the
//  loop-closure Fixman term (calcConstraintLogDet), and manifold preservation
//  under the real templated verletStep + AnalyticForceBridge.
//
//  The private dense solvers (solveSmallSpd / solveCoupling) already have a
//  direct test in TestConstraintSolver.cpp via ConstraintTestAccess; here we
//  exercise the production-facing entry points end to end.
//
//  FIXTURE. A single ring is the macrocycle the header is written for:
//      Ground -> b1 (Free) -> b2 (Torsion) -> b3 (Torsion)
//  with atoms on each body and ONE DistanceConstraint joining an atom on b1 to
//  an atom on b3 (different bodies, so the bond's path runs through the shared
//  torsion u -- the loop the spanning tree carries one too many DOF for). d0 is
//  taken from a chosen reference configuration so C(q_ref) == 0 exactly, then
//  the state is opened so |C| >> tol and the projection has real work to do.
//
//  ORACLE. The dense coupling matrix A = G M^-1 G^T is assembled with the SAME
//  primitives the engine uses -- mapAtomForcesToGeneralizedForces on the
//  (+vecAB at A, -vecAB at B) unit pattern gives a row of G^T, multiplyByMInv
//  gives the matching M^-1 G^T column, and A[r][c] = (G^T_r) . (M^-1 G^T_c).
//  That is byte-for-byte how solveCoupling builds A, so ln det A from
//  robo_linalg::logDetSymPD is an independent check of calcConstraintLogDet.
// ============================================================================
#include 
#include 
#include 
#include 
#include 

#include "AnalyticForceBridge.hpp"
#include "Constraints.hpp"
#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotIntegrator.hpp"
#include "RobotLinearAlgebra.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::attachAtoms;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// ---- named tolerances local to the constraint paths ------------------------
constexpr Real kShakeTol = Real(1e-10); // SHAKE convergence target (== solver default)
constexpr Real kConstr = Real(1e-9);    // post-RATTLE bond-rate residual
constexpr Real kManifold = Real(1e-8);  // trajectory drift of |C| / |G u|

// The ring atoms inside the loop fixture. b1 has atoms {0,1}; b2 {2,3}; b3 {4,5}.
// The ring-closing bond joins atom A on b1 to atom B on b3.
constexpr int kAtomA = 0; // on body 1 (Free)
constexpr int kAtomB = 4; // on body 3 (Torsion)

// ---------------------------------------------------------------------------
//  Build Ground -> Free -> Torsion -> Torsion with two atoms per moving body.
//  No constraint is added here; the caller attaches the DistanceConstraint with
//  a d0 it reads off a reference configuration (so C(q_ref) == 0 exactly).
// ---------------------------------------------------------------------------
RobotModel buildRingChain(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3(-0.3, 0.3));
        s.X_BM = Transform(rng.rotation(), rng.vec3(-0.3, 0.3));
        s.mass = rng.uniform(0.8, 1.6);
        s.com_B = rng.vec3(-0.1, 0.1);
        s.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
        return s;
    };
    RobotModel m =
        buildForest({mk(0, JointType::Free), mk(1, JointType::Torsion), mk(2, JointType::Torsion)});
    attachAtoms(m, 1, {Vec3(0.0, 0.0, 0.0), Vec3(0.11, -0.02, 0.04)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.05, 0.10, 0.0), Vec3(-0.03, 0.0, 0.06)}, {14.0, 1.0});
    attachAtoms(m, 3, {Vec3(0.0, 0.07, -0.05), Vec3(0.04, 0.0, 0.05)}, {16.0, 1.0});
    return m;
}

// refresh closure the SHAKE solver needs: realizePosition refills X_GB/H/atomPosG
// (C is nonlinear in q), realizeArticulatedBodyInertias refills P/G/DI for the
// multiplyByMInv inside the projection.
void refreshFor(const RobotModel& m, RobotState& s) {
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
}

// C(q) = |r_AB|^2 - d0^2 for one distance bond, read off the current atom posns.
Real evalC(const RobotModel& m, const RobotState& s, const DistanceConstraint& bond) {
    (void)m;
    const Vec3* p = s.atomPosG();
    const Vec3 vecAB = p[bond.atomA] - p[bond.atomB];
    return dot(vecAB, vecAB) - bond.restLength * bond.restLength;
}

// G u = relative velocity along the bond = dot(vecAB, vA - vB) -- the exact rhs
// enforceVelocityConstraints projects to zero (== half d/dt C along u).
Real evalGu(const RobotModel& m, const RobotState& s, const DistanceConstraint& bond) {
    const Transform* X_GB = s.X_GB();
    const Vec3* posG = s.atomPosG();
    const SpatialVec* V_GB = s.V_GB();
    const Vec3 vecAB = posG[bond.atomA] - posG[bond.atomB];
    const int bA = m.atomBody[bond.atomA];
    const int bB = m.atomBody[bond.atomB];
    const Vec3 stA = posG[bond.atomA] - X_GB[bA].p();
    const Vec3 stB = posG[bond.atomB] - X_GB[bB].p();
    const Vec3 vA = V_GB[bA].linear + (V_GB[bA].angular % stA);
    const Vec3 vB = V_GB[bB].linear + (V_GB[bB].angular % stB);
    return dot(vecAB, vA - vB);
}

// Assemble one row of G^T (mapAtomForcesToGeneralizedForces on the +/-vecAB
// pattern) and its M^-1 G^T partner -- the engine's exact assembly. Fills both
// jacT and minvJacT (each length nu). Requires position + ABI realized.
void assembleConstraintRow(const RobotModel& m,
                           RobotState& s,
                           const DistanceConstraint& bond,
                           std::vector& jacT,
                           std::vector& minvJacT) {
    const Vec3* posG = s.atomPosG();
    const Vec3 vecAB = posG[bond.atomA] - posG[bond.atomB];
    std::vector atomForce(static_cast(m.numAtoms), Vec3(0));
    atomForce[static_cast(bond.atomA)] = vecAB;
    atomForce[static_cast(bond.atomB)] = Vec3(0) - vecAB;
    jacT.assign(static_cast(m.nu), 0);
    minvJacT.assign(static_cast(m.nu), 0);
    ConstraintSet::mapAtomForcesToGeneralizedForces(m, s, atomForce.data(), jacT.data());
    RobotEngine::multiplyByMInv(m, s, jacT.data(), minvJacT.data());
}

// Dense A = G M^-1 G^T (numC x numC, row-major) assembled exactly as solveCoupling
// does. Requires position + ABI realized.
std::vector denseCoupling(const RobotModel& m, RobotState& s, const ConstraintSet& cset) {
    const int numC = cset.numConstraints();
    std::vector<std::vector> jacT(static_cast(numC));
    std::vector<std::vector> minvJacT(static_cast(numC));
    for (int c = 0; c < numC; ++c) {
        assembleConstraintRow(m,
                              s,
                              cset.distance[static_cast(c)],
                              jacT[static_cast(c)],
                              minvJacT[static_cast(c)]);
    }
    std::vector A(static_cast(numC * numC), 0);
    for (int r = 0; r < numC; ++r) {
        for (int c = 0; c < numC; ++c) {
            Real acc = 0;
            for (int i = 0; i < m.nu; ++i) {
                acc += jacT[static_cast(r)][static_cast(i)]
                       * minvJacT[static_cast(c)][static_cast(i)];
            }
            A[static_cast(r * numC + c)] = acc;
        }
    }
    return A;
}

// Seed the derivative chain so the first verletStep has valid qdot0/udot0/qdd0.
void seedDerivatives(const RobotModel& m, RobotState& s, AnalyticForceBridge& bridge) {
    RobotEngine::realizePosition(m, s);
    RobotEngine::fillAtomPositionsFromBodies(m, s);
    bridge.evaluate(s);
    RobotEngine::realizeVelocity(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
    RobotEngine::calcUDot(m, s);
    RobotEngine::calcQDot(m, s, s.qdot());
    RobotEngine::calcQDotDot(m, s);
}

} // namespace

// ===========================================================================
//  1. MapAtomForcesEqualsJacobianTranspose
//     mapAtomForcesToGeneralizedForces IS J^T. With atomForce = (+vecAB at A,
//     -vecAB at B), tau = (J_A - J_B)^T vecAB = (1/2) dC/dq. We verify it as a
//     central finite difference of C taken in u-space (perturb each u direction
//     by applyVelSpaceIncrementToQ, refresh atoms, recompute C). MUST-FAIL: the
//     flipped A/B sign breaks it -- pinning the "verify once against a finite-
//     difference of C" comment in the code.
// ===========================================================================
TEST(Constraints, MapAtomForcesEqualsJacobianTranspose) {
    Rng rng(0xC03A);
    RobotModel m = buildRingChain(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    refreshFor(m, s);

    DistanceConstraint bond;
    bond.atomA = kAtomA;
    bond.atomB = kAtomB;
    bond.restLength = 0; // C = |rAB|^2 here; d0 irrelevant to dC/dq.

    // tau = J^T (vecAB at A, -vecAB at B): the engine's assembly.
    std::vector jacT, minvJacT;
    assembleConstraintRow(m, s, bond, jacT, minvJacT);

    // Central FD of C along each u-direction. applyVelSpaceIncrementToQ maps a
    // u-space increment onto q (quaternion DOF go through N(q)), so this is the
    // directional derivative dC/du_i, which must equal 2*tau[i].
    const Real h = Real(1e-6);
    for (int i = 0; i < m.nu; ++i) {
        std::vector qSave(s.q(), s.q() + m.nq);

        std::vector dvel(static_cast(m.nu), 0);
        dvel[static_cast(i)] = h;
        ConstraintSet::applyVelSpaceIncrementToQ(m, s, dvel.data());
        RobotEngine::realizePosition(m, s);
        const Real cPlus = evalC(m, s, bond);

        std::copy(qSave.begin(), qSave.end(), s.q());
        dvel[static_cast(i)] = -h;
        ConstraintSet::applyVelSpaceIncrementToQ(m, s, dvel.data());
        RobotEngine::realizePosition(m, s);
        const Real cMinus = evalC(m, s, bond);

        std::copy(qSave.begin(), qSave.end(), s.q());
        RobotEngine::realizePosition(m, s);

        const Real dCdu = (cPlus - cMinus) / (2 * h);
        EXPECT_NEAR(jacT[static_cast(i)], Real(0.5) * dCdu, rtest::kFD) << "u-direction " << i;
    }

    // MUST-FAIL guard: flip the A/B sign of the atom force. tau negates, so it
    // can no longer equal +1/2 dC/du -- at least one component must disagree.
    std::vector flipped(static_cast(m.numAtoms), Vec3(0));
    const Vec3* p = s.atomPosG();
    const Vec3 vecAB = p[bond.atomA] - p[bond.atomB];
    flipped[static_cast(bond.atomA)] = Vec3(0) - vecAB; // wrong sign
    flipped[static_cast(bond.atomB)] = vecAB;           // wrong sign
    std::vector tauFlipped(static_cast(m.nu), 0);
    ConstraintSet::mapAtomForcesToGeneralizedForces(m, s, flipped.data(), tauFlipped.data());

    bool anyDisagree = false;
    const Real h2 = Real(1e-6);
    for (int i = 0; i < m.nu; ++i) {
        std::vector qSave(s.q(), s.q() + m.nq);
        std::vector dvel(static_cast(m.nu), 0);
        dvel[static_cast(i)] = h2;
        ConstraintSet::applyVelSpaceIncrementToQ(m, s, dvel.data());
        RobotEngine::realizePosition(m, s);
        const Real cPlus = evalC(m, s, bond);
        std::copy(qSave.begin(), qSave.end(), s.q());
        dvel[static_cast(i)] = -h2;
        ConstraintSet::applyVelSpaceIncrementToQ(m, s, dvel.data());
        RobotEngine::realizePosition(m, s);
        const Real cMinus = evalC(m, s, bond);
        std::copy(qSave.begin(), qSave.end(), s.q());
        RobotEngine::realizePosition(m, s);
        const Real halfDC = Real(0.5) * (cPlus - cMinus) / (2 * h2);
        if (std::abs(tauFlipped[static_cast(i)] - halfDC) > 1e-5) {
            anyDisagree = true;
        }
    }
    EXPECT_TRUE(anyDisagree)
        << "flipped-sign atom force still matched 1/2 dC/du -- the A/B convention is not pinned";
}

// ===========================================================================
//  2. ShakeDrivesPositionConstraintToZero
//     Open the ring (|C| >> tol), SHAKE it shut. PASS: returns iter < maxIter and
//     |C| <= tol. PASS: a body NOT in the loop is unmoved beyond the shared-u
//     coupling (forest locality). MUST-FAIL: maxIter == 0 leaves |C| unchanged.
// ===========================================================================
TEST(Constraints, ShakeDrivesPositionConstraintToZero) {
    Rng rng(0xC03B);
    // The ring chain plus an independent second robot (a lone Free body with
    // atoms) that shares NO u with the loop -- forest locality must leave it put.
    auto mk = [&](int parent, JointType jt) {
        BodySpec sp;
        sp.parent = parent;
        sp.joint = jt;
        sp.X_PF = Transform(rng.rotation(), rng.vec3(-0.3, 0.3));
        sp.X_BM = Transform(rng.rotation(), rng.vec3(-0.3, 0.3));
        sp.mass = rng.uniform(0.8, 1.6);
        sp.com_B = rng.vec3(-0.1, 0.1);
        sp.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
        return sp;
    };
    RobotModel m = buildForest({
        mk(0, JointType::Free),    // 1  loop body
        mk(1, JointType::Torsion), // 2  loop body
        mk(2, JointType::Torsion), // 3  loop body
        mk(0, JointType::Free),    // 4  SECOND robot (not in loop)
    });
    attachAtoms(m, 1, {Vec3(0.0, 0.0, 0.0), Vec3(0.11, -0.02, 0.04)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.05, 0.10, 0.0), Vec3(-0.03, 0.0, 0.06)}, {14.0, 1.0});
    attachAtoms(m, 3, {Vec3(0.0, 0.07, -0.05), Vec3(0.04, 0.0, 0.05)}, {16.0, 1.0});
    const int farAtomBeg = m.numAtoms;
    attachAtoms(m, 4, {Vec3(0.02, 0.0, 0.0), Vec3(0.0, 0.08, 0.0)}, {15.0, 1.0});
    const int farAtomEnd = m.numAtoms;

    RobotState s;
    s.allocateFull(m);

    // Reference config: set d0 to the actual current A-B distance so C == 0,
    // then OPEN the ring by re-randomizing.
    randomizeState(m, s, rng);
    refreshFor(m, s);
    const Vec3* p0 = s.atomPosG();
    const Real d0 = (p0[kAtomA] - p0[kAtomB]).norm();

    ConstraintSet cset;
    cset.distance.push_back(DistanceConstraint{kAtomA, kAtomB, d0});

    // Open the loop: a fresh random state breaks |rAB| away from d0.
    randomizeState(m, s, rng);
    refreshFor(m, s);
    const Real cOpen = evalC(m, s, cset.distance[0]);
    ASSERT_GT(std::abs(cOpen), 1e-3) << "setup failed to open the ring; reseed";

    // snapshot the far robot's atoms BEFORE projection
    std::vector farBefore;
    for (int a = farAtomBeg; a < farAtomEnd; ++a) {
        farBefore.push_back(s.atomPosG()[a]);
    }

    // MUST-FAIL guard: maxIter == 0 does no projection -> violation unchanged.
    {
        RobotState sGuard;
        sGuard.allocateFull(m);
        std::copy(s.q(), s.q() + m.nq, sGuard.q());
        std::copy(s.u(), s.u() + m.nu, sGuard.u());
        refreshFor(m, sGuard);
        const Real cBefore = evalC(m, sGuard, cset.distance[0]);
        const int it0 = cset.enforcePositionConstraints(
            m,
            sGuard,
            [&]() {
                refreshFor(m, sGuard);
            },
            kShakeTol,
            /*maxIter=*/0);
        const Real cAfter = evalC(m, sGuard, cset.distance[0]);
        EXPECT_EQ(it0, 0);
        EXPECT_NEAR(cBefore, cAfter, 1e-14)
            << "maxIter=0 changed C -- setup, not projection, is satisfying it";
    }

    // Real SHAKE: converges in < maxIter, drives |C| to <= tol.
    const int iter = cset.enforcePositionConstraints(
        m,
        s,
        [&]() {
            refreshFor(m, s);
        },
        kShakeTol,
        50);
    refreshFor(m, s);
    EXPECT_LT(iter, 50) << "SHAKE did not converge within the iteration cap";
    EXPECT_LE(std::abs(evalC(m, s, cset.distance[0])), kShakeTol) << "ring still open after SHAKE";

    // Forest locality: the second robot shares no u with the loop, so M^-1 G^T
    // is identically zero on its block and its atoms cannot move.
    for (int k = 0; k < farAtomEnd - farAtomBeg; ++k) {
        EXPECT_TRUE(rtest::NearVec3(s.atomPosG()[farAtomBeg + k],
                                    farBefore[static_cast(k)],
                                    rtest::kTight))
            << "off-loop atom " << (farAtomBeg + k) << " moved -- forest locality broken";
    }
}

// ===========================================================================
//  3. RattleProjectsVelocityOntoConstraintSurface
//     After realizeVelocity, G u (the bond-length rate) is nonzero; RATTLE kills
//     it. PASS: |G u| <= tol. PASS: idempotent (second call is a no-op on u).
//     PASS: only the along-bond (minvJacobianT) component is removed; the
//     orthogonal complement of u is preserved.
// ===========================================================================
TEST(Constraints, RattleProjectsVelocityOntoConstraintSurface) {
    Rng rng(0xC03C);
    RobotModel m = buildRingChain(rng);
    RobotState s;
    s.allocateFull(m);

    randomizeState(m, s, rng);
    refreshFor(m, s);
    const Vec3* p0 = s.atomPosG();
    const Real d0 = (p0[kAtomA] - p0[kAtomB]).norm();
    ConstraintSet cset;
    cset.distance.push_back(DistanceConstraint{kAtomA, kAtomB, d0});

    // generic velocity -> nonzero bond-length rate
    randomizeState(m, s, rng);
    refreshFor(m, s);
    RobotEngine::realizeVelocity(m, s);
    const Real guBefore = evalGu(m, s, cset.distance[0]);
    ASSERT_GT(std::abs(guBefore), 1e-3) << "velocity already on the surface; reseed";

    // the along-bond direction in u-space: M^-1 G^T (the only direction RATTLE
    // is allowed to touch). Captured BEFORE the projection.
    std::vector jacT, minvJacT;
    assembleConstraintRow(m, s, cset.distance[0], jacT, minvJacT);
    std::vector uBefore(s.u(), s.u() + m.nu);

    // RATTLE
    cset.enforceVelocityConstraints(m, s);
    RobotEngine::realizeVelocity(m, s);
    EXPECT_LE(std::abs(evalGu(m, s, cset.distance[0])), kConstr) << "bond-length rate not killed";

    // Idempotent: a second projection leaves u unchanged.
    std::vector uAfter1(s.u(), s.u() + m.nu);
    cset.enforceVelocityConstraints(m, s);
    RobotEngine::realizeVelocity(m, s);
    for (int i = 0; i < m.nu; ++i) {
        EXPECT_NEAR(s.u()[i], uAfter1[static_cast(i)], kConstr)
            << "RATTLE not idempotent at u[" << i << "]";
    }

    // Energy-only: the update du = u_after - u_before is a pure multiple of
    // minvJacobianT (a single ring -> a single direction). Any component of u
    // orthogonal to minvJacobianT is therefore preserved exactly.
    Real mm = 0;
    for (int i = 0; i < m.nu; ++i) {
        mm += minvJacT[static_cast(i)] * minvJacT[static_cast(i)];
    }
    ASSERT_GT(mm, 0.0);
    // du must be parallel to minvJacT: du - (du.mhat) mhat == 0.
    Real duDotM = 0;
    for (int i = 0; i < m.nu; ++i) {
        duDotM += (uAfter1[static_cast(i)] - uBefore[static_cast(i)])
                  * minvJacT[static_cast(i)];
    }
    const Real coeff = duDotM / mm;
    for (int i = 0; i < m.nu; ++i) {
        const Real du = uAfter1[static_cast(i)] - uBefore[static_cast(i)];
        EXPECT_NEAR(du, coeff * minvJacT[static_cast(i)], rtest::kLoose)
            << "RATTLE moved u off the minvJacobianT direction at u[" << i << "]";
    }

    // Concretely: pick a test direction orthogonal to minvJacT and confirm its
    // projection of u is unchanged to kLoose.
    std::vector e(static_cast(m.nu), 0);
    e[0] = 1.0; // arbitrary probe
    Real eDotM = 0;
    for (int i = 0; i < m.nu; ++i) {
        eDotM += e[static_cast(i)] * minvJacT[static_cast(i)];
    }
    for (int i = 0; i < m.nu; ++i) {
        e[static_cast(i)] -=
            (eDotM / mm) * minvJacT[static_cast(i)]; // make e _|_ minvJacT
    }
    Real projBefore = 0, projAfter = 0;
    for (int i = 0; i < m.nu; ++i) {
        projBefore += e[static_cast(i)] * uBefore[static_cast(i)];
        projAfter += e[static_cast(i)] * uAfter1[static_cast(i)];
    }
    EXPECT_NEAR(projBefore, projAfter, rtest::kLoose)
        << "u component orthogonal to the bond direction was not preserved";
}

// ===========================================================================
//  4. ConstraintManifoldPreservedUnderIntegration
//     Integrate the ring with the real templated verletStep + AnalyticForceBridge
//     + the ConstraintSet. PASS: max_t |C| and max_t |G u| stay <= 1e-8 across
//     2000 steps (the secular drift the header warns about never opens the ring).
//     PASS (O(h^2)): halving h shrinks the energy drift by ~4x.
// ===========================================================================
TEST(Constraints, ConstraintManifoldPreservedUnderIntegration) {
    Rng rng(0xC03D);
    RobotModel m = buildRingChain(rng);
    RobotState s;
    s.allocateFull(m);

    // Build a closed, gently-moving start state and freeze the ring at d0.
    randomizeState(m, s, rng);
    Real* u0 = s.u();
    for (int i = 0; i < m.nu; ++i) {
        u0[i] *= 0.05; // gentle velocities so the step is benign
    }
    refreshFor(m, s);
    const Vec3* p0 = s.atomPosG();
    const Real d0 = (p0[kAtomA] - p0[kAtomB]).norm();

    ConstraintSet cset;
    cset.distance.push_back(DistanceConstraint{kAtomA, kAtomB, d0});

    AnalyticForceBridge bridge(m, s, /*k=*/80.0);

    // Project the start state ONTO the manifold first (SHAKE then RATTLE), so the
    // trajectory begins exactly on C = 0, G u = 0.
    cset.enforcePositionConstraints(
        m,
        s,
        [&]() {
            refreshFor(m, s);
        },
        kShakeTol,
        50);
    refreshFor(m, s);
    RobotEngine::realizeVelocity(m, s);
    cset.enforceVelocityConstraints(m, s);
    seedDerivatives(m, s, bridge);

    const Real h = Real(5e-4);
    Real maxC = 0, maxGu = 0;
    for (int n = 0; n < 2000; ++n) {
        const bool ok = RobotEngine::verletStep(m, s, bridge, cset, h);
        ASSERT_TRUE(ok) << "step " << n << " rejected";
        RobotEngine::realizeVelocity(m, s);
        maxC = std::max(maxC, std::abs(evalC(m, s, cset.distance[0])));
        maxGu = std::max(maxGu, std::abs(evalGu(m, s, cset.distance[0])));
    }
    EXPECT_LE(maxC, kManifold) << "position constraint drifted: max|C| = " << maxC;
    EXPECT_LE(maxGu, kManifold) << "velocity constraint drifted: max|G u| = " << maxGu;

    // O(h^2): integrate the SAME closed start at h and h/2 over the SAME physical
    // time; the RATTLE energy drift is quadratic (Andersen Appendix B), so the
    // ratio drift(h)/drift(h/2) lands near 4. The two runs MUST share an identical
    // start configuration -- otherwise the ratio compares two unrelated drifts and
    // is only statistically ~4. A fixed local seed gives both runs the same q0,u0.
    auto driftAt = [&](Real step, int nSteps) -> Real {
        Rng seedRng(0x0F1E2D3C); // identical start state for every call
        RobotState st;
        st.allocateFull(m);
        randomizeState(m, st, seedRng);
        Real* uu = st.u();
        for (int i = 0; i < m.nu; ++i) {
            uu[i] *= 0.05;
        }
        refreshFor(m, st);
        const Vec3* pp = st.atomPosG();
        const Real dd = (pp[kAtomA] - pp[kAtomB]).norm();
        ConstraintSet cs;
        cs.distance.push_back(DistanceConstraint{kAtomA, kAtomB, dd});
        AnalyticForceBridge br(m, st, 80.0);
        cs.enforcePositionConstraints(
            m,
            st,
            [&]() {
                refreshFor(m, st);
            },
            kShakeTol,
            50);
        refreshFor(m, st);
        RobotEngine::realizeVelocity(m, st);
        cs.enforceVelocityConstraints(m, st);
        seedDerivatives(m, st, br);
        const Real E0 = RobotEngine::calcKineticEnergy(m, st) + br.calcPotentialEnergy(st);
        Real worst = 0;
        for (int n = 0; n < nSteps; ++n) {
            const bool ok = RobotEngine::verletStep(m, st, br, cs, step);
            if (!ok) {
                return std::numeric_limits::infinity();
            }
            const Real E = RobotEngine::calcKineticEnergy(m, st) + br.calcPotentialEnergy(st);
            worst = std::max(worst, std::abs(E - E0));
        }
        return worst;
    };
    // same total time: 600 steps at h, 1200 steps at h/2.
    const Real driftH = driftAt(h, 600);
    const Real driftHalf = driftAt(h / 2, 1200);
    ASSERT_GT(driftHalf, 0.0);
    const Real ratio = driftH / driftHalf;
    EXPECT_GE(ratio, 3.0) << "energy drift not shrinking ~4x under h/2 (ratio " << ratio << ")";
    EXPECT_LE(ratio, 5.0) << "energy drift shrinking too fast for O(h^2) (ratio " << ratio << ")";
}

// ===========================================================================
//  5. ConstraintLogDetMatchesDenseLnDet
//     calcConstraintLogDet returns ln det(G M^-1 G^T) (up to the documented
//     constant that cancels in any dH). Compare against the dense A built from
//     the same assembly via robo_linalg::logDetSymPD. PASS: single ring (1x1)
//     and a two-ring (2x2) case agree to 1e-7. PASS: acyclic -> exactly 0.0.
//     MUST-FAIL: the cyclic return must be != 0 (catches a regression that
//     early-returns 0 for cyclic systems -- the bug the header was written for).
// ===========================================================================
TEST(Constraints, ConstraintLogDetMatchesDenseLnDet) {
    Rng rng(0xC03E);
    RobotModel m = buildRingChain(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);

    RobotEngine::realizePosition(m, s);
    const Vec3* p0 = s.atomPosG();
    const Real d0 = (p0[kAtomA] - p0[kAtomB]).norm();

    // ---- single ring: A is 1x1, ln det A == ln(A00) ----
    {
        ConstraintSet cset;
        cset.distance.push_back(DistanceConstraint{kAtomA, kAtomB, d0});

        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        const std::vector A = denseCoupling(m, s, cset); // 1x1
        const Real lnDetDense = robo_linalg::logDetSymPD(A.data(), 1);

        const Real lnDet = cset.calcConstraintLogDet(m, s);
        EXPECT_NEAR(lnDet, lnDetDense, 1e-7) << "single-ring ln det mismatch";

        // MUST-FAIL guard: a cyclic system must NOT return 0 (the early-return bug).
        EXPECT_GT(std::abs(lnDet), 1e-12)
            << "cyclic calcConstraintLogDet returned ~0 -- loop-closure Fixman term lost";
    }

    // ---- two rings: A is 2x2, exercises the dense logdet path ----
    {
        // A second independent ring-closing bond on the SAME chain: join atom 1
        // (on b1) to atom 5 (on b3). Distinct from the first bond, so A is a
        // genuine 2x2 (the two constraints share u, off-diagonal nonzero).
        RobotEngine::realizePosition(m, s);
        const Vec3* p = s.atomPosG();
        const Real d1 = (p[1] - p[5]).norm();

        ConstraintSet cset2;
        cset2.distance.push_back(DistanceConstraint{kAtomA, kAtomB, d0});
        cset2.distance.push_back(DistanceConstraint{1, 5, d1});

        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        const std::vector A = denseCoupling(m, s, cset2); // 2x2
        const Real lnDetDense = robo_linalg::logDetSymPD(A.data(), 2);

        const Real lnDet = cset2.calcConstraintLogDet(m, s);
        EXPECT_NEAR(lnDet, lnDetDense, 1e-7) << "two-ring ln det mismatch";
    }

    // ---- acyclic: empty distance set returns EXACTLY 0.0 ----
    {
        const ConstraintSet empty;
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        const Real lnDet = empty.calcConstraintLogDet(m, s);
        EXPECT_EQ(lnDet, 0.0) << "acyclic calcConstraintLogDet must be an exact no-op";
    }
}

// ============================================================================
//  TestConstraintSolver.cpp -- Phase 0.3: the private dense coupling solvers of
//  ConstraintSet, reached via the friend ConstraintTestAccess.
//
//  solveSmallSpd(A, b, &lnDet) solves A x = b for a small SPD A (Gauss-Jordan,
//  partial pivot) and returns ln|det A| as a by-product. solveCoupling assembles
//  A = G M^-1 G^T from (G^T rows, M^-1 G^T rows) and forwards to solveSmallSpd.
//  Both are load-bearing for SHAKE/RATTLE (the Lagrange-multiplier solve) and
//  for calcConstraintLogDet (the loop-closure Fixman term), so they get a direct
//  test here in addition to the public-path coverage planned for TestConstraints.
//
//  Cross-link: the ln|det A| solveSmallSpd reports must match the independent
//  Cholesky log-determinant robo_linalg::logDetSymPD (the freshly hoisted Phase
//  0.1 symbol) for SPD inputs.
// ============================================================================
#include 
#include 
#include 

#include "ConstraintTestAccess.hpp"
#include "RobotLinearAlgebra.hpp"
#include "TestHelpers.hpp"

using robo::ConstraintTestAccess;
using robo::Real;
using rtest::Rng;

namespace {

// dense A (vector-of-rows) times x.
std::vector matVecRows(const std::vector<std::vector>& A, const std::vector& x) {
    const int n = static_cast(x.size());
    std::vector y(static_cast(n), 0);
    for (int i = 0; i < n; ++i) {
        Real s = 0;
        for (int j = 0; j < n; ++j) {
            s += A[static_cast(i)][static_cast(j)] * x[static_cast(j)];
        }
        y[static_cast(i)] = s;
    }
    return y;
}

Real maxResidual(const std::vector& a, const std::vector& b) {
    Real d = 0;
    for (std::size_t i = 0; i < a.size(); ++i) {
        d = std::max(d, std::abs(a[i] - b[i]));
    }
    return d;
}

} // namespace

// ---------------------------------------------------------------------------
//  1. 2x2 SPD golden: known solution and known ln det.
// ---------------------------------------------------------------------------
TEST(ConstraintSolver, SolveSmallSpd2x2Golden) {
    // A = [[4,1],[1,3]], det = 11.  b = [1,2].
    std::vector<std::vector> A = {{4, 1}, {1, 3}};
    std::vector b = {1, 2};
    Real lnDet = 0;
    const std::vector x = ConstraintTestAccess::solveSmallSpd(A, b, &lnDet);

    // A x == b
    EXPECT_LT(maxResidual(matVecRows(A, x), b), rtest::kLoose);
    // closed-form: x = A^-1 b = (1/11)[[3,-1],[-1,4]] [1;2] = [1/11; 7/11]
    EXPECT_NEAR(x[0], 1.0 / 11.0, rtest::kLoose);
    EXPECT_NEAR(x[1], 7.0 / 11.0, rtest::kLoose);
    EXPECT_NEAR(lnDet, std::log(11.0), rtest::kLoose);
}

// ---------------------------------------------------------------------------
//  2. 1x1 trivial: x = b/A, ln det = ln A.
// ---------------------------------------------------------------------------
TEST(ConstraintSolver, SolveSmallSpd1x1) {
    std::vector<std::vector> A = {{7.0}};
    std::vector b = {3.5};
    Real lnDet = 0;
    const std::vector x = ConstraintTestAccess::solveSmallSpd(A, b, &lnDet);
    EXPECT_NEAR(x[0], 0.5, rtest::kTight);
    EXPECT_NEAR(lnDet, std::log(7.0), rtest::kTight);
}

// ---------------------------------------------------------------------------
//  3. Degenerate pivot stays FINITE (must not NaN): a zero diagonal is floored,
//     the log stays finite, and the corresponding solution component locks to 0.
//     (Mirrors the loop-closure case where a constraint row is rank-deficient.)
// ---------------------------------------------------------------------------
TEST(ConstraintSolver, SolveSmallSpdDegeneratePivotFinite) {
    std::vector<std::vector> A = {{0.0, 0.0}, {0.0, 2.0}};
    std::vector b = {1.0, 4.0};
    Real lnDet = 0;
    const std::vector x = ConstraintTestAccess::solveSmallSpd(A, b, &lnDet);
    EXPECT_TRUE(std::isfinite(lnDet)) << "degenerate pivot must keep ln|det| finite";
    for (Real xi : x) {
        EXPECT_TRUE(std::isfinite(xi));
    }
    EXPECT_EQ(x[0], 0.0) << "null direction must lock to 0, not blow up";
    EXPECT_NEAR(x[1], 2.0, rtest::kLoose); // the well-conditioned row still solves
}

// ---------------------------------------------------------------------------
//  4. solveSmallSpd ln|det| == independent Cholesky log-det (robo_linalg), for
//     random SPD matrices of size 1..6. Ties the constraint solver's determinant
//     by-product to the Phase 0.1 hoisted kernel.
// ---------------------------------------------------------------------------
TEST(ConstraintSolver, LnDetMatchesCholeskyLogDet) {
    Rng rng(0xC0501);
    for (int n : {1, 2, 3, 6}) {
        for (int t = 0; t < 50; ++t) {
            Real flat[36];
            rng.spd(n, flat, 0.4, 4.0); // row-major SPD
            std::vector<std::vector> A(static_cast(n),
                                             std::vector(static_cast(n)));
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    A[static_cast(i)][static_cast(j)] = flat[i * n + j];
                }
            }
            std::vector b(static_cast(n));
            for (int i = 0; i < n; ++i) {
                b[static_cast(i)] = rng.gaussian();
            }
            Real lnDet = 0;
            const std::vector x = ConstraintTestAccess::solveSmallSpd(A, b, &lnDet);
            EXPECT_LT(maxResidual(matVecRows(A, x), b), 1e-7) << "n=" << n;
            EXPECT_NEAR(lnDet, robo_linalg::logDetSymPD(flat, n), rtest::kLoose) << "n=" << n;
        }
    }
}

// ---------------------------------------------------------------------------
//  5. solveCoupling assembles A = G M^-1 G^T correctly: with G^T = I (jacobianT
//     identity rows) and M^-1 G^T = S (minvJacobianT = S rows), the coupling
//     matrix is exactly S, so the solve must match solveSmallSpd(S, rhs). Pins
//     the assembly AND proves solveCoupling is reachable.
// ---------------------------------------------------------------------------
TEST(ConstraintSolver, SolveCouplingAssemblesGMInvGt) {
    Rng rng(0xC0502);
    for (int n : {1, 2, 3}) {
        Real flat[9];
        rng.spd(n, flat, 0.5, 3.0);
        // jacobianT = identity (n rows of length numU=n); minvJacobianT = S rows.
        std::vector<std::vector> jacT(static_cast(n),
                                            std::vector(static_cast(n), 0));
        std::vector<std::vector> minvJacT(static_cast(n),
                                                std::vector(static_cast(n), 0));
        std::vector<std::vector> S(static_cast(n),
                                         std::vector(static_cast(n)));
        for (int i = 0; i < n; ++i) {
            jacT[static_cast(i)][static_cast(i)] = 1.0;
            for (int j = 0; j < n; ++j) {
                const Real v = flat[i * n + j];
                minvJacT[static_cast(i)][static_cast(j)] = v;
                S[static_cast(i)][static_cast(j)] = v;
            }
        }
        std::vector rhs(static_cast(n));
        for (int i = 0; i < n; ++i) {
            rhs[static_cast(i)] = rng.gaussian();
        }

        Real lnDetCoupling = 0, lnDetDirect = 0;
        const std::vector viaCoupling =
            ConstraintTestAccess::solveCoupling(jacT, minvJacT, rhs, n, n, &lnDetCoupling);
        const std::vector viaDirect = ConstraintTestAccess::solveSmallSpd(S, rhs, &lnDetDirect);

        EXPECT_LT(maxResidual(viaCoupling, viaDirect), rtest::kLoose) << "n=" << n;
        EXPECT_NEAR(lnDetCoupling, lnDetDirect, rtest::kLoose) << "n=" << n;
    }
}

// ============================================================================
//  test_geometry.cpp -- Part 1.9: calcDihedralAngle, pitch, safeLogSineSqr
// ============================================================================
#include 

#include "EngineHelpers.hpp"
#include "TestHelpers.hpp"
#include "robot_math.hpp"

using namespace rtest;
using robo::calcDihedralAngle;
using robo::Quat;
using robo::Rotation;
using robo::Vec3;

namespace {
// Build 4 points realizing a given dihedral phi about a central bond on +x.
void dihedralPoints(Real phi, Vec3& a, Vec3& b, Vec3& c, Vec3& d) {
    b = Vec3(0, 0, 0);
    c = Vec3(1, 0, 0);                             // central bond along +x
    a = b + Vec3(0, 1, 0);                         // first arm in +y from b
    d = c + Vec3(0, std::cos(phi), std::sin(phi)); // arm rotated by phi about x
}
} // namespace

TEST(Geometry, DihedralKnownAngles) {
    // Construction: d is rotated by +phi about the b->c (+x) axis (right-hand).
    // calcDihedralAngle follows the standard (IUPAC) convention, which for this
    // parameterization returns -phi. We assert magnitude AND the code's sign
    // convention explicitly (so a future sign regression is caught).
    for (Real phi : {0.0, 0.3, 1.0, 2.0, -0.7, M_PI / 2}) {
        Vec3 a, b, c, d;
        dihedralPoints(phi, a, b, c, d);
        const Real got = calcDihedralAngle(a, b, c, d);
        EXPECT_NEAR(std::abs(got), std::abs(phi), kAlg) << "phi=" << phi;
        if (std::abs(phi) > 1e-6 && std::abs(std::abs(phi) - M_PI) > 1e-6) {
            EXPECT_NEAR(got, -phi, kAlg) << "code sign convention (IUPAC), phi=" << phi;
        }
    }
}

TEST(Geometry, DihedralRigidMotionInvariant) {
    Rng rng(1);
    Vec3 a, b, c, d;
    dihedralPoints(0.9, a, b, c, d);
    const Real ref = calcDihedralAngle(a, b, c, d);
    for (int t = 0; t < 50; ++t) {
        const Rotation R = rng.rotation();
        const Vec3 sh = rng.vec3();
        const Real got = calcDihedralAngle(R * a + sh, R * b + sh, R * c + sh, R * d + sh);
        EXPECT_NEAR(got, ref, kAlg);
    }
}

TEST(Geometry, DihedralChiralityFlipsSign) {
    Vec3 a, b, c, d;
    dihedralPoints(0.9, a, b, c, d);
    const Real ref = calcDihedralAngle(a, b, c, d);
    // reflect through the x-z plane (y -> -y): chirality flips
    auto refl = [](const Vec3& v) {
        return Vec3(v[0], -v[1], v[2]);
    };
    const Real got = calcDihedralAngle(refl(a), refl(b), refl(c), refl(d));
    EXPECT_NEAR(got, -ref, kAlg);
}

// --- pitch extraction: sinPitch = 2(qw*qy - qz*qx) --------------------------
TEST(Geometry, PitchFromRotation) {
    for (Real theta = -1.2; theta < 1.2; theta += 0.1) {
        // pure pitch = rotation about Y by theta
        Rotation R;
        R.setRotationFromAngleAboutAxis(theta, robo::YAxis);
        Real w, x, y, z;
        EngineHelpers::rotationToQuaternion(R, w, x, y, z);
        const Real sinPitch = 2 * (w * y - z * x);
        EXPECT_NEAR(std::asin(std::max(Real(-1), std::min(Real(1), sinPitch))), theta, kAlg)
            << "theta=" << theta;
    }
}

// --- safeLogSineSqr: floor at the pole, exact away from it -------------------
TEST(Geometry, SafeLogSineSqrFloor) {
    using EngineHelpers::safeLogSineSqr;
    // at pitch = pi/2, sin^2 = 1 -> log = 0
    EXPECT_NEAR(safeLogSineSqr(M_PI / 2), 0.0, kAlg);
    // away from pole: equals ln(sin^2)
    for (Real p : {0.3, 0.6, 1.0, 1.4}) {
        const Real s = std::sin(p);
        EXPECT_NEAR(safeLogSineSqr(p), std::log(s * s), kAlg);
    }
    // at the pole: floored, finite, equals ln(1e-12)
    EXPECT_NEAR(safeLogSineSqr(0.0), std::log(1e-12), kAlg);
    EXPECT_TRUE(std::isfinite(safeLogSineSqr(0.0)));
    EXPECT_TRUE(std::isfinite(safeLogSineSqr(M_PI)));
}

// ============================================================================
//  TestHelpers.hpp -- shared utilities for the Robosample primitive test suite
//
//  Deterministic RNG (fixed seed, Rule 9), random generators for the robo::
//  value types, double-cover-aware comparators, and finite-difference helpers.
//  Everything here is pure and header-only so each test translation unit can
//  include it without a link dependency.
// ============================================================================
#pragma once

#include 
#include 
#include 
#include 

#include "robot_math.hpp"

namespace rtest {

using robo::Mat33;
using robo::Quat;
using robo::Real;
using robo::Rotation;
using robo::SpatialVec;
using robo::SymMat33;
using robo::Transform;
using robo::UnitVec3;
using robo::Vec3;
using robo::Vec4;

// ---- tolerances (named so intent is explicit at each call site) ------------
inline constexpr Real kTight = 1e-13; // machine-precision algebra
inline constexpr Real kAlg = 1e-12;   // analytic identities
inline constexpr Real kFD = 1e-6;     // central finite difference (~sqrt(eps)*scale)
inline constexpr Real kLoose = 1e-9;  // accumulated / eigen tolerances

// ---- deterministic RNG -----------------------------------------------------
// A single fixed seed makes every run bit-reproducible. Tests that need an
// independent stream pass their own seed.
class Rng {
    public:
    explicit Rng(std::uint64_t seed = 0x9E3779B97F4A7C15ULL)
        : gen_(seed) {
    }

    auto uniform(Real lo, Real hi) -> Real {
        return std::uniform_real_distribution(lo, hi)(gen_);
    }
    auto gaussian(Real mean = 0, Real sd = 1) -> Real {
        return std::normal_distribution(mean, sd)(gen_);
    }
    auto vec3(Real lo = -2, Real hi = 2) -> Vec3 {
        return Vec3(uniform(lo, hi), uniform(lo, hi), uniform(lo, hi));
    }
    // uniform direction on S^2 (Marsaglia)
    auto unitVec3() -> Vec3 {
        Real x, y, s;
        do {
            x = uniform(-1, 1);
            y = uniform(-1, 1);
            s = x * x + y * y;
        } while (s >= Real(1) || s < Real(1e-12));
        const Real f = Real(2) * std::sqrt(Real(1) - s);
        return Vec3(x * f, y * f, Real(1) - Real(2) * s);
    }
    // uniform on SO(3): unit quaternion via Shoemake -> rotation
    auto unitQuat() -> Quat {
        const Real u1 = uniform(0, 1), u2 = uniform(0, 1), u3 = uniform(0, 1);
        const Real s1 = std::sqrt(Real(1) - u1), s2 = std::sqrt(u1);
        const Real t2 = Real(2) * M_PI * u2, t3 = Real(2) * M_PI * u3;
        Quat q(s2 * std::cos(t3), s1 * std::sin(t2), s1 * std::cos(t2), s2 * std::sin(t3));
        q.normalize();
        return q;
    }
    auto rotation() -> Rotation {
        return Rotation::fromQuaternion(unitQuat());
    }

    // random SPD nxn (row-major) with eigenvalues in [lo,hi]; A = Q diag Q^T.
    void spd(int n, Real* out, Real lo = 0.3, Real hi = 5.0) {
        std::array Q{};
        // random orthonormal Q via Gram-Schmidt on a Gaussian matrix
        for (int i = 0; i < n * n; ++i) {
            Q[i] = gaussian();
        }
        for (int c = 0; c < n; ++c) {
            for (int p = 0; p < c; ++p) {
                Real d = 0;
                for (int r = 0; r < n; ++r) {
                    d += Q[r * n + c] * Q[r * n + p];
                }
                for (int r = 0; r < n; ++r) {
                    Q[r * n + c] -= d * Q[r * n + p];
                }
            }
            Real nrm = 0;
            for (int r = 0; r < n; ++r) {
                nrm += Q[r * n + c] * Q[r * n + c];
            }
            nrm = std::sqrt(nrm);
            for (int r = 0; r < n; ++r) {
                Q[r * n + c] /= nrm;
            }
        }
        std::array lam{};
        for (int k = 0; k < n; ++k) {
            lam[k] = uniform(lo, hi);
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                Real acc = 0;
                for (int k = 0; k < n; ++k) {
                    acc += Q[i * n + k] * lam[k] * Q[j * n + k];
                }
                out[i * n + j] = acc;
            }
        }
    }

    private:
    std::mt19937_64 gen_;
};

// ---- small vector ops not on the value types ------------------------------
inline auto cross(const Vec3& a, const Vec3& b) -> Vec3 {
    return a % b;
}
inline auto vnorm(const Vec3& v) -> Real {
    return v.norm();
}

// ---- comparators -----------------------------------------------------------
inline ::testing::AssertionResult NearVec3(const Vec3& a, const Vec3& b, Real tol) {
    const Real d = (a - b).norm();
    if (d <= tol) {
        return ::testing::AssertionSuccess();
    }
    return ::testing::AssertionFailure()
           << "Vec3 differ by " << d << " (tol " << tol << "): a=(" << a[0] << "," << a[1] << "," << a[2]
           << ") b=(" << b[0] << "," << b[1] << "," << b[2] << ")";
}

inline ::testing::AssertionResult NearMat33(const Mat33& a, const Mat33& b, Real tol) {
    Real d = 0;
    for (int i = 0; i < 9; ++i) {
        const Real e = a.elems[static_cast(i)] - b.elems[static_cast(i)];
        d = std::max(d, std::abs(e));
    }
    if (d <= tol) {
        return ::testing::AssertionSuccess();
    }
    return ::testing::AssertionFailure() << "Mat33 max elem diff " << d << " (tol " << tol << ")";
}

// double-cover aware quaternion distance: min(|q-q'|, |q+q'|)
inline auto quatDist(const Quat& a, const Quat& b) -> Real {
    Real dp = 0, dm = 0;
    for (int i = 0; i < 4; ++i) {
        dp += (a.elems[static_cast(i)] - b.elems[static_cast(i)])
              * (a.elems[static_cast(i)] - b.elems[static_cast(i)]);
        dm += (a.elems[static_cast(i)] + b.elems[static_cast(i)])
              * (a.elems[static_cast(i)] + b.elems[static_cast(i)]);
    }
    return std::sqrt(std::min(dp, dm));
}

inline auto quatDist(const Vec4& a, const Vec4& b) -> Real {
    return quatDist(Quat(a[0], a[1], a[2], a[3]), Quat(b[0], b[1], b[2], b[3]));
}

// Frobenius diff of two row-major nxn
inline auto matDiff(const Real* a, const Real* b, int n) -> Real {
    Real d = 0;
    for (int i = 0; i < n * n; ++i) {
        d = std::max(d, std::abs(a[i] - b[i]));
    }
    return d;
}

// dense matrix * vector / matrix (row-major)
inline void matVec(const Real* A, const Real* x, int n, Real* y) {
    for (int i = 0; i < n; ++i) {
        Real s = 0;
        for (int j = 0; j < n; ++j) {
            s += A[i * n + j] * x[j];
        }
        y[i] = s;
    }
}
inline void matMat(const Real* A, const Real* B, int n, Real* C) {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real s = 0;
            for (int k = 0; k < n; ++k) {
                s += A[i * n + k] * B[k * n + j];
            }
            C[i * n + j] = s;
        }
    }
}

inline void identity(int n, Real* I) {
    for (int i = 0; i < n * n; ++i) {
        I[i] = 0;
    }
    for (int i = 0; i < n; ++i) {
        I[i * n + i] = 1;
    }
}

// ---- finite difference of a Vec3-valued function of a scalar --------------
template 
inline auto fdVec3(F f, Real t, Real h = 1e-6) -> Vec3 {
    const Vec3 fp = f(t + h);
    const Vec3 fm = f(t - h);
    return (fp - fm) * (Real(1) / (Real(2) * h));
}

} // namespace rtest

// ============================================================================
//  test_inertia.cpp -- Part 1.7: Inertia, MassProperties, reexpress, scaling
// ============================================================================
#include "TestHelpers.hpp"
#include "robot_math.hpp"

using namespace rtest;
using robo::ArticulatedInertia;
using robo::Inertia;
using robo::MassProperties;
using robo::Mat33;
using robo::Rotation;
using robo::SpatialInertia;
using robo::SymMat33;
using robo::UnitInertia;
using robo::Vec3;

// --- point-mass inertia: I = m(|p|^2 I3 - p p^T) ----------------------------
TEST(InertiaTest, PointMassFormula) {
    Rng rng(1);
    for (int t = 0; t < 200; ++t) {
        const Vec3 p = rng.vec3(-2, 2);
        const Real m = rng.uniform(0.5, 5);
        const SymMat33 I = Inertia(p, m).asSymMat33();
        EXPECT_NEAR(I.elems[0], m * (p[1] * p[1] + p[2] * p[2]), kTight); // xx
        EXPECT_NEAR(I.elems[1], -m * p[0] * p[1], kTight);                // xy
        EXPECT_NEAR(I.elems[2], m * (p[0] * p[0] + p[2] * p[2]), kTight); // yy
        EXPECT_NEAR(I.elems[3], -m * p[0] * p[2], kTight);                // xz
        EXPECT_NEAR(I.elems[4], -m * p[1] * p[2], kTight);                // yz
        EXPECT_NEAR(I.elems[5], m * (p[0] * p[0] + p[1] * p[1]), kTight); // zz
    }
}

// --- additivity of point-mass inertias --------------------------------------
TEST(InertiaTest, Additive) {
    const Vec3 p1(1, 0, 0), p2(0, 1, 0);
    const Real m1 = 2, m2 = 3;
    Inertia sum = Inertia(p1, m1);
    sum += Inertia(p2, m2);
    const SymMat33 a = sum.asSymMat33();
    const SymMat33 b = (Inertia(p1, m1) + Inertia(p2, m2)).asSymMat33();
    for (int i = 0; i < 6; ++i) {
        EXPECT_NEAR(a.elems[static_cast(i)], b.elems[static_cast(i)], kTight);
    }
}

// --- reexpress is a similarity transform R^T I R ----------------------------
TEST(InertiaTest, ReexpressSimilarity) {
    Rng rng(2);
    for (int t = 0; t < 200; ++t) {
        const SymMat33 I(rng.uniform(1, 4),
                         rng.uniform(-0.3, 0.3),
                         rng.uniform(1, 4),
                         rng.uniform(-0.3, 0.3),
                         rng.uniform(-0.3, 0.3),
                         rng.uniform(1, 4));
        const Rotation R = rng.rotation();
        const SymMat33 Ir = I.reexpress(R);
        const Mat33 ref = R.transpose() * I.full() * R;
        EXPECT_TRUE(NearMat33(Ir.full(), ref, kAlg));
        // trace invariant
        EXPECT_NEAR(Ir.full()(0, 0) + Ir.full()(1, 1) + Ir.full()(2, 2),
                    I.full()(0, 0) + I.full()(1, 1) + I.full()(2, 2),
                    kAlg);
        // round-trip reexpress(R) then reexpress(R^T) == I
        const SymMat33 back = Ir.reexpress(Rotation(R.transpose()));
        for (int i = 0; i < 6; ++i) {
            EXPECT_NEAR(back.elems[static_cast(i)], I.elems[static_cast(i)], kAlg);
        }
    }
}

// --- MassProperties::reexpress: com' = R^T com ------------------------------
TEST(InertiaTest, MassPropertiesReexpress) {
    Rng rng(3);
    for (int t = 0; t < 100; ++t) {
        const Real m = rng.uniform(0.5, 4);
        const Vec3 com = rng.vec3(-1, 1);
        const UnitInertia G(2, 0, 2, 0, 0, 2);
        const MassProperties mp(m, com, G);
        const Rotation R = rng.rotation();
        const MassProperties mpr = mp.reexpress(R);
        EXPECT_TRUE(NearVec3(mpr.com, R.transpose() * com, kAlg));
        EXPECT_NEAR(mpr.mass, m, kTight); // mass invariant
    }
}

// --- mass scaling: ArticulatedInertia blocks scale linearly in mass ---------
TEST(InertiaTest, MassScalingLinear) {
    Rng rng(4);
    const Vec3 com(0.1, -0.2, 0.3);
    const UnitInertia G(2, 0.1, 3, 0.1, 0.1, 4);
    const Real m = 1.7, s = 3.5;
    const ArticulatedInertia P(SpatialInertia(m, com, G));
    const ArticulatedInertia Ps(SpatialInertia(s * m, com, G));
    for (int t = 0; t < 50; ++t) {
        const SpatialVec v(rng.vec3(), rng.vec3());
        const SpatialVec a = Ps * v;
        const SpatialVec b = (P * v) * s; // scaling mass scales the operator
        EXPECT_TRUE(NearVec3(a[0], b[0], kAlg));
        EXPECT_TRUE(NearVec3(a[1], b[1], kAlg));
    }
}

// --- zero-mass guard (virtual sites): unit inertia is zero, no divide-by-0 --
TEST(InertiaTest, ZeroMassGuard) {
    const MassProperties mp(0.0, Vec3(1, 2, 3), Inertia(5.0));
    for (int i = 0; i < 6; ++i) {
        EXPECT_NEAR(mp.unitInertia.elems[static_cast(i)], 0.0, kTight);
    }
    EXPECT_NEAR(mp.mass, 0.0, kTight);
}

// ============================================================================
//  TestIntegratorSmoke.cpp -- Phase 1 keystone proof: drive the REAL, now-
//  templated RobotEngine::verletStep with the OpenMM-free AnalyticForceBridge.
//
//  This is the payoff of templating the integrator: the production velocity-
//  Verlet step runs end-to-end against an analytic potential, no OpenMM, no
//  faking. It is a smoke test (full energy-drift / reversibility goldens are
//  Phase 5); here we assert the step instantiates, runs, returns success, keeps
//  the state finite, and -- since AnalyticForceBridge is a genuine conservative
//  harmonic system integrated by a symplectic step -- that total energy KE+U
//  does not drift more than a few percent over a short trajectory at small h.
// ============================================================================
#include 
#include 
#include 
#include 
#include 

#include "AnalyticForceBridge.hpp"
#include "Constraints.hpp"
#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotIntegrator.hpp" // the templated verletStep/stepTo/checkReversibility
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::attachAtoms;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

RobotModel chain(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.8, 1.6);
        s.com_B = rng.vec3(-0.1, 0.1);
        s.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
        return s;
    };
    RobotModel m = buildForest({mk(0, JointType::Free), mk(1, JointType::Torsion)});
    attachAtoms(m, 1, {Vec3(0.0, 0.0, 0.0), Vec3(0.10, 0.02, -0.03)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.05, 0.11, 0.0), Vec3(-0.03, 0.0, 0.06)}, {14.0, 1.0});
    return m;
}

// Seed the derivative chain so the first verletStep has valid qdot0/udot0/qdd0.
void seedDerivatives(const RobotModel& m, RobotState& s, AnalyticForceBridge& bridge) {
    RobotEngine::realizePosition(m, s);
    RobotEngine::fillAtomPositionsFromBodies(m, s);
    bridge.evaluate(s);
    RobotEngine::realizeVelocity(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
    RobotEngine::calcUDot(m, s);
    RobotEngine::calcQDot(m, s, s.qdot());
    RobotEngine::calcQDotDot(m, s);
}

// ---------------------------------------------------------------------------
//  Phase 5 fixtures: a single Free body, and a Free-rooted 3-body chain. Both
//  carry real atoms so the harmonic AnalyticForceBridge has something to pull on.
// ---------------------------------------------------------------------------
RobotModel singleFree(Rng& rng) {
    BodySpec s;
    s.parent = 0;
    s.joint = JointType::Free;
    s.X_PF = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
    s.X_BM = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
    s.mass = rng.uniform(0.8, 1.6);
    s.com_B = rng.vec3(-0.1, 0.1);
    s.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
    RobotModel m = buildForest({s});
    attachAtoms(m, 1, {Vec3(0, 0, 0), Vec3(0.10, 0.02, -0.03), Vec3(-0.04, 0.07, 0.0)}, {12.0, 1.0, 1.0});
    return m;
}

RobotModel chain3(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
        s.X_BM = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
        s.mass = rng.uniform(0.8, 1.6);
        s.com_B = rng.vec3(-0.1, 0.1);
        s.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
        return s;
    };
    RobotModel m =
        buildForest({mk(0, JointType::Free), mk(1, JointType::Torsion), mk(2, JointType::Torsion)});
    attachAtoms(m, 1, {Vec3(0, 0, 0), Vec3(0.10, 0.02, -0.03)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.05, 0.11, 0), Vec3(-0.03, 0, 0.06)}, {14.0, 1.0});
    attachAtoms(m, 3, {Vec3(0, 0.08, -0.04), Vec3(0.04, 0, 0.05)}, {16.0, 1.0});
    return m;
}

// A Free root with a Ball child: two quaternion bodies, for the |q|=1 test.
RobotModel freeBall(Rng& rng) {
    auto mk = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
        s.X_BM = Transform(rng.rotation(), rng.vec3(-0.2, 0.2));
        s.mass = rng.uniform(0.8, 1.6);
        s.com_B = rng.vec3(-0.1, 0.1);
        s.inertia_B = UnitInertia(rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6), rng.uniform(0.4, 0.6));
        return s;
    };
    RobotModel m = buildForest({mk(0, JointType::Free), mk(1, JointType::Ball)});
    attachAtoms(m, 1, {Vec3(0, 0, 0), Vec3(0.10, 0.02, -0.03)}, {12.0, 1.0});
    attachAtoms(m, 2, {Vec3(0.05, 0.11, 0), Vec3(-0.03, 0, 0.06)}, {14.0, 1.0});
    return m;
}

// thermal scale for the momentum draw (arbitrary positive constant; only sets
// the energy scale, not correctness).
constexpr Real kBoostRT = Real(2.5);

// Build a ready-to-integrate state: anchors captured at a first random pose, then
// the body is displaced to a SECOND random pose (so U != 0), and u is seeded the
// production way -- u = sqrt(RT) * sqrt(M^-1) * gaussian (multiplyBySqrtMInv).
// Returns the bridge by value-construction into `bridgeStore`. After this the
// derivative chain is seeded and the first verletStep is valid.
void buildSeeded(const RobotModel& m,
                 RobotState& s,
                 Rng& rng,
                 Real k,
                 std::vector& bridgeStore) {
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);
    bridgeStore.emplace_back(m, s, k); // anchors = this pose
    AnalyticForceBridge& bridge = bridgeStore.back();

    randomizeState(m, s, rng); // displace off the anchors
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);

    std::vector w(static_cast(m.nu)), u(static_cast(m.nu));
    for (int i = 0; i < m.nu; ++i) {
        w[static_cast(i)] = rng.gaussian();
    }
    RobotEngine::multiplyBySqrtMInv(m, s, w.data(), u.data());
    for (int i = 0; i < m.nu; ++i) {
        s.u()[i] = std::sqrt(kBoostRT) * u[static_cast(i)];
    }

    seedDerivatives(m, s, bridge);
}

// least-squares slope of y vs index 0..n-1 (for the monotone-drift check).
Real lsSlope(const std::vector& y) {
    const Real n = static_cast(y.size());
    Real sx = 0, sy = 0, sxx = 0, sxy = 0;
    for (std::size_t i = 0; i < y.size(); ++i) {
        const Real x = static_cast(i);
        sx += x;
        sy += y[i];
        sxx += x * x;
        sxy += x * y[i];
    }
    return (n * sxy - sx * sy) / (n * sxx - sx * sx);
}

// max |E_t - E_0| / |E_0| and the linear-fit total drift slope*N/|E_0| over a
// trajectory; returns false if any step is rejected.
struct DriftResult {
    bool ok = true;
    Real maxRel = 0;
    Real slopeTotal = 0;
    Real maxAbs = 0;
};
DriftResult runTrajectory(const RobotModel& m,
                          RobotState& s,
                          AnalyticForceBridge& bridge,
                          const ConstraintSet& cset,
                          Real h,
                          int nSteps) {
    DriftResult r;
    const Real E0 = RobotEngine::calcKineticEnergy(m, s) + bridge.calcPotentialEnergy(s);
    std::vector energies;
    energies.reserve(static_cast(nSteps));
    for (int n = 0; n < nSteps; ++n) {
        if (!RobotEngine::verletStep(m, s, bridge, cset, h)) {
            r.ok = false;
            return r;
        }
        const Real E = RobotEngine::calcKineticEnergy(m, s) + bridge.calcPotentialEnergy(s);
        energies.push_back(E);
        r.maxRel = std::max(r.maxRel, std::abs(E - E0) / (std::abs(E0) + Real(1e-12)));
        r.maxAbs = std::max(r.maxAbs, std::abs(E - E0));
    }
    r.slopeTotal = std::abs(lsSlope(energies)) * static_cast(nSteps) / (std::abs(E0) + Real(1e-12));
    return r;
}

// ---- Phase 5 tolerances ----
constexpr Real kEdrift = Real(1e-4);   // relative energy drift at the safe step
constexpr Real kRevTight = Real(1e-7); // round-trip reversibility residual at safe h
constexpr Real kSafeH = Real(5e-4);    // a step well inside the reversible regime

} // namespace

// ---------------------------------------------------------------------------
//  The templated verletStep instantiates with a non-ForceBridge type, runs, and
//  returns success on a benign step.
// ---------------------------------------------------------------------------
TEST(IntegratorSmoke, VerletStepRunsWithAnalyticBridge) {
    Rng rng(0x5709);
    RobotModel m = chain(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    AnalyticForceBridge bridge(m, s, /*k=*/120.0);
    const ConstraintSet cset; // empty -> unconstrained

    // small displacement + gentle velocities so the step is benign
    randomizeState(m, s, rng);
    Real* u = s.u();
    for (int i = 0; i < m.nu; ++i) {
        u[i] *= 0.05;
    }
    seedDerivatives(m, s, bridge);

    const bool ok = RobotEngine::verletStep(m, s, bridge, cset, /*h=*/1e-3);
    EXPECT_TRUE(ok) << "templated verletStep rejected a benign step";
    for (int i = 0; i < m.nq; ++i) {
        EXPECT_TRUE(std::isfinite(s.q()[i]));
    }
    for (int i = 0; i < m.nu; ++i) {
        EXPECT_TRUE(std::isfinite(s.u()[i]));
    }
}

// ---------------------------------------------------------------------------
//  stepTo (also templated) drives a short trajectory; total energy KE+U stays
//  bounded (symplectic Verlet on a smooth harmonic potential).
// ---------------------------------------------------------------------------
TEST(IntegratorSmoke, EnergyBoundedOverShortTrajectory) {
    Rng rng(0x570A);
    RobotModel m = chain(rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    AnalyticForceBridge bridge(m, s, 120.0);
    const ConstraintSet cset;

    // displace off the anchors and give a modest velocity
    randomizeState(m, s, rng);
    Real* u = s.u();
    for (int i = 0; i < m.nu; ++i) {
        u[i] *= 0.1;
    }
    seedDerivatives(m, s, bridge);

    const Real h = 5e-4;
    const Real E0 = RobotEngine::calcKineticEnergy(m, s) + bridge.calcPotentialEnergy(s);

    Real maxRelDrift = 0;
    int steps = 0;
    for (int n = 0; n < 200; ++n) {
        const bool ok = RobotEngine::verletStep(m, s, bridge, cset, h);
        ASSERT_TRUE(ok) << "step " << n << " was rejected";
        ++steps;
        const Real E = RobotEngine::calcKineticEnergy(m, s) + bridge.calcPotentialEnergy(s);
        maxRelDrift = std::max(maxRelDrift, std::abs(E - E0) / (std::abs(E0) + Real(1e-12)));
    }
    EXPECT_EQ(steps, 200);
    // symplectic Verlet on a smooth potential: bounded, small drift (not secular
    // growth). Loose bound -- this is a smoke test, not the Phase 5 energy golden.
    EXPECT_LT(maxRelDrift, 0.05) << "energy drifted " << maxRelDrift << " over 200 steps";
}

// ===========================================================================
//  Phase 5 -- verlet / reversibility / stepTo goldens. Production momentum draw
//  (multiplyBySqrtMInv of a Gaussian), no constraints (empty ConstraintSet).
// ===========================================================================

// ---------------------------------------------------------------------------
//  P5.1: total energy KE+U stays bounded with NO secular (monotone) drift over a
//        long trajectory at a safe step, for both the single Free body and the
//        3-chain. FAIL sensitivity: at 10x the step, the drift blows past kEdrift.
// ---------------------------------------------------------------------------
TEST(Integrator, EnergyConservationBounded) {
    const ConstraintSet cset; // unconstrained

    struct Case {
        const char* name;
        RobotModel (*build)(Rng&);
        unsigned seed;
    };
    const Case cases[] = {
        {"Free", &singleFree, 0x5101},
        {"Chain3", &chain3, 0x5102},
    };

    for (const Case& c : cases) {
        Rng rng(c.seed);
        RobotModel m = c.build(rng);

        // safe step: bounded, non-secular drift.
        {
            RobotState s;
            s.allocateFull(m);
            std::vector store;
            store.reserve(1);
            Rng r(c.seed ^ 0xABCDu);
            buildSeeded(m, s, r, /*k=*/60.0, store);
            const DriftResult d = runTrajectory(m, s, store.back(), cset, kSafeH, 2000);
            ASSERT_TRUE(d.ok) << c.name << ": a safe-step trajectory was rejected";
            EXPECT_LT(d.maxRel, kEdrift) << c.name << ": energy drift " << d.maxRel;
            EXPECT_LT(d.slopeTotal, kEdrift)
                << c.name << ": secular (monotone) drift slope*N/|E0| = " << d.slopeTotal;
        }

        // FAIL sensitivity: 10x the step must drive the drift past kEdrift, proving
        // the test can actually SEE a bad step (it is not vacuously loose).
        {
            RobotState s;
            s.allocateFull(m);
            std::vector store;
            store.reserve(1);
            Rng r(c.seed ^ 0xABCDu); // SAME start as the safe run
            buildSeeded(m, s, r, 60.0, store);
            const DriftResult d = runTrajectory(m, s, store.back(), cset, 10 * kSafeH, 2000);
            // either it was rejected (also a clear "bad step" signal) or the drift
            // exceeded the budget.
            const bool sawBadStep = (!d.ok) || (d.maxRel > kEdrift);
            EXPECT_TRUE(sawBadStep) << c.name << ": 10x step stayed under kEdrift (maxRel=" << d.maxRel
                                    << ", ok=" << d.ok << ") -- test is insensitive";
        }
    }
}

// ---------------------------------------------------------------------------
//  P5.2: velocity-Verlet is globally second order -- the energy drift at h is
//        ~4x the drift at h/2 over the SAME physical time from the SAME start.
// ---------------------------------------------------------------------------
TEST(Integrator, SecondOrderEnergyError) {
    const ConstraintSet cset;

    struct Case {
        const char* name;
        RobotModel (*build)(Rng&);
        unsigned seed;
    };
    const Case cases[] = {
        {"Free", &singleFree, 0x5201},
        {"Chain3", &chain3, 0x5202},
    };

    for (const Case& c : cases) {
        Rng rng(c.seed);
        RobotModel m = c.build(rng);

        auto driftAt = [&](Real h, int nSteps) -> Real {
            RobotState s;
            s.allocateFull(m);
            std::vector store;
            store.reserve(1);
            Rng r(c.seed ^ 0x55AAu); // fixed seed: identical start for h and h/2
            buildSeeded(m, s, r, 60.0, store);
            const DriftResult d = runTrajectory(m, s, store.back(), cset, h, nSteps);
            return d.ok ? d.maxAbs : std::numeric_limits::infinity();
        };

        // same physical time: 600 steps at h, 1200 at h/2.
        const Real driftH = driftAt(kSafeH, 600);
        const Real driftHalf = driftAt(kSafeH / 2, 1200);
        ASSERT_GT(driftHalf, 0.0) << c.name;
        const Real ratio = driftH / driftHalf;
        EXPECT_GE(ratio, 3.0) << c.name << ": O(h^2) ratio too small (" << ratio << ")";
        EXPECT_LE(ratio, 5.0) << c.name << ": O(h^2) ratio too large (" << ratio << ")";
    }
}

// ---------------------------------------------------------------------------
//  P5.3: the engine's own checkReversibility (which no other test invokes) gives
//        a tiny round-trip residual at a safe h. FAIL sensitivity: at a large h
//        the residual is O(1) -- documenting the header's configuration-dependent
//        safe-h claim. (Uses the 3-chain: a single Free body's exp-map advance is
//        reversible even at large h, so the chain is what exposes the breakdown.)
// ---------------------------------------------------------------------------
TEST(Integrator, TimeReversibilityResidualSmall) {
    const ConstraintSet cset;

    Rng rng(0x5301);
    RobotModel m = chain3(rng);
    RobotState s;
    s.allocateFull(m);
    std::vector store;
    store.reserve(1);
    Rng r(0x5311);
    buildSeeded(m, s, r, 60.0, store);

    // checkReversibility is non-destructive, so both calls run from the same state.
    const Real safe = RobotEngine::checkReversibility(m, s, store.back(), cset, /*nSteps=*/200, kSafeH);
    EXPECT_LT(safe, kRevTight) << "reversible step gave residual " << safe;

    const Real big = RobotEngine::checkReversibility(m, s, store.back(), cset, 200, /*h=*/5e-2);
    EXPECT_GT(big, 0.1) << "large-h residual " << big << " is not O(1) -- safe-h claim not exercised";
}

// ---------------------------------------------------------------------------
//  P5.4: every quaternion q-block of every Free/Ball body stays unit-norm over a
//        long trajectory. The exp-map advance preserves |q|=1 by construction;
//        this guards against a regression to linear-Taylor-without-renormalize.
// ---------------------------------------------------------------------------
TEST(Integrator, QuaternionStaysUnitOverTrajectory) {
    const ConstraintSet cset;

    Rng rng(0x5401);
    RobotModel m = freeBall(rng); // a Free body and a Ball body
    RobotState s;
    s.allocateFull(m);
    std::vector store;
    store.reserve(1);
    Rng r(0x5411);
    buildSeeded(m, s, r, 60.0, store);
    AnalyticForceBridge& bridge = store.back();

    bool anyQuat = false;
    for (int b = 1; b < m.numBodies; ++b) {
        anyQuat = anyQuat || m.isQuaternionBody(b);
    }
    ASSERT_TRUE(anyQuat) << "fixture has no quaternion body -- test is vacuous";

    for (int n = 0; n < 1500; ++n) {
        ASSERT_TRUE(RobotEngine::verletStep(m, s, bridge, cset, kSafeH)) << "step " << n << " rejected";
        for (int b = 1; b < m.numBodies; ++b) {
            if (!m.isQuaternionBody(b)) {
                continue;
            }
            const int q = m.bodyQIndex[b];
            const Real norm = std::sqrt(s.q()[q] * s.q()[q] + s.q()[q + 1] * s.q()[q + 1]
                                        + s.q()[q + 2] * s.q()[q + 2] + s.q()[q + 3] * s.q()[q + 3]);
            ASSERT_NEAR(norm, 1.0, rtest::kTight)
                << "body " << b << " quaternion lost unit norm at step " << n;
        }
    }
}

// ---------------------------------------------------------------------------
//  P5.5: stepTo is deterministic -- two identical states advanced over the same
//        schedule produce BITWISE-identical q,u (mirrors Stability.Deterministic-
//        Generators). Steps are genuinely taken (asserted), not rejected no-ops.
// ---------------------------------------------------------------------------
TEST(Integrator, StepToReachesEndTimeDeterministically) {
    const ConstraintSet cset;

    Rng rng(0x5501);
    RobotModel m = chain3(rng);
    RobotState s1;
    s1.allocateFull(m);
    std::vector store;
    store.reserve(1);
    Rng r(0x5511);
    buildSeeded(m, s1, r, 60.0, store);
    AnalyticForceBridge& bridge = store.back();

    // exact clone of the seeded state
    RobotState s2;
    s2.allocateFull(m);
    std::copy(s1.q(), s1.q() + m.nq, s2.q());
    std::copy(s1.u(), s1.u() + m.nu, s2.u());
    std::copy(s1.qdot(), s1.qdot() + m.nq, s2.qdot());
    std::copy(s1.udot(), s1.udot() + m.nu, s2.udot());
    std::copy(s1.qdotdot(), s1.qdotdot() + m.nq, s2.qdotdot());
    s2.time = s1.time;

    int taken1 = 0, taken2 = 0;
    for (int n = 0; n < 200; ++n) {
        if (RobotEngine::stepTo(m, s1, bridge, cset, s1.time + kSafeH)) {
            ++taken1;
        }
    }
    for (int n = 0; n < 200; ++n) {
        if (RobotEngine::stepTo(m, s2, bridge, cset, s2.time + kSafeH)) {
            ++taken2;
        }
    }
    ASSERT_EQ(taken1, 200) << "stepTo rejected steps -- determinism test would be vacuous";
    ASSERT_EQ(taken2, 200);

    for (int i = 0; i < m.nq; ++i) {
        EXPECT_EQ(s1.q()[i], s2.q()[i]) << "q[" << i << "] diverged -- stepTo not deterministic";
    }
    for (int i = 0; i < m.nu; ++i) {
        EXPECT_EQ(s1.u()[i], s2.u()[i]) << "u[" << i << "] diverged -- stepTo not deterministic";
    }
}

// A test-only bridge that injects a non-finite body force, to drive the
// reject-and-restore path of verletStep without OpenMM. Same evaluate() contract.
struct InfForceBridge {
    const RobotModel& model;
    explicit InfForceBridge(const RobotModel& m)
        : model(m) {
    }
    void evaluate(RobotState& s) {
        SpatialVec* BF = s.bodyForceG();
        for (int b = 0; b < model.numBodies; ++b) {
            BF[b] = SpatialVec(Vec3(0), Vec3(0));
        }
        Real* mob = s.mobilityForce();
        for (int i = 0; i < model.nu; ++i) {
            mob[i] = 0;
        }
        BF[1].linear[0] = std::numeric_limits::infinity(); // poison one body force
    }
};

// ---------------------------------------------------------------------------
//  P5.6: a bad step (non-finite force, OR an absurdly large h) makes verletStep
//        return false AND leave q,u EXACTLY equal to the pre-step snapshot. The
//        restorePreStep contract: the caller must never be handed a NaN to reject.
// ---------------------------------------------------------------------------
TEST(Integrator, BadStepReturnsFalseAndRestores) {
    const ConstraintSet cset;

    // ---- (a) non-finite force ----
    {
        Rng rng(0x5601);
        RobotModel m = chain3(rng);
        RobotState s;
        s.allocateFull(m);
        std::vector store;
        store.reserve(1);
        Rng r(0x5611);
        buildSeeded(m, s, r, 60.0, store); // valid derivative seed via the finite bridge

        std::vector q0(s.q(), s.q() + m.nq), u0(s.u(), s.u() + m.nu);
        InfForceBridge bad(m);
        const bool ok = RobotEngine::verletStep(m, s, bad, cset, kSafeH);
        EXPECT_FALSE(ok) << "verletStep accepted a step with a non-finite force";
        for (int i = 0; i < m.nq; ++i) {
            EXPECT_EQ(s.q()[i], q0[static_cast(i)])
                << "q[" << i << "] not restored after bad step";
        }
        for (int i = 0; i < m.nu; ++i) {
            EXPECT_EQ(s.u()[i], u0[static_cast(i)])
                << "u[" << i << "] not restored after bad step";
        }
    }

    // ---- (b) absurd step size (CFL runaway -> velocitiesSane fails) ----
    {
        Rng rng(0x5602);
        RobotModel m = chain3(rng);
        RobotState s;
        s.allocateFull(m);
        std::vector store;
        store.reserve(1);
        Rng r(0x5612);
        buildSeeded(m, s, r, 60.0, store);

        std::vector q0(s.q(), s.q() + m.nq), u0(s.u(), s.u() + m.nu);
        const bool ok = RobotEngine::verletStep(m, s, store.back(), cset, /*h=*/5.0);
        EXPECT_FALSE(ok) << "verletStep accepted an absurd-h runaway";
        for (int i = 0; i < m.nq; ++i) {
            EXPECT_EQ(s.q()[i], q0[static_cast(i)])
                << "q[" << i << "] not restored after runaway";
        }
        for (int i = 0; i < m.nu; ++i) {
            EXPECT_EQ(s.u()[i], u0[static_cast(i)])
                << "u[" << i << "] not restored after runaway";
        }
    }
}

// ============================================================================
//  TestJointKernels.cpp -- the per-mobilizer PRIMITIVES. These are the
//  Robosample analogue of Simbody's per-RigidBodyNodeSpec checks: for each
//  JointType we verify the q/u sizing, the cross-mobilizer transform X_FM(q),
//  and -- the load-bearing one -- that X_FM, the velocity Jacobian H_FM, and the
//  q-dot (N) map are mutually consistent, by finite-differencing X_FM along a
//  trajectory generated by the q-dot map and comparing the resulting spatial
//  velocity to H_FM*u. The same idea finite-differences H_FM itself against
//  HDot_FM. This is exactly the consistency Simbody's framework guarantees
//  implicitly, here pinned down directly on the bare kernels (no engine, no
//  forcefield) -- and it certifies the BendStretch / SphericalCoords / FreeLine
//  HDot terms that previously carried only a "needs golden test" comment.
// ============================================================================
#include 
#include 

#include "JointKernels.hpp"
#include "RobotModel.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::Rng;

namespace {

constexpr std::array kAllJoints = {
    JointType::Rigid,       JointType::Torsion,      JointType::Slider,   JointType::Cylinder,
    JointType::BendStretch, JointType::Cartesian,    JointType::Ball,     JointType::SphericalCoords,
    JointType::FreeLine,    JointType::Free};

const char* name(JointType jt) {
    switch (jt) {
        case JointType::Rigid: return "Rigid";
        case JointType::Torsion: return "Torsion";
        case JointType::Slider: return "Slider";
        case JointType::Cylinder: return "Cylinder";
        case JointType::BendStretch: return "BendStretch";
        case JointType::Cartesian: return "Cartesian";
        case JointType::Ball: return "Ball";
        case JointType::SphericalCoords: return "SphericalCoords";
        case JointType::FreeLine: return "FreeLine";
        case JointType::Free: return "Free";
    }
    return "?";
}

// angular velocity in F from a central difference of the rotation:
// dR_FM/dt = [w_FM]x R_FM  =>  [w]x = Rdot R^T  (w expressed in F).
Vec3 angVelFromRotationFD(const Rotation& Rp, const Rotation& Rm, Real h) {
    const Mat33 Rdot = (Rp - Rm) * (Real(1) / (Real(2) * h));
    const Mat33 W = Rdot * Rp.transpose();
    const Mat33 W2 = Rdot * Rm.transpose(); // average reduces the O(h^2) bias
    return Vec3(Real(0.5) * (W(2, 1) + W2(2, 1)),
                Real(0.5) * (W(0, 2) + W2(0, 2)),
                Real(0.5) * (W(1, 0) + W2(1, 0)));
}

// The joint's q-dot map qdot = N(q) u (same N the engine's calcQDot uses), so we
// can evolve q(t) = q0 + t*qdot0 for the finite difference.
void jointQDot(JointType jt, const Real* q, const Real* u, Real* qdot) {
    if (jt == JointType::Ball) {
        const Vec4 quat(q[0], q[1], q[2], q[3]);
        const Vec4 qd = Rotation::convertAngVelToQuaternionDot(quat, Vec3(u[0], u[1], u[2]));
        for (int k = 0; k < 4; ++k) qdot[k] = qd[k];
        return;
    }
    if (jt == JointType::Free) {
        const Vec4 quat(q[0], q[1], q[2], q[3]);
        const Vec4 qd = Rotation::convertAngVelToQuaternionDot(quat, Vec3(u[0], u[1], u[2]));
        for (int k = 0; k < 4; ++k) qdot[k] = qd[k];
        qdot[4] = u[3]; qdot[5] = u[4]; qdot[6] = u[5];
        return;
    }
    if (jt == JointType::FreeLine) {
        const Vec4 quat(q[0], q[1], q[2], q[3]);
        const Rotation R = jointX_FM(jt, q, 0).R();
        const Vec3 wF = R * Vec3(u[0], u[1], 0);
        const Vec4 qd = Rotation::convertAngVelToQuaternionDot(quat, wF);
        for (int k = 0; k < 4; ++k) qdot[k] = qd[k];
        qdot[4] = u[2]; qdot[5] = u[3]; qdot[6] = u[4];
        return;
    }
    const int nu = RobotModel::jointNU(jt);
    for (int j = 0; j < nu; ++j) qdot[j] = u[j]; // QDotIsAlwaysTheSameAsU
}

// q(t) = q0 + t*qdot0, renormalizing any quaternion block.
std::array evolveQ(JointType jt, const Real* q0, const Real* qdot0, Real t) {
    std::array q{};
    const int nq = RobotModel::jointNQ(jt);
    for (int i = 0; i < nq; ++i) q[i] = q0[i] + t * qdot0[i];
    if (RobotModel::jointUsesQuaternion(jt)) {
        const Real n = std::sqrt(q[0] * q[0] + q[1] * q[1] + q[2] * q[2] + q[3] * q[3]);
        for (int k = 0; k < 4; ++k) q[k] /= n;
    }
    return q;
}

std::array randomQ(JointType jt, Rng& rng) {
    std::array q{};
    const int nq = RobotModel::jointNQ(jt);
    for (int i = 0; i < nq; ++i) q[i] = rng.uniform(-1.3, 1.3);
    if (RobotModel::jointUsesQuaternion(jt)) {
        const auto quat = rng.unitQuat();
        for (int k = 0; k < 4; ++k) q[k] = quat.elems[k];
    }
    return q;
}

} // namespace

// ---------------------------------------------------------------------------
//  P1: q/u sizing and joint-fact truth tables (the single source of truth).
// ---------------------------------------------------------------------------
TEST(JointFacts, DofAndNqTable) {
    struct Row { JointType jt; int nu; int nq; bool quat; };
    const Row rows[] = {
        {JointType::Rigid, 0, 0, false},       {JointType::Torsion, 1, 1, false},
        {JointType::Slider, 1, 1, false},      {JointType::Cylinder, 2, 2, false},
        {JointType::BendStretch, 2, 2, false}, {JointType::Cartesian, 3, 3, false},
        {JointType::Ball, 3, 4, true},         {JointType::SphericalCoords, 3, 3, false},
        {JointType::FreeLine, 5, 7, true},     {JointType::Free, 6, 7, true},
    };
    for (const auto& r : rows) {
        EXPECT_EQ(RobotModel::jointNU(r.jt), r.nu) << name(r.jt);
        EXPECT_EQ(RobotModel::jointNQ(r.jt), r.nq) << name(r.jt);
        EXPECT_EQ(RobotModel::jointUsesQuaternion(r.jt), r.quat) << name(r.jt);
        // Non-quaternion joints store nq == nu. Quaternion joints inflate the
        // orientation block 3->4, so nq = nu + (#quaternion-encoded rot dofs not
        // in u): +1 for Ball/Free, +2 for FreeLine (only 2 of its 3 quaternion-
        // borne rotational dofs are mobilities).
        if (!r.quat) EXPECT_EQ(r.nq, r.nu) << name(r.jt);
        else EXPECT_GT(r.nq, r.nu) << name(r.jt);
    }
}

TEST(JointFacts, FlexibleAndLegalRoot) {
    EXPECT_FALSE(RobotModel::jointIsFlexible(JointType::Rigid));
    for (auto jt : kAllJoints)
        if (jt != JointType::Rigid) EXPECT_TRUE(RobotModel::jointIsFlexible(jt)) << name(jt);

    const JointType legal[] = {JointType::Free, JointType::Cartesian, JointType::Rigid,
                               JointType::FreeLine, JointType::Ball, JointType::Torsion};
    const JointType illegal[] = {JointType::Slider, JointType::Cylinder,
                                 JointType::BendStretch, JointType::SphericalCoords};
    for (auto jt : legal) EXPECT_TRUE(RobotModel::jointIsLegalRoot(jt)) << name(jt);
    for (auto jt : illegal) EXPECT_FALSE(RobotModel::jointIsLegalRoot(jt)) << name(jt);
}

TEST(JointFacts, ConstantHFMClassification) {
    for (auto jt : {JointType::Rigid, JointType::Torsion, JointType::Slider, JointType::Cylinder,
                    JointType::Cartesian, JointType::Ball, JointType::Free})
        EXPECT_TRUE(RobotModel::jointHasConstantHFM(jt)) << name(jt);
    for (auto jt : {JointType::BendStretch, JointType::SphericalCoords, JointType::FreeLine})
        EXPECT_FALSE(RobotModel::jointHasConstantHFM(jt)) << name(jt);
}

// ---------------------------------------------------------------------------
//  P2: analytic X_FM spot checks.
// ---------------------------------------------------------------------------
TEST(JointXFM, AnalyticSpotChecks) {
    EXPECT_TRUE(rtest::NearMat33(jointX_FM(JointType::Rigid, nullptr, 0).R(), Mat33(Real(1)), rtest::kTight));

    {
        Real q[1] = {Real(0.7)};
        const Transform X = jointX_FM(JointType::Torsion, q, 0);
        Rotation Rz; Rz.setRotationFromAngleAboutZ(Real(0.7));
        EXPECT_TRUE(rtest::NearMat33(X.R(), Rz, rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(0), rtest::kTight));
    }
    {
        Real q[1] = {Real(1.25)};
        const Transform X = jointX_FM(JointType::Slider, q, 0);
        EXPECT_TRUE(rtest::NearMat33(X.R(), Mat33(Real(1)), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(Real(1.25), 0, 0), rtest::kTight));
    }
    {
        Real q[3] = {Real(0.3), Real(-0.4), Real(0.9)};
        const Transform X = jointX_FM(JointType::Cartesian, q, 0);
        EXPECT_TRUE(rtest::NearMat33(X.R(), Mat33(Real(1)), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(Real(0.3), Real(-0.4), Real(0.9)), rtest::kTight));
    }
    {
        Real q[2] = {Real(0.5), Real(2.0)};
        const Transform X = jointX_FM(JointType::Cylinder, q, 0);
        Rotation Rz; Rz.setRotationFromAngleAboutZ(Real(0.5));
        EXPECT_TRUE(rtest::NearMat33(X.R(), Rz, rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(0, 0, Real(2.0)), rtest::kTight));
    }
    {
        Real q[7] = {1, 0, 0, 0, 0, 0, 0};
        EXPECT_TRUE(rtest::NearMat33(jointX_FM(JointType::Ball, q, 0).R(), Mat33(Real(1)), rtest::kTight));
        const Transform Xf = jointX_FM(JointType::Free, q, 0);
        EXPECT_TRUE(rtest::NearMat33(Xf.R(), Mat33(Real(1)), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(Xf.p(), Vec3(0), rtest::kTight));
    }
    {
        // SphericalCoords (Z-radial), az=ze=0 -> M origin at radius along +Z.
        Real q[3] = {0, 0, Real(1.7)};
        const Transform X = jointX_FM(JointType::SphericalCoords, q, 0);
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(0, 0, Real(1.7)), rtest::kAlg));
    }
    {
        Real q[7] = {1, 0, 0, 0, Real(0.2), Real(-0.6), Real(0.8)};
        const Transform X = jointX_FM(JointType::FreeLine, q, 0);
        EXPECT_TRUE(rtest::NearMat33(X.R(), Mat33(Real(1)), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(Real(0.2), Real(-0.6), Real(0.8)), rtest::kTight));
    }
}

// ---------------------------------------------------------------------------
//  P3: X_FM / H_FM / N(q) mutual consistency for EVERY joint.
//      V_FM := H_FM(q)*u  must equal  d/dt X_FM along q(t)=q0+t*N(q0)u.
// ---------------------------------------------------------------------------
TEST(JointJacobian, HFMisDerivativeOfXFM) {
    Rng rng(0xA11CE5);
    const Real h = 1e-6;
    for (auto jt : kAllJoints) {
        const int nu = RobotModel::jointNU(jt);
        if (nu == 0) continue; // Rigid: nothing to differentiate
        for (int trial = 0; trial < 200; ++trial) {
            const auto q0 = randomQ(jt, rng);
            std::array u{};
            for (int j = 0; j < nu; ++j) u[j] = rng.gaussian(0, Real(0.6));

            std::array qdot0{};
            jointQDot(jt, q0.data(), u.data(), qdot0.data());

            const auto qp = evolveQ(jt, q0.data(), qdot0.data(), +h);
            const auto qm = evolveQ(jt, q0.data(), qdot0.data(), -h);
            const Transform Xp = jointX_FM(jt, qp.data(), 0);
            const Transform Xm = jointX_FM(jt, qm.data(), 0);

            const Vec3 w_fd = angVelFromRotationFD(Xp.R(), Xm.R(), h);
            const Vec3 v_fd = (Xp.p() - Xm.p()) * (Real(1) / (Real(2) * h));

            const Transform X0 = jointX_FM(jt, q0.data(), 0);
            std::array H{};
            jointH_FM(jt, X0, H.data());
            Vec3 w_an(0), v_an(0);
            for (int j = 0; j < nu; ++j) {
                w_an = w_an + H[j][0] * u[j];
                v_an = v_an + H[j][1] * u[j];
            }
            ASSERT_TRUE(rtest::NearVec3(w_an, w_fd, 1e-4)) << name(jt) << " angular trial " << trial;
            ASSERT_TRUE(rtest::NearVec3(v_an, v_fd, 1e-4)) << name(jt) << " linear trial " << trial;
        }
    }
}

// ---------------------------------------------------------------------------
//  P4: HDot_FM consistency. d/dt H_FM(q(t)) (FD) must equal jointHDot_FM with
//      velocity argument V_FM = H_FM*u. Zero for the constant-H joints; nonzero
//      and correct for BendStretch / SphericalCoords / FreeLine. This is the
//      check that retires the "golden-test before trust" caveat.
// ---------------------------------------------------------------------------
TEST(JointJacobianDot, HDotMatchesDerivativeOfHFM) {
    Rng rng(0xBEEF11);
    const Real h = 1e-6;
    for (auto jt : kAllJoints) {
        const int nu = RobotModel::jointNU(jt);
        if (nu == 0) continue;
        for (int trial = 0; trial < 150; ++trial) {
            const auto q0 = randomQ(jt, rng);
            std::array u{};
            for (int j = 0; j < nu; ++j) u[j] = rng.gaussian(0, Real(0.6));
            std::array qdot0{};
            jointQDot(jt, q0.data(), u.data(), qdot0.data());

            const Transform X0 = jointX_FM(jt, q0.data(), 0);
            std::array H0{};
            jointH_FM(jt, X0, H0.data());
            Vec3 w0(0), v0(0);
            for (int j = 0; j < nu; ++j) { w0 = w0 + H0[j][0] * u[j]; v0 = v0 + H0[j][1] * u[j]; }
            const SpatialVec V_FM(w0, v0);

            std::array Hdot{};
            jointHDot_FM(jt, X0, V_FM, Hdot.data());

            const auto qp = evolveQ(jt, q0.data(), qdot0.data(), +h);
            const auto qm = evolveQ(jt, q0.data(), qdot0.data(), -h);
            std::array Hp{}, Hm{};
            jointH_FM(jt, jointX_FM(jt, qp.data(), 0), Hp.data());
            jointH_FM(jt, jointX_FM(jt, qm.data(), 0), Hm.data());

            for (int j = 0; j < nu; ++j) {
                const Vec3 dAng = (Hp[j][0] - Hm[j][0]) * (Real(1) / (Real(2) * h));
                const Vec3 dLin = (Hp[j][1] - Hm[j][1]) * (Real(1) / (Real(2) * h));
                ASSERT_TRUE(rtest::NearVec3(Hdot[j][0], dAng, 1e-4))
                    << name(jt) << " HDot ang col " << j << " trial " << trial;
                ASSERT_TRUE(rtest::NearVec3(Hdot[j][1], dLin, 1e-4))
                    << name(jt) << " HDot lin col " << j << " trial " << trial;
            }
        }
    }
}

// ---------------------------------------------------------------------------
//  P5: the Ball-quaternion regression. A Ball body is a 3-dof pure rotation
//  (q = unit quaternion, no translation) -- the exact behaviour the old engine
//  mishandled (it gave Ball nq=nu=0 and never renormalized). P1/P3 cover the
//  sizing and rate; this pins "rotation only, no translation" explicitly.
// ---------------------------------------------------------------------------
TEST(BallRegression, PureRotationNoTranslation) {
    Rng rng(0x5A11);
    for (int t = 0; t < 50; ++t) {
        const auto quat = rng.unitQuat();
        Real q[4] = {quat.elems[0], quat.elems[1], quat.elems[2], quat.elems[3]};
        const Transform X = jointX_FM(JointType::Ball, q, 0);
        // M origin coincides with F origin: no translation dof.
        EXPECT_TRUE(rtest::NearVec3(X.p(), Vec3(0), rtest::kTight));
        // X_FM.R() is a proper rotation: R R^T = I, det +1 (orthonormality check).
        const Mat33 RRt = X.R() * X.R().transpose();
        EXPECT_TRUE(rtest::NearMat33(RRt, Mat33(Real(1)), rtest::kAlg));
        // H_FM is the identity rotational triple, no linear rows.
        std::array H{};
        jointH_FM(JointType::Ball, X, H.data());
        EXPECT_TRUE(rtest::NearVec3(H[0][0], Vec3(1, 0, 0), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(H[1][0], Vec3(0, 1, 0), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(H[2][0], Vec3(0, 0, 1), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(H[0][1], Vec3(0), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(H[1][1], Vec3(0), rtest::kTight));
        EXPECT_TRUE(rtest::NearVec3(H[2][1], Vec3(0), rtest::kTight));
    }
}

// ============================================================================
//  test_linalg.cpp -- Part 1.8: jacobiSymEig, invertDense, symSqrt(Inv),
//  logDetSymPD. Exercises the REAL helpers (extracted into RobotLinearAlgebra.hpp).
//  Self-consistency + crafted singular/conditioned matrices.
// ============================================================================
#include 

#include "RobotLinearAlgebra.hpp"
#include "TestHelpers.hpp"

using namespace rtest;
namespace L = robo_linalg;

// --- jacobiSymEig: V diag(d) V^T = A and V^T V = I --------------------------
TEST(LinAlg, JacobiEigReconstructs) {
    Rng rng(1);
    for (int n : {1, 3, 6}) {
        for (int t = 0; t < 100; ++t) {
            Real A[36];
            rng.spd(n, A, 0.3, 5.0);
            Real d[6], V[36];
            L::jacobiSymEig(A, n, d, V);
            // reconstruct
            Real recon[36];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    Real acc = 0;
                    for (int k = 0; k < n; ++k) {
                        acc += V[i * n + k] * d[k] * V[j * n + k];
                    }
                    recon[i * n + j] = acc;
                }
            }
            EXPECT_LT(matDiff(recon, A, n), kLoose) << "n=" << n;
            // V^T V = I
            Real VtV[36], I[36];
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    Real acc = 0;
                    for (int k = 0; k < n; ++k) {
                        acc += V[k * n + i] * V[k * n + j];
                    }
                    VtV[i * n + j] = acc;
                }
            }
            identity(n, I);
            EXPECT_LT(matDiff(VtV, I, n), kLoose) << "eigenvectors not orthonormal, n=" << n;
        }
    }
}

// --- invertDense: A A^-1 = I for non-degenerate -----------------------------
TEST(LinAlg, InvertDenseInverts) {
    Rng rng(2);
    for (int n : {1, 3, 6}) {
        for (int t = 0; t < 100; ++t) {
            Real A[36];
            rng.spd(n, A, 0.5, 5.0);
            Real Ai[36], prod[36], I[36];
            L::invertDense(A, n, Ai);
            matMat(A, Ai, n, prod);
            identity(n, I);
            EXPECT_LT(matDiff(prod, I, n), kLoose) << "n=" << n;
        }
    }
}

// --- invertDense LOCKS a null direction (returns 0, not 1e14) ---------------
TEST(LinAlg, InvertDenseLocksNullDirection) {
    // 1-DOF: a tiny "inertia" on its own axis must lock to 0.
    Real d = 1e-33, di;
    L::invertDense(&d, 1, &di);
    EXPECT_EQ(di, 0.0) << "near-null 1-DOF must lock to 0, not 1/eps";

    // 3x3 with one ~null eigenvalue: that direction's inverse contributes 0.
    Rng rng(3);
    Real Q[9];
    rng.spd(3, Q, 1.0, 1.0); // orthonormal-ish basis with eqvals 1 (well-cond)
    // build A = sum lambda_k v_k v_k^T with lambda = {2, 3, 1e-20}
    Real d3[3], V[9];
    L::jacobiSymEig(Q, 3, d3, V);
    const Real lam[3] = {2.0, 3.0, 1e-20};
    Real A[9];
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            Real acc = 0;
            for (int k = 0; k < 3; ++k) {
                acc += V[i * 3 + k] * lam[k] * V[j * 3 + k];
            }
            A[i * 3 + j] = acc;
        }
    }
    Real Ai[9];
    L::invertDense(A, 3, Ai);
    // Ai must be finite and bounded (the null direction was dropped, not 1e20)
    for (int i = 0; i < 9; ++i) {
        EXPECT_TRUE(std::isfinite(Ai[i]));
        EXPECT_LT(std::abs(Ai[i]), 1e6) << "null direction was regularized to a huge inverse";
    }
}

// --- tolerance straddle: stiff-but-nonsingular must NOT lock (see 12.6) ------
TEST(LinAlg, InvertDenseToleranceStraddle) {
    // eigenvalue 1e-6 is small but >> 1e-12 lock tol: must invert to ~1e6.
    Real d = 1e-6, di;
    L::invertDense(&d, 1, &di);
    EXPECT_NEAR(di, 1e6, 1.0);
    // eigenvalue 1e-13 < 1e-12: must lock to 0.
    Real d2 = 1e-13, di2;
    L::invertDense(&d2, 1, &di2);
    EXPECT_EQ(di2, 0.0);
}

// --- symSqrt: S*S = A ; symSqrtInv*symSqrt = I ------------------------------
TEST(LinAlg, SymSqrtSquaresToA) {
    Rng rng(4);
    for (int n : {1, 3, 6}) {
        for (int t = 0; t < 100; ++t) {
            Real A[36];
            rng.spd(n, A, 0.3, 5.0);
            Real S[36], SS[36];
            L::symSqrt(A, n, S);
            matMat(S, S, n, SS);
            EXPECT_LT(matDiff(SS, A, n), 1e-11) << "n=" << n;

            Real Sinv[36], prod[36], I[36];
            L::symSqrtInv(A, n, Sinv);
            matMat(Sinv, S, n, prod);
            identity(n, I);
            EXPECT_LT(matDiff(prod, I, n), 1e-11) << "symSqrtInv*symSqrt != I, n=" << n;
        }
    }
}

// --- logDetSymPD: = log det (via eigenvalue product) ------------------------
TEST(LinAlg, LogDetMatchesEigenProduct) {
    Rng rng(5);
    for (int n : {1, 3, 6}) {
        for (int t = 0; t < 100; ++t) {
            Real A[36];
            rng.spd(n, A, 0.4, 4.0);
            const Real ld = L::logDetSymPD(A, n);
            Real d[6], V[36];
            L::jacobiSymEig(A, n, d, V);
            Real ref = 0;
            for (int k = 0; k < n; ++k) {
                ref += std::log(d[k]);
            }
            EXPECT_NEAR(ld, ref, kLoose) << "n=" << n;
        }
    }
}

// --- logDetSymPD pivot clamp: near-singular -> finite, not NaN --------------
TEST(LinAlg, LogDetPivotClampFinite) {
    // a 2x2 that is (numerically) singular
    Real A[4] = {1e-200, 0, 0, 1e-200};
    const Real ld = L::logDetSymPD(A, 2);
    EXPECT_TRUE(std::isfinite(ld)) << "pivot clamp must keep log-det finite";
}

// ============================================================================
//  TestLinearAlgebraOracle.cpp -- VALIDATE the dense linalg kernels against an
//  INDEPENDENT oracle, not against themselves.
//
//  WHY THIS EXISTS. TestLinearAlgebra.cpp checks self-consistency: A*A^-1 == I,
//  S*S == A, V diag V^T == A. Those are necessary (they catch gross errors) but
//  they are not validation against a trusted reference -- a routine can satisfy
//  "A*Ainv==I" to 1e-9 and still carry the wrong convention, mis-order/eigen-sign,
//  or silently fail to converge on a hard spectrum. This file builds matrices
//  whose eigenvalues / eigenvectors / inverse / sqrt / log-det are KNOWN BY
//  CONSTRUCTION (A = Q diag(lambda) Q^T with Q,lambda chosen), so every kernel is
//  checked against the closed-form answer -- an oracle independent of the code
//  under test and requiring no external library.
//
//  CROSS-CHECK STATUS (recorded in the repo, run offline): the same kernels were
//  diffed against LAPACK (scipy dsyev/dpotrf/sqrtm) over well-conditioned,
//  clustered, and degenerate spectra -- agreement to ~1e-15. They diverge from
//  LAPACK *intentionally* in exactly two regimes, which are pinned below as
//  INTENDED behaviour (a naive "compare to LAPACK" oracle would falsely flag
//  them): (1) invertDense LOCKS a near-null eigendirection to 0 instead of
//  inverting it to ~1/eps; (2) logDetSymPD FLOORS a near-zero Cholesky pivot to
//  keep the log finite.
// ============================================================================
#include 
#include 
#include 
#include 

#include "RobotLinearAlgebra.hpp" // robo_linalg::{jacobiSymEig,invertDense,symSqrt,symSqrtInv,logDetSymPD}
#include "TestHelpers.hpp"

using robo::Real;
using rtest::Rng;
namespace L = robo_linalg;

namespace {

// Build A = Q diag(lambda) Q^T (row-major), returning A AND the Q,lambda used.
// Q is a random orthonormal matrix (Gram-Schmidt on a Gaussian), so the spectrum
// (lambda) and eigenspaces (columns of Q) are the GROUND TRUTH for the kernels.
struct Spd {
    int n;
    std::array A{};
    std::array Q{}; // columns = eigenvectors
    std::array lam{};
};

Spd spdFromSpectrum(Rng& rng, const std::vector& lambda) {
    Spd s;
    s.n = static_cast(lambda.size());
    const int n = s.n;
    for (int i = 0; i < n; ++i) {
        s.lam[static_cast(i)] = lambda[static_cast(i)];
    }
    // random orthonormal Q via Gram-Schmidt on a Gaussian (same idea as rng.spd,
    // but here we KEEP Q and lambda instead of discarding them).
    for (int i = 0; i < n * n; ++i) {
        s.Q[static_cast(i)] = rng.gaussian();
    }
    for (int c = 0; c < n; ++c) {
        for (int p = 0; p < c; ++p) {
            Real d = 0;
            for (int r = 0; r < n; ++r) {
                d += s.Q[static_cast(r * n + c)] * s.Q[static_cast(r * n + p)];
            }
            for (int r = 0; r < n; ++r) {
                s.Q[static_cast(r * n + c)] -= d * s.Q[static_cast(r * n + p)];
            }
        }
        Real nrm = 0;
        for (int r = 0; r < n; ++r) {
            nrm += s.Q[static_cast(r * n + c)] * s.Q[static_cast(r * n + c)];
        }
        nrm = std::sqrt(nrm);
        for (int r = 0; r < n; ++r) {
            s.Q[static_cast(r * n + c)] /= nrm;
        }
    }
    // A = Q diag(lam) Q^T
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real acc = 0;
            for (int k = 0; k < n; ++k) {
                acc += s.Q[static_cast(i * n + k)] * s.lam[static_cast(k)]
                       * s.Q[static_cast(j * n + k)];
            }
            s.A[static_cast(i * n + j)] = acc;
        }
    }
    return s;
}

// Reference Q diag(f(lambda)) Q^T into out (the closed-form oracle for inv/sqrt).
template 
void refFromSpectrum(const Spd& s, F f, Real* out) {
    const int n = s.n;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real acc = 0;
            for (int k = 0; k < n; ++k) {
                acc += s.Q[static_cast(i * n + k)] * f(s.lam[static_cast(k)])
                       * s.Q[static_cast(j * n + k)];
            }
            out[i * n + j] = acc;
        }
    }
}

Real maxAbsDiff(const Real* a, const Real* b, int n) {
    Real d = 0;
    for (int i = 0; i < n * n; ++i) {
        d = std::max(d, std::abs(a[i] - b[i]));
    }
    return d;
}

// A spread of well-conditioned spectra (cond <= ~1e3) where every kernel must
// match the closed form to ~kLoose.
const std::vector<std::vector> kGoodSpectra = {
    {2.0},
    {0.5, 3.0, 4.0},
    {0.3, 0.9, 1.7, 2.4, 3.1, 4.8},
    {1.0, 1.0000001, 2.0, 2.0000001, 5.0, 5.0000001}, // clustered
};

} // namespace

// ---------------------------------------------------------------------------
//  O1: jacobiSymEig recovers the KNOWN spectrum (sorted), not just "some
//      decomposition that reconstructs A".
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, EigRecoversKnownSpectrum) {
    Rng rng(0x0E16);
    for (const auto& spec : kGoodSpectra) {
        for (int t = 0; t < 30; ++t) {
            const Spd s = spdFromSpectrum(rng, spec);
            Real d[6], V[36];
            L::jacobiSymEig(s.A.data(), s.n, d, V);
            std::vector got(d, d + s.n), want(spec);
            std::sort(got.begin(), got.end());
            std::sort(want.begin(), want.end());
            for (int k = 0; k < s.n; ++k) {
                EXPECT_NEAR(got[static_cast(k)],
                            want[static_cast(k)],
                            rtest::kLoose)
                    << "n=" << s.n << " k=" << k;
            }
        }
    }
}

// ---------------------------------------------------------------------------
//  O2: invertDense == Q diag(1/lambda) Q^T (the closed-form inverse).
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, InverseMatchesClosedForm) {
    Rng rng(0x1217);
    for (const auto& spec : kGoodSpectra) {
        for (int t = 0; t < 30; ++t) {
            const Spd s = spdFromSpectrum(rng, spec);
            Real got[36], ref[36];
            L::invertDense(s.A.data(), s.n, got);
            refFromSpectrum(
                s,
                [](Real x) {
                    return Real(1) / x;
                },
                ref);
            EXPECT_LT(maxAbsDiff(got, ref, s.n), rtest::kLoose) << "n=" << s.n;
        }
    }
}

// ---------------------------------------------------------------------------
//  O3: symSqrt == Q diag(sqrt(lambda)) Q^T ; symSqrtInv == Q diag(1/sqrt) Q^T.
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, SqrtAndInvSqrtMatchClosedForm) {
    Rng rng(0x5417);
    for (const auto& spec : kGoodSpectra) {
        for (int t = 0; t < 30; ++t) {
            const Spd s = spdFromSpectrum(rng, spec);
            Real gotS[36], refS[36], gotSi[36], refSi[36];
            L::symSqrt(s.A.data(), s.n, gotS);
            L::symSqrtInv(s.A.data(), s.n, gotSi);
            refFromSpectrum(
                s,
                [](Real x) {
                    return std::sqrt(x);
                },
                refS);
            refFromSpectrum(
                s,
                [](Real x) {
                    return Real(1) / std::sqrt(x);
                },
                refSi);
            EXPECT_LT(maxAbsDiff(gotS, refS, s.n), rtest::kLoose) << "sqrt n=" << s.n;
            EXPECT_LT(maxAbsDiff(gotSi, refSi, s.n), rtest::kLoose) << "invsqrt n=" << s.n;
        }
    }
}

// ---------------------------------------------------------------------------
//  O4: logDetSymPD == sum_k ln(lambda_k)  (the exact log-determinant).
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, LogDetEqualsSumLogSpectrum) {
    Rng rng(0x70D7);
    for (const auto& spec : kGoodSpectra) {
        for (int t = 0; t < 30; ++t) {
            const Spd s = spdFromSpectrum(rng, spec);
            Real want = 0;
            for (Real lk : spec) {
                want += std::log(lk);
            }
            EXPECT_NEAR(L::logDetSymPD(s.A.data(), s.n), want, rtest::kLoose) << "n=" << s.n;
        }
    }
}

// ---------------------------------------------------------------------------
//  O5: INTENDED divergence #1 -- invertDense LOCKS a near-null eigendirection.
//  With lambda = {1e-13, 2, 3} the closed-form inverse has a ~1e13 entry; the
//  kernel must instead return the pseudo-inverse Q diag(0, 1/2, 1/3) Q^T (null
//  direction zeroed), staying bounded. This is the deliberate robustness feature
//  a naive LAPACK oracle would wrongly flag as a bug.
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, InvertDenseLocksNullDirection_IntendedDivergence) {
    Rng rng(0x10CC);
    const Spd s = spdFromSpectrum(rng, {1e-13, 2.0, 3.0});
    Real got[9], pinv[9], trueInv[9];
    L::invertDense(s.A.data(), 3, got);
    refFromSpectrum(
        s,
        [](Real x) {
            return x > Real(1e-12) ? Real(1) / x : Real(0);
        },
        pinv); // locked
    refFromSpectrum(
        s,
        [](Real x) {
            return Real(1) / x;
        },
        trueInv); // 1e13 entry

    // (a) bounded -- not the 1e13 true inverse
    for (int i = 0; i < 9; ++i) {
        EXPECT_TRUE(std::isfinite(got[i]));
        EXPECT_LT(std::abs(got[i]), 1e6) << "null direction was inverted, not locked";
    }
    // (b) equals the pseudo-inverse (null direction zeroed), NOT the true inverse
    EXPECT_LT(maxAbsDiff(got, pinv, 3), 1e-6) << "locked inverse must match the pseudo-inverse";
    EXPECT_GT(maxAbsDiff(got, trueInv, 3), 1e6) << "must DIFFER from the true (1e13) inverse on purpose";
}

// ---------------------------------------------------------------------------
//  O6: INTENDED divergence #2 -- logDetSymPD FLOORS a near-zero pivot so the
//  log-det stays finite on a (numerically) singular matrix, rather than -inf.
// ---------------------------------------------------------------------------
TEST(LinAlgOracle, LogDetFloorsSingularPivot_IntendedDivergence) {
    Rng rng(0xF100);
    const Spd s = spdFromSpectrum(rng, {1e-200, 2.0, 3.0});
    const Real ld = L::logDetSymPD(s.A.data(), 3);
    EXPECT_TRUE(std::isfinite(ld)) << "pivot floor must keep ln|det| finite on a singular matrix";
}

// ============================================================================
//  TestMassMatrix.cpp -- COMPOSITION of the articulated-body dynamics on a robot
//  forest: the matrix-free mass operators (M^-1, sqrt(M^-1), sqrt(M)), the
//  kinetic energy, the O(n) log-determinant, and forward dynamics (calcUDot).
//  These are the Robosample analogues of Simbody's matter-subsystem operator
//  tests. No World/forcefield: generalized forces are set directly.
//
//  The strong cross-checks here:
//    * sqrt(M) and sqrt(M^-1) are mutual inverses (Simbody guarantees this).
//    * M^-1 is symmetric (SPD), checked as a bilinear form.
//    * calcUDot at zero velocity equals M^-1 * tau == multiplyByMInv(tau): the
//      forward-dynamics solve and the explicit operator agree.
//    * KE(u = sqrt(M^-1) w) = 1/2 |w|^2 exactly (ties calcKineticEnergy to the
//      sqrt operator: if L L^T = M^-1 then u=Lw gives u^T M u = |w|^2).
//    * calcLogDetM equals -ln det(M^-1) built densely from multiplyByMInv.
// ============================================================================
#include 
#include 
#include 
#include 

#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotLinearAlgebra.hpp" // jacobiSymEig / logDetSymPD (n <= 6 dense kernels)
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::BodySpec;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// A forest with a healthy mix of dof so nu is large and M is non-trivial.
RobotModel makeDynForest(Rng& rng) {
    auto F = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.5);
        s.com_B = rng.vec3(-0.25, 0.25);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        return s;
    };
    std::vector specs;
    specs.push_back(F(0, JointType::Free));      // 1
    specs.push_back(F(1, JointType::Torsion));   // 2
    specs.push_back(F(2, JointType::Torsion));   // 3 (chain)
    specs.push_back(F(0, JointType::Ball));      // 4 (second robot)
    specs.push_back(F(4, JointType::Cylinder));  // 5
    specs.push_back(F(0, JointType::Cartesian)); // 6 (third robot)
    return buildForest(specs);
}

void prep(const RobotModel& m, RobotState& s) {
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeVelocity(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
}

Real dot(const std::vector& a, const std::vector& b) {
    Real s = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        s += a[i] * b[i];
    }
    return s;
}

// log|det A| of a row-major n x n via partial-pivot Gaussian elimination.
Real logDet(std::vector A, int n) {
    Real ld = 0;
    for (int col = 0; col < n; ++col) {
        int piv = col;
        for (int r = col + 1; r < n; ++r) {
            if (std::abs(A[r * n + col]) > std::abs(A[piv * n + col])) {
                piv = r;
            }
        }
        if (piv != col) {
            for (int c = 0; c < n; ++c) {
                std::swap(A[piv * n + c], A[col * n + c]);
            }
        }
        const Real d = A[col * n + col];
        ld += std::log(std::abs(d));
        for (int r = col + 1; r < n; ++r) {
            const Real f = A[r * n + col] / d;
            for (int c = col; c < n; ++c) {
                A[r * n + c] -= f * A[col * n + c];
            }
        }
    }
    return ld;
}

// ---------------------------------------------------------------------------
//  Phase 4: an INDEPENDENT dense M, built from the system Jacobian -- the path
//  the existing suite never takes (M^-1 is only ever checked against udot and
//  against its own sqrt, never against a forward-formed M).
//
//  Column j of the system Jacobian J is V_GB over all bodies when u = e_j (one
//  realizeVelocity per basis vector; V_GB = J(q) u is linear in u). Then, in the
//  spatial-inertia metric,
//      M_ij = sum_b dot( V_GB^(i)[b], Mk_G[b] * V_GB^(j)[b] ).
//  dot(SpatialVec,SpatialVec) = w.tau + v.f is the existing pairing, and
//  Mk_G[b] * V_GB[b] is the spatial momentum. This uses ONLY forward kinematics
//  (realizeVelocity) and the body spatial inertias -- never the articulated-body
//  inverse recursion (multiplyByMInv / P / D / DI) -- so it is a genuinely
//  independent oracle for M.
//
//  The fixture is sized to nu == 6 so the dense SPD kernels jacobiSymEig /
//  logDetSymPD (fixed 6x6 buffers) apply directly.
// ---------------------------------------------------------------------------
RobotModel makeDenseForest(Rng& rng) {
    auto F = [&](int parent, JointType jt) {
        BodySpec s;
        s.parent = parent;
        s.joint = jt;
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.5);
        s.com_B = rng.vec3(-0.25, 0.25);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        return s;
    };
    // nu = 6: Ball (3) + three Torsions (1 each), a single coupled chain.
    return buildForest({F(0, JointType::Ball),
                        F(1, JointType::Torsion),
                        F(2, JointType::Torsion),
                        F(3, JointType::Torsion)});
}

// Build the dense nu x nu mass matrix from the system Jacobian (forward path).
// Requires realizePosition current; leaves u as it found it. Reads Mk_G from the
// state, so it reflects whatever spatial inertias the engine is currently using.
std::vector buildDenseM(const RobotModel& m, RobotState& s) {
    const int n = m.nu, B = m.numBodies;
    const SpatialInertia* Mk = s.Mk_G();

    // capture J's columns: V_GB when u = e_j (position held fixed throughout).
    std::vector<std::vector> col(static_cast(n),
                                             std::vector(static_cast(B)));
    std::vector uSave(s.u(), s.u() + n);
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < n; ++i) {
            s.u()[i] = (i == j) ? Real(1) : Real(0);
        }
        RobotEngine::realizeVelocity(m, s);
        const SpatialVec* V = s.V_GB();
        for (int b = 0; b < B; ++b) {
            col[static_cast(j)][static_cast(b)] = V[b];
        }
    }
    std::copy(uSave.begin(), uSave.end(), s.u());

    std::vector M(static_cast(n * n), 0);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            Real acc = 0;
            for (int b = 1; b < B; ++b) { // body 0 == Ground: no inertia
                const SpatialVec MV = Mk[b] * col[static_cast(j)][static_cast(b)];
                acc += dot(col[static_cast(i)][static_cast(b)], MV);
            }
            M[static_cast(i * n + j)] = acc;
        }
    }
    return M;
}

// smallest eigenvalue of a row-major symmetric n x n (n <= 6) via the in-house
// Jacobi solver -- used to assert M is positive-definite.
Real minEigSym(const std::vector& A, int n) {
    Real d[6], V[36];
    robo_linalg::jacobiSymEig(A.data(), n, d, V);
    Real lo = d[0];
    for (int k = 1; k < n; ++k) {
        lo = std::min(lo, d[k]);
    }
    return lo;
}

} // namespace

// ---------------------------------------------------------------------------
//  D1: sqrt(M) and sqrt(M^-1) are mutual inverses.
// ---------------------------------------------------------------------------
TEST(MassMatrix, SqrtOperatorsAreInverses) {
    Rng rng(0x511);
    RobotModel m = makeDynForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        prep(m, s);
        std::vector w(m.nu), u(m.nu), w2(m.nu);
        for (int i = 0; i < m.nu; ++i) {
            w[i] = rng.gaussian();
        }
        RobotEngine::multiplyBySqrtMInv(m, s, w.data(), u.data()); // u = L w
        RobotEngine::multiplyBySqrtM(m, s, u.data(), w2.data());   // w2 = L^-1 u
        for (int i = 0; i < m.nu; ++i) {
            EXPECT_NEAR(w2[i], w[i], rtest::kLoose) << "i=" << i << " rep " << rep;
        }
    }
}

// ---------------------------------------------------------------------------
//  D2: M^-1 is symmetric: x . M^-1 y == y . M^-1 x.
// ---------------------------------------------------------------------------
TEST(MassMatrix, MInvIsSymmetric) {
    Rng rng(0x522);
    RobotModel m = makeDynForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        prep(m, s);
        std::vector x(m.nu), y(m.nu), Mix(m.nu), Miy(m.nu);
        for (int i = 0; i < m.nu; ++i) {
            x[i] = rng.gaussian();
            y[i] = rng.gaussian();
        }
        RobotEngine::multiplyByMInv(m, s, x.data(), Mix.data());
        RobotEngine::multiplyByMInv(m, s, y.data(), Miy.data());
        EXPECT_NEAR(dot(y, Mix), dot(x, Miy), rtest::kLoose) << "rep " << rep;
        // SPD: x . M^-1 x > 0 for x != 0.
        EXPECT_GT(dot(x, Mix), 0.0) << "rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  D3: forward dynamics at zero velocity equals the explicit M^-1 operator.
//      M udot = tau (bias is zero at u=0)  =>  udot == multiplyByMInv(tau).
// ---------------------------------------------------------------------------
TEST(Dynamics, UDotEqualsMInvForceAtZeroVelocity) {
    Rng rng(0x533);
    RobotModel m = makeDynForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        std::fill(s.u(), s.u() + m.nu, Real(0)); // zero velocity -> no Coriolis/gyro bias

        std::vector tau(m.nu);
        for (int i = 0; i < m.nu; ++i) {
            tau[i] = rng.gaussian();
        }

        // forward dynamics path
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        std::fill(s.bodyForceG(), s.bodyForceG() + m.numBodies, SpatialVec(Vec3(0), Vec3(0)));
        std::copy(tau.begin(), tau.end(), s.mobilityForce());
        RobotEngine::calcUDot(m, s);
        std::vector udot(m.nu);
        std::copy(s.udot(), s.udot() + m.nu, udot.begin());

        // explicit operator path
        std::vector minvTau(m.nu);
        RobotEngine::multiplyByMInv(m, s, tau.data(), minvTau.data());

        for (int i = 0; i < m.nu; ++i) {
            EXPECT_NEAR(udot[i], minvTau[i], rtest::kLoose) << "i=" << i << " rep " << rep;
        }
    }
}

// ---------------------------------------------------------------------------
//  D4: KE(u = sqrt(M^-1) w) = 1/2 |w|^2 exactly. Plus basic KE algebra.
// ---------------------------------------------------------------------------
TEST(MassMatrix, KineticEnergyMatchesSqrtMInv) {
    Rng rng(0x544);
    RobotModel m = makeDynForest(rng);
    RobotState s;
    s.allocateFull(m);
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);

        std::vector w(m.nu), u(m.nu);
        Real wsq = 0;
        for (int i = 0; i < m.nu; ++i) {
            w[i] = rng.gaussian();
            wsq += w[i] * w[i];
        }
        RobotEngine::multiplyBySqrtMInv(m, s, w.data(), u.data());
        std::copy(u.begin(), u.end(), s.u());
        RobotEngine::realizeVelocity(m, s);
        const Real ke = RobotEngine::calcKineticEnergy(m, s);
        EXPECT_NEAR(ke, 0.5 * wsq, rtest::kLoose) << "rep " << rep;

        // KE(-u) == KE(u); KE(2u) == 4 KE(u).
        for (int i = 0; i < m.nu; ++i) {
            s.u()[i] = -u[i];
        }
        RobotEngine::realizeVelocity(m, s);
        EXPECT_NEAR(RobotEngine::calcKineticEnergy(m, s), ke, rtest::kLoose);
        for (int i = 0; i < m.nu; ++i) {
            s.u()[i] = 2 * u[i];
        }
        RobotEngine::realizeVelocity(m, s);
        EXPECT_NEAR(RobotEngine::calcKineticEnergy(m, s), 4 * ke, rtest::kLoose);
    }
}

// ---------------------------------------------------------------------------
//  D5: calcLogDetM == -ln det(M^-1), with M^-1 formed densely from the operator.
//      Cross-checks the O(n) articulated-body determinant against O(n^3) algebra.
// ---------------------------------------------------------------------------
TEST(MassMatrix, LogDetMatchesDenseInverse) {
    Rng rng(0x555);
    RobotModel m = makeDynForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    for (int rep = 0; rep < 10; ++rep) {
        randomizeState(m, s, rng);
        prep(m, s);

        // dense M^-1 by applying the operator to each basis vector.
        std::vector Minv(n * n, 0), e(n, 0), col(n, 0);
        for (int j = 0; j < n; ++j) {
            std::fill(e.begin(), e.end(), Real(0));
            e[j] = 1;
            RobotEngine::multiplyByMInv(m, s, e.data(), col.data());
            for (int i = 0; i < n; ++i) {
                Minv[i * n + j] = col[i];
            }
        }
        const Real lnDetMInv = logDet(Minv, n);
        const Real lnDetM = RobotEngine::calcLogDetM(m, s);
        EXPECT_NEAR(lnDetM, -lnDetMInv, 1e-7) << "rep " << rep;
    }
}

// ===========================================================================
//  Phase 4 -- the independent dense M (forward Jacobian path).
// ===========================================================================

// ---------------------------------------------------------------------------
//  P4.1: M (forward Jacobian assembly) is symmetric and positive-definite.
//        M_ij == M_ji to kLoose; every eigenvalue > 0 (jacobiSymEig).
// ---------------------------------------------------------------------------
TEST(MassMatrixDense, DenseMIsSymmetricSPD) {
    Rng rng(0x4D01);
    RobotModel m = makeDenseForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    ASSERT_LE(n, 6) << "dense SPD kernels assume nu <= 6";
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s); // fixes X_GB, H, Mk_G for the Jacobian build
        const std::vector M = buildDenseM(m, s);

        Real maxAsym = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                maxAsym = std::max(maxAsym, std::abs(M[i * n + j] - M[j * n + i]));
            }
        }
        EXPECT_LT(maxAsym, rtest::kLoose) << "M not symmetric, rep " << rep;

        EXPECT_GT(minEigSym(M, n), 0.0) << "M not positive-definite, rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  P4.2: M * (multiplyByMInv(M e_j)) == e_j for every basis vector. This closes
//        the loop the current suite leaves open: M^-1 is finally checked against
//        an independently-formed M, not against udot or its own sqrt.
// ---------------------------------------------------------------------------
TEST(MassMatrixDense, MTimesMInvIsIdentity) {
    Rng rng(0x4D02);
    RobotModel m = makeDenseForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        const std::vector M = buildDenseM(m, s);     // forward path
        RobotEngine::realizeArticulatedBodyInertias(m, s); // inverse path inputs (P/G/DI)

        for (int j = 0; j < n; ++j) {
            std::vector e(static_cast(n), 0), Mij(static_cast(n), 0);
            e[static_cast(j)] = 1;
            // M e_j
            for (int i = 0; i < n; ++i) {
                Real acc = 0;
                for (int k = 0; k < n; ++k) {
                    acc += M[i * n + k] * e[static_cast(k)];
                }
                Mij[static_cast(i)] = acc;
            }
            // M^-1 (M e_j) must be e_j
            std::vector back(static_cast(n), 0);
            RobotEngine::multiplyByMInv(m, s, Mij.data(), back.data());
            for (int i = 0; i < n; ++i) {
                EXPECT_NEAR(back[static_cast(i)], e[static_cast(i)], rtest::kLoose)
                    << "M^-1 M e_" << j << " != e_" << j << " at " << i << ", rep " << rep;
            }
        }
    }
}

// ---------------------------------------------------------------------------
//  P4.3: calcKineticEnergy == 1/2 u^T M u at random u (the current KE test only
//        checks the sqrt-operator identity, never the quadratic form directly).
// ---------------------------------------------------------------------------
TEST(MassMatrixDense, KineticEnergyMatchesDenseForm) {
    Rng rng(0x4D03);
    RobotModel m = makeDenseForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng); // sets a random u as well
        RobotEngine::realizePosition(m, s);
        const std::vector M = buildDenseM(m, s); // restores u after probing columns

        // 1/2 u^T M u with the state's current u
        const Real* u = s.u();
        Real quad = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                quad += u[i] * M[i * n + j] * u[j];
            }
        }

        RobotEngine::realizeVelocity(m, s); // V_GB at the real u, for calcKineticEnergy
        const Real ke = RobotEngine::calcKineticEnergy(m, s);
        EXPECT_NEAR(ke, 0.5 * quad, rtest::kLoose) << "rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  P4.4: calcLogDetM == logDetSymPD(M), M built FORWARD. Strictly stronger than
//        LogDetMatchesDenseInverse, which builds M^-1 and inverts: here nothing
//        in the oracle touches the articulated-body inverse recursion.
// ---------------------------------------------------------------------------
TEST(MassMatrixDense, LogDetMMatchesDenseM) {
    Rng rng(0x4D04);
    RobotModel m = makeDenseForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        const std::vector M = buildDenseM(m, s);     // forward
        RobotEngine::realizeArticulatedBodyInertias(m, s); // calcLogDetM reads P
        const Real lnDetM = RobotEngine::calcLogDetM(m, s);
        const Real lnDense = robo_linalg::logDetSymPD(M.data(), n);
        EXPECT_NEAR(lnDetM, lnDense, 1e-7) << "rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  P4.5 (FAIL guard): the forward-M and inverse-M paths are now genuinely
//        independent, so a fault injected into ONE of them cannot be cancelled
//        by the other. Build the dense-M oracle from a CLEAN Mk_G, then corrupt
//        one Mk_G block in the state and rebuild the articulated inertias from
//        it. Only the engine's M^-1 / log-det now see the corruption; the oracle
//        still holds the clean M. Both MTimesMInvIsIdentity and LogDetMMatchesDenseM
//        must go red.
//
//        (Corrupting the MODEL mass and re-realizing EVERYTHING would feed the
//        same fault to both paths and they would still agree -- which is exactly
//        why this guard desynchronizes them instead.)
// ---------------------------------------------------------------------------
TEST(MassMatrixDense, CorruptingMkGBreaksBothDensePaths) {
    Rng rng(0x4D05);
    RobotModel m = makeDenseForest(rng);
    RobotState s;
    s.allocateFull(m);
    const int n = m.nu;
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);

    // oracle from the CLEAN spatial inertias
    const std::vector Mclean = buildDenseM(m, s);

    // sanity: clean paths agree (proves the corruption, not a pre-existing gap,
    // is what turns them red below).
    {
        RobotState sc;
        sc.allocateFull(m);
        std::copy(s.q(), s.q() + m.nq, sc.q());
        std::copy(s.u(), s.u() + m.nu, sc.u());
        RobotEngine::realizePosition(m, sc);
        RobotEngine::realizeArticulatedBodyInertias(m, sc);
        Real idErr = 0;
        for (int j = 0; j < n; ++j) {
            std::vector Mij(static_cast(n), 0), back(static_cast(n), 0);
            for (int i = 0; i < n; ++i) {
                Mij[static_cast(i)] = Mclean[i * n + j];
            }
            RobotEngine::multiplyByMInv(m, sc, Mij.data(), back.data());
            for (int i = 0; i < n; ++i) {
                idErr = std::max(idErr, std::abs(back[static_cast(i)] - (i == j ? 1.0 : 0.0)));
            }
        }
        ASSERT_LT(idErr, rtest::kLoose) << "clean paths already disagree; guard would be vacuous";
        ASSERT_NEAR(RobotEngine::calcLogDetM(m, sc), robo_linalg::logDetSymPD(Mclean.data(), n), 1e-7);
    }

    // Corrupt one Mk_G block in the STATE (engine view only), then rebuild the
    // articulated inertias so M^-1 / calcLogDetM are derived from the fault.
    SpatialInertia* Mk = s.Mk_G();
    const int badBody = 2;
    Mk[badBody] = SpatialInertia(Mk[badBody].getMass() * Real(1.7),
                                 Mk[badBody].getMassCenter(),
                                 Mk[badBody].getUnitInertia());
    RobotEngine::realizeArticulatedBodyInertias(m, s);

    // MTimesMInvIsIdentity must FAIL: M_clean^-1_engine M_clean e_j != e_j now.
    Real maxIdErr = 0;
    for (int j = 0; j < n; ++j) {
        std::vector Mij(static_cast(n), 0), back(static_cast(n), 0);
        for (int i = 0; i < n; ++i) {
            Mij[static_cast(i)] = Mclean[i * n + j];
        }
        RobotEngine::multiplyByMInv(m, s, Mij.data(), back.data());
        for (int i = 0; i < n; ++i) {
            maxIdErr = std::max(maxIdErr, std::abs(back[static_cast(i)] - (i == j ? 1.0 : 0.0)));
        }
    }
    EXPECT_GT(maxIdErr, 1e-3) << "corrupting Mk_G did NOT break M*M^-1==I -- paths are not independent";

    // LogDetMMatchesDenseM must FAIL: engine log-det now reflects the fault, the
    // dense oracle does not.
    const Real lnDetM = RobotEngine::calcLogDetM(m, s);
    const Real lnDense = robo_linalg::logDetSymPD(Mclean.data(), n);
    EXPECT_GT(std::abs(lnDetM - lnDense), 1e-3)
        << "corrupting Mk_G did NOT break the log-det match -- paths are not independent";
}

// ============================================================================
//  TestMassProperties.cpp -- port of Simbody SimTKcommon/tests/TestMassProperties.cpp
//
//  WHAT CARRIES OVER. The original exercises four areas: cross products /
//  crossMat (testCrossProduct), rigid-body inertia algebra (testInertia),
//  spatial inertia block form (testSpatialInertia) and articulated inertia
//  block form (testArticulatedInertia). The pieces that map onto the modern
//  value types are ported here as EXACT goldens wherever the original used
//  base-2-representable numbers, plus the block-construction goldens that the
//  current suite only checked indirectly (through the *v action).
//
//  WHAT DOES NOT (and why these are intentionally absent):
//   * 2-D / float / Row variants, det(), v % Mat33 (column/row-wise cross),
//     crossMatSq(), halfCross()/halfCrossDiff() -- the modern port has no
//     generic Mat/Row and no SymMat helper kernels; the dynamics never
//     need them. crossMatSq is recovered below as ~crossMat*crossMat.
//   * Inertia::trace/toMat33/reexpress/shiftFrom*; UnitInertia::shiftToCentroid;
//     SpatialInertia::toSpatialMat/shiftInPlace; ArticulatedInertia::toSpatialMat
//     -- not present. Inertia reexpress/scaling and the Phi-conjugation shift
//     (shift == Phi P ~Phi) are already covered in TestInertia.cpp and
//     TestSpatialAlgebra.cpp, so they are not duplicated here.
// ============================================================================
#include "TestHelpers.hpp"
#include "robot_math.hpp"

using namespace rtest;
using robo::ArticulatedInertia;
using robo::crossMat;
using robo::Inertia;
using robo::Mat33;
using robo::SpatialInertia;
using robo::SymMat33;
using robo::UnitInertia;
using robo::Vec3;

// --- exact cross product & crossMat goldens (testCrossProduct, 3-D part) -----
// All operands are exactly representable in base 2, so these must hold to the
// last bit -- a transposition or sign error in % / crossMat is caught exactly.
TEST(MassProperties, CrossProductExactGolden) {
    const Vec3 w(1.25, 3, -2.5), v(-2.75, 2.125, 5);
    const Vec3 wxv = w % v;
    EXPECT_EQ(wxv[0], 20.3125);
    EXPECT_EQ(wxv[1], 0.625);
    EXPECT_EQ(wxv[2], 10.90625);
    // antisymmetry, exact
    const Vec3 vxw = v % w;
    EXPECT_EQ(vxw[0], -wxv[0]);
    EXPECT_EQ(vxw[1], -wxv[1]);
    EXPECT_EQ(vxw[2], -wxv[2]);
}

TEST(MassProperties, CrossMatExactGolden) {
    const Vec3 w(1.25, 3, -2.5);
    // crossMat(w) == [[0,-wz,wy],[wz,0,-wx],[-wy,wx,0]]
    const Mat33 expected(0, 2.5, 3, -2.5, 0, -1.25, -3, 1.25, 0);
    EXPECT_TRUE(NearMat33(crossMat(w), expected, 0.0)); // exact
}

// crossMat(w) is skew: ~crossMat == -crossMat, so crossMat(-w) == ~crossMat(w).
TEST(MassProperties, CrossMatOfNegatedIsTranspose) {
    Rng rng(10);
    for (int t = 0; t < 200; ++t) {
        const Vec3 w = rng.vec3();
        EXPECT_TRUE(NearMat33(crossMat(Vec3(0, 0, 0) - w), crossMat(w).transpose(), kTight));
    }
}

// crossMatSq(w)*v identity: the original asserts crossMatSq(w)*v == -w%(w%v),
// where crossMatSq == ~crossMat*crossMat == -crossMat^2. Here crossMat^2 * v
// must equal w%(w%v) (the modern engine relies on this in pointMassInertia).
TEST(MassProperties, CrossMatSquaredAction) {
    Rng rng(11);
    for (int t = 0; t < 300; ++t) {
        const Vec3 w = rng.vec3(), v = rng.vec3();
        const Mat33 wx = crossMat(w);
        EXPECT_TRUE(NearVec3(wx * (wx * v), w % (w % v), kTight));
        // crossMatSq == ~wx*wx == -wx^2
        const Mat33 crossMatSq = wx.transpose() * wx;
        EXPECT_TRUE(NearVec3(crossMatSq * v, Vec3(0, 0, 0) - (w % (w % v)), kTight));
    }
}

// --- point-mass inertia == m * crossMatSq(p) (testInertia, shift-from-point) -
// Inertia(p,m) is the load-bearing path the engine uses to build body inertia
// from atom point masses. Pin it to the unit-inertia-of-a-point identity
//      I_point = m (|p|^2 I3 - p p^T) = m * (~crossMat(p) crossMat(p)).
TEST(MassProperties, PointInertiaEqualsCrossMatSquared) {
    Rng rng(12);
    for (int t = 0; t < 300; ++t) {
        const Vec3 p = rng.vec3(-2, 2);
        const Real m = rng.uniform(0.3, 5);
        const Mat33 px = crossMat(p);
        const Mat33 crossMatSq = px.transpose() * px; // = |p|^2 I - p p^T
        const Mat33 got = Inertia(p, m).asSymMat33().full();
        EXPECT_TRUE(NearMat33(got, crossMatSq * m, kTight));
    }
}

// Point inertia is linear in the mass: m * I_unit == I(p,m). The original tests
// Inertia*scalar; the modern Inertia has no scalar operator, so we scale the
// SymMat33 (which does), matching the engine's "unit inertia times mass" path.
TEST(MassProperties, PointInertiaLinearInMass) {
    Rng rng(13);
    for (int t = 0; t < 200; ++t) {
        const Vec3 p = rng.vec3(-2, 2);
        const Real m = rng.uniform(0.3, 5);
        const SymMat33 unit = Inertia(p, Real(1)).asSymMat33();
        const SymMat33 scaled = unit * m;
        const SymMat33 direct = Inertia(p, m).asSymMat33();
        for (int i = 0; i < 6; ++i) {
            EXPECT_NEAR(scaled.elems[static_cast(i)],
                        direct.elems[static_cast(i)],
                        kTight);
        }
    }
}

// --- SpatialInertia block form (testSpatialInertia) -------------------------
// The original reads SpatialInertia::toSpatialMat() and checks the four 3x3
// blocks: (0,0)=m*G, (0,1)=m*crossMat(com), (1,0)=m*~crossMat(com), (1,1)=m*I.
// The modern port has no toSpatialMat(); the spatial inertia's single source of
// truth is ArticulatedInertia(SpatialInertia) (operator* delegates to it), so
// the same block goldens are asserted on its J/F/M blocks.
TEST(MassProperties, SpatialInertiaBlockForm) {
    const Real mass = 1.125; // exact in base 2
    const Vec3 com(0.1, 0.2, 0.25);
    const UnitInertia gyration(1.8, 1.9, 2.1, 0.01, 0.03, 0.02);
    const ArticulatedInertia P(SpatialInertia(mass, com, gyration));

    // (0,0) angular-angular block == mass * gyration
    EXPECT_TRUE(NearMat33(P.angAng.full(), gyration.full() * mass, kTight));
    // (0,1) angular-linear block == mass * crossMat(com)
    EXPECT_TRUE(NearMat33(P.angLin, crossMat(com) * mass, kTight));
    // (1,1) linear-linear block == mass * I3
    EXPECT_TRUE(NearMat33(P.linLin.full(), Mat33::identity() * mass, kTight));
}

// --- ArticulatedInertia ctor block mapping (testArticulatedInertia) ---------
// Pins the (massBlock, momentBlock, inertiaBlock) -> (linLin=M, angLin=F,
// angAng=J) argument order directly, not just through the *v action.
TEST(MassProperties, ArticulatedInertiaBlockMapping) {
    Rng rng(14);
    const SymMat33 mass(rng.uniform(1, 3),
                        rng.uniform(-0.2, 0.2),
                        rng.uniform(1, 3),
                        rng.uniform(-0.2, 0.2),
                        rng.uniform(-0.2, 0.2),
                        rng.uniform(1, 3));
    Mat33 massMoment;
    for (int i = 0; i < 9; ++i) {
        massMoment.elems[static_cast(i)] = rng.uniform(-1, 1);
    }
    const Vec3 q = rng.vec3();
    const SymMat33 inertia = SymMat33::fromSymmetricPart(crossMat(q).transpose() * crossMat(q));

    const ArticulatedInertia abi(mass, massMoment, inertia);
    EXPECT_TRUE(NearMat33(abi.angAng.full(), inertia.full(), kTight)); // (0,0) = inertia (J)
    EXPECT_TRUE(NearMat33(abi.angLin, massMoment, kTight));            // (0,1) = massMoment (F)
    EXPECT_TRUE(NearMat33(abi.linLin.full(), mass.full(), kTight));    // (1,1) = mass (M)
}

// ============================================================================
//  TestPortedMobilizer.cpp -- direct ports of the portable parts of the SimTK
//  mobilizer test files, translated from the SimTK MobilizedBody API to the
//  RobotModel/RobotEngine SoA. What is faithfully portable is ported; what
//  depends on SimTK-only machinery is documented at the bottom of this file
//  rather than faked.
//
//  Ported here:
//   * Acceleration leg of TestMobilizedBody::testCalculationMethods -- the body
//     spatial acceleration A_GB must equal d/dt V_GB (completes the position +
//     velocity legs already in TestMobilizerKinematics).
//   * TestAngleConversions' "one of every mobilizer in a chain" stress config:
//     a deep chain of all ten JointTypes realized at a random configuration,
//     with the kinematic sweeps self-consistent and quaternion blocks unit.
//     (The Euler<->quaternion conversion itself is N/A: the port is quaternion-
//     only; the portable invariant is that renormalizing the quaternion does not
//     move any body, and the q-from-u map round-trips.)
//   * The Weld-mobilizer kernel of TestMobilizedBody::testWeld: a Rigid child
//     moves rigidly with its parent (same angular velocity; origin velocity is
//     the rigid transport of the parent's).
//   * The equivalence pattern shared by TestLoneParticle / testWeld / testGimbal
//     / reaction-force tests: two structurally identical robots in one forest
//     produce identical kinematics and dynamics body-for-body (exercises forest
//     indexing / children-CSR and determinism).
// ============================================================================
#include 
#include 
#include 

#include "RobotBuilders.hpp"
#include "RobotEngine.hpp"
#include "RobotModel.hpp"
#include "RobotState.hpp"
#include "TestHelpers.hpp"

using namespace robo;
using rtest::BodySpec;
using rtest::buildChain;
using rtest::buildForest;
using rtest::randomizeState;
using rtest::Rng;

namespace {

// every JointType, with a legal root (Free) first.
const std::vector kChainAllJoints = {JointType::Free,
                                                JointType::Torsion,
                                                JointType::Slider,
                                                JointType::Cylinder,
                                                JointType::BendStretch,
                                                JointType::Cartesian,
                                                JointType::Ball,
                                                JointType::SphericalCoords,
                                                JointType::FreeLine,
                                                JointType::Rigid};

Vec3 angVelFD(const Rotation& Rp, const Rotation& Rm, Real h) {
    const Mat33 Rdot = (Rp - Rm) * (Real(1) / (Real(2) * h));
    const Mat33 W = Rdot * Rp.transpose();
    const Mat33 W2 = Rdot * Rm.transpose();
    return Vec3(Real(0.5) * (W(2, 1) + W2(2, 1)),
                Real(0.5) * (W(0, 2) + W2(0, 2)),
                Real(0.5) * (W(1, 0) + W2(1, 0)));
}

} // namespace

// ---------------------------------------------------------------------------
//  Acceleration leg of testCalculationMethods: A_GB == d/dt V_GB.
//  We drive the body with a random generalized force, run full forward dynamics
//  to get (udot, A_GB), then finite-difference V_GB along the true trajectory
//  q(t)=q0+t*qdot0, u(t)=u0+t*udot0 (the omitted O(t^2) terms are symmetric and
//  cancel in the central difference).
// ---------------------------------------------------------------------------
TEST(PortedCalculationMethods, BodyAccelerationIsDerivativeOfVelocity) {
    Rng rng(0xACCE1);
    const Real h = 1e-6;
    RobotModel m = buildChain(
        {JointType::Free, JointType::Torsion, JointType::Ball, JointType::Cartesian, JointType::FreeLine},
        rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);
        RobotEngine::realizeArticulatedBodyInertias(m, s);
        std::fill(s.bodyForceG(), s.bodyForceG() + m.numBodies, SpatialVec(Vec3(0), Vec3(0)));
        for (int i = 0; i < m.nu; ++i) {
            s.mobilityForce()[i] = rng.gaussian(0, Real(0.5));
        }
        RobotEngine::calcUDot(m, s);

        std::vector q0(m.nq), u0(m.nu), qdot0(m.nq), udot0(m.nu);
        std::copy(s.q(), s.q() + m.nq, q0.begin());
        std::copy(s.u(), s.u() + m.nu, u0.begin());
        std::copy(s.udot(), s.udot() + m.nu, udot0.begin());
        RobotEngine::calcQDot(m, s, qdot0.data());
        std::vector A0(m.numBodies);
        std::copy(s.A_GB(), s.A_GB() + m.numBodies, A0.begin());

        auto velAt = [&](Real t, std::vector& V) {
            for (int i = 0; i < m.nq; ++i) {
                s.q()[i] = q0[i] + t * qdot0[i];
            }
            for (int i = 0; i < m.nu; ++i) {
                s.u()[i] = u0[i] + t * udot0[i];
            }
            RobotEngine::normalizeQuaternions(m, s);
            RobotEngine::realizePosition(m, s);
            RobotEngine::realizeVelocity(m, s);
            V.assign(s.V_GB(), s.V_GB() + m.numBodies);
        };
        std::vector Vp, Vm;
        velAt(+h, Vp);
        velAt(-h, Vm);

        for (int b = 1; b < m.numBodies; ++b) {
            const Vec3 aAng = (Vp[b][0] - Vm[b][0]) * (Real(1) / (Real(2) * h));
            const Vec3 aLin = (Vp[b][1] - Vm[b][1]) * (Real(1) / (Real(2) * h));
            EXPECT_TRUE(rtest::NearVec3(A0[b][0], aAng, 1e-3)) << "ang body " << b << " rep " << rep;
            EXPECT_TRUE(rtest::NearVec3(A0[b][1], aLin, 1e-3)) << "lin body " << b << " rep " << rep;
        }
        std::copy(q0.begin(), q0.end(), s.q());
        std::copy(u0.begin(), u0.end(), s.u());
    }
}

// ---------------------------------------------------------------------------
//  TestAngleConversions, ported: one of every mobilizer in a chain, random
//  configuration, all kinematics finite & self-consistent; quaternions unit.
// ---------------------------------------------------------------------------
TEST(PortedAngleConversions, AllMobilizerChainRealizesConsistently) {
    Rng rng(0xC4A1);
    const Real h = 1e-6;
    RobotModel m = buildChain(kChainAllJoints, rng);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 15; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);

        // every body transform and velocity is finite.
        for (int b = 1; b < m.numBodies; ++b) {
            for (int k = 0; k < 3; ++k) {
                ASSERT_TRUE(std::isfinite(s.X_GB()[b].p()[k])) << "body " << b;
                ASSERT_TRUE(std::isfinite(s.V_GB()[b][0][k]));
                ASSERT_TRUE(std::isfinite(s.V_GB()[b][1][k]));
            }
            const Mat33 RRt = s.X_GB()[b].R() * s.X_GB()[b].R().transpose();
            EXPECT_TRUE(rtest::NearMat33(RRt, Mat33(Real(1)), 1e-9)) << "orthonormal body " << b;
        }

        // velocity consistency across the whole all-joint chain (FD of X_GB).
        std::vector q0(m.nq), qdot0(m.nq);
        std::copy(s.q(), s.q() + m.nq, q0.begin());
        RobotEngine::calcQDot(m, s, qdot0.data());
        std::vector V0(s.V_GB(), s.V_GB() + m.numBodies);

        auto posAt = [&](Real t, std::vector& X) {
            for (int i = 0; i < m.nq; ++i) {
                s.q()[i] = q0[i] + t * qdot0[i];
            }
            RobotEngine::normalizeQuaternions(m, s);
            RobotEngine::realizePosition(m, s);
            X.assign(s.X_GB(), s.X_GB() + m.numBodies);
        };
        std::vector Xp, Xm;
        posAt(+h, Xp);
        posAt(-h, Xm);
        for (int b = 1; b < m.numBodies; ++b) {
            const Vec3 w_fd = angVelFD(Xp[b].R(), Xm[b].R(), h);
            const Vec3 v_fd = (Xp[b].p() - Xm[b].p()) * (Real(1) / (Real(2) * h));
            EXPECT_TRUE(rtest::NearVec3(V0[b][0], w_fd, 1e-4)) << "ang body " << b << " rep " << rep;
            EXPECT_TRUE(rtest::NearVec3(V0[b][1], v_fd, 1e-4)) << "lin body " << b << " rep " << rep;
        }
        std::copy(q0.begin(), q0.end(), s.q());
    }
}

TEST(PortedAngleConversions, QuaternionNormalizationPreservesConfiguration) {
    // The portable remnant of the Euler<->quaternion round trip: the body layout
    // is a function of the quaternion only through its direction, so renormalizing
    // an already-unit quaternion must not move any body, and q -> u -> q via the
    // engine's own maps is the identity up to renorm.
    Rng rng(0xC4A2);
    RobotModel m = buildChain(kChainAllJoints, rng);
    RobotState s;
    s.allocateFull(m);
    randomizeState(m, s, rng);
    RobotEngine::realizePosition(m, s);
    std::vector before(s.X_GB(), s.X_GB() + m.numBodies);

    // perturb quaternion blocks slightly off the unit sphere, then renormalize.
    for (int qs : m.quaternionQStart) {
        for (int k = 0; k < 4; ++k) {
            s.q()[qs + k] *= Real(1.05);
        }
    }
    RobotEngine::normalizeQuaternions(m, s);
    RobotEngine::realizePosition(m, s);

    for (int b = 1; b < m.numBodies; ++b) {
        EXPECT_TRUE(rtest::NearMat33(s.X_GB()[b].R(), before[b].R(), 1e-9)) << "body " << b;
        EXPECT_TRUE(rtest::NearVec3(s.X_GB()[b].p(), before[b].p(), 1e-9)) << "body " << b;
    }
}

// ---------------------------------------------------------------------------
//  Weld-mobilizer kernel of testWeld: a Rigid child moves rigidly with parent.
//  (The full testWeld -- weld MOBILIZER vs weld CONSTRAINT equivalence under
//  integration -- needs the constraint set + integrator, i.e. "more vertical".)
// ---------------------------------------------------------------------------
TEST(PortedWeld, RigidChildMovesRigidlyWithParent) {
    Rng rng(0x3ED);
    std::vector specs;
    BodySpec root;
    root.parent = 0;
    root.joint = JointType::Free;
    root.X_PF = Transform(rng.rotation(), rng.vec3());
    root.X_BM = Transform(rng.rotation(), rng.vec3());
    specs.push_back(root);
    BodySpec weld;
    weld.parent = 1;
    weld.joint = JointType::Rigid;
    weld.X_PF = Transform(rng.rotation(), rng.vec3());
    weld.X_BM = Transform(rng.rotation(), rng.vec3());
    specs.push_back(weld);
    RobotModel m = buildForest(specs);
    RobotState s;
    s.allocateFull(m);

    for (int rep = 0; rep < 20; ++rep) {
        randomizeState(m, s, rng);
        RobotEngine::realizePosition(m, s);
        RobotEngine::realizeVelocity(m, s);
        const SpatialVec Vp = s.V_GB()[1]; // parent (Free)
        const SpatialVec Vc = s.V_GB()[2]; // welded child
        // same angular velocity.
        EXPECT_TRUE(rtest::NearVec3(Vc[0], Vp[0], rtest::kAlg)) << "rep " << rep;
        // child origin velocity = parent origin velocity + w x r (rigid transport).
        const Vec3 r = s.X_GB()[2].p() - s.X_GB()[1].p();
        const Vec3 vExpected = Vp[1] + (Vp[0] % r);
        EXPECT_TRUE(rtest::NearVec3(Vc[1], vExpected, rtest::kAlg)) << "rep " << rep;
    }
}

// ---------------------------------------------------------------------------
//  Equivalence pattern (TestLoneParticle / testGimbal / reaction tests all
//  compare two equivalent builds): two identical robots in one forest, driven by
//  identical coordinates/forces, agree body-for-body across X_GB, V_GB, A_GB and
//  udot. Exercises forest indexing, the children-CSR, and determinism.
// ---------------------------------------------------------------------------
TEST(PortedEquivalence, IdenticalRobotsAgreeAcrossAllQuantities) {
    Rng rng(0x7011);
    // Two identical 3-body chains as separate robots on Ground.
    const std::vector chain = {JointType::Free, JointType::Torsion, JointType::Ball};

    // Build robot A specs, then duplicate as robot B (same frames/masses).
    std::vector a;
    for (int i = 0; i < (int)chain.size(); ++i) {
        BodySpec s;
        s.parent = (i == 0 ? 0 : i);
        s.joint = chain[i];
        s.X_PF = Transform(rng.rotation(), rng.vec3());
        s.X_BM = Transform(rng.rotation(), rng.vec3());
        s.mass = rng.uniform(0.5, 2.0);
        s.com_B = rng.vec3(-0.2, 0.2);
        s.inertia_B = UnitInertia(rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7), rng.uniform(0.3, 0.7));
        a.push_back(s);
    }
    const int nA = (int)a.size();
    std::vector all = a;
    for (int i = 0; i < nA; ++i) {
        BodySpec s = a[i];
        s.parent = (i == 0 ? 0 : nA + i); // robot B mirrors robot A's topology
        all.push_back(s);
    }
    RobotModel m = buildForest(all);
    RobotState s;
    s.allocateFull(m);

    randomizeState(m, s, rng);
    // copy robot A's coordinates onto robot B so both are driven identically.
    for (int i = 0; i < nA; ++i) {
        const int bA = 1 + i, bB = 1 + nA + i;
        for (int j = 0; j < m.bodyNQ[bA]; ++j) {
            s.q()[m.bodyQIndex[bB] + j] = s.q()[m.bodyQIndex[bA] + j];
        }
        for (int j = 0; j < m.bodyNU[bA]; ++j) {
            s.u()[m.bodyUIndex[bB] + j] = s.u()[m.bodyUIndex[bA] + j];
        }
    }
    RobotEngine::realizePosition(m, s);
    RobotEngine::realizeVelocity(m, s);
    RobotEngine::realizeArticulatedBodyInertias(m, s);
    std::fill(s.bodyForceG(), s.bodyForceG() + m.numBodies, SpatialVec(Vec3(0), Vec3(0)));
    for (int i = 0; i < nA; ++i) {
        const int bA = 1 + i, bB = 1 + nA + i;
        for (int j = 0; j < m.bodyNU[bA]; ++j) {
            const Real f = rng.gaussian(0, 0.5);
            s.mobilityForce()[m.bodyUIndex[bA] + j] = f;
            s.mobilityForce()[m.bodyUIndex[bB] + j] = f;
        }
    }
    RobotEngine::calcUDot(m, s);

    for (int i = 0; i < nA; ++i) {
        const int bA = 1 + i, bB = 1 + nA + i;
        // X_GB depends on the (random, different) frames, so compare the MOTION
        // invariants that must match: mobilizer-frame velocity V_FM and udot.
        for (int j = 0; j < m.bodyNU[bA]; ++j) {
            EXPECT_NEAR(s.udot()[m.bodyUIndex[bA] + j], s.udot()[m.bodyUIndex[bB] + j], rtest::kLoose)
                << "udot body pair " << i << " comp " << j;
        }
        EXPECT_TRUE(rtest::NearVec3(s.V_FM()[bA][0], s.V_FM()[bB][0], rtest::kTight)) << "V_FM ang " << i;
        EXPECT_TRUE(rtest::NearVec3(s.V_FM()[bA][1], s.V_FM()[bB][1], rtest::kTight)) << "V_FM lin " << i;
    }
}

